window.DS3_CHUNK("weapons",[{"id":"ancient-dragon-greatshield","kind":"weapon","name":"Ancient Dragon Greatshield","page":"Ancient Dragon Greatshield","img":"assets/img/Ancient_Dragon_Greatshield.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":87,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":16,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":77,"mag":45,"fire":43,"ltn":46,"dark":45},"stability":54,"weight":6.5,"durability":105,"skill":"Weapon Skill","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"A wooden shield bearing the image of an ancient dragon. Very slowly regenerates HP.\nThe painting is the result of an exquisite but painstaking technique.\nLingering, undying traces of the ancient dragons can still be seen in their descendants, the man-serpents, though they have fallen far from grace.\nSkill: Weapon Skill\nEquipping this shield in the left hand allows one to perform the skill of the right-hand weapon.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"archdragon-peak\">Archdragon Peak<\/a>, behind the first Giant Man Serpent standing on top of a big archway, just before the entrance to the <a data-e=\"ancient-wyvern\">Ancient Wyvern<\/a>'s boss battle.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Ancient_Dragon_Greatshield"},{"id":"anris-straight-sword","kind":"weapon","name":"Anri's Straight Sword","page":"Anri's Straight Sword","img":"assets/img/Anri_s_Straight_Sword.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":117,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":10,"int":0,"fth":0},"scale":{"str":"E","dex":"E","int":"-","fth":"E"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":3,"durability":80,"skill":"Stance","dmg_type":"Standard/Thrust","cast":null,"fp":"-(17/20)","buy":null,"desc":"Sword precious to Anri, another Unkindled. The dullest type of blade found in the ruined land of Astora.\nOnly, it was once the sword of an earnest noble figure, and its attacks are boosted by that elusive, essential property unique to humans: luck.\nSkill: Stance\nWhile in stance, use normal attack to break a foe's guard from below, and strong attack to slash upwards with a forward lunge.","boss_weapon":false,"avail":"<ul><li>Dropped by <a data-e=\"anri-of-astora\">Anri of Astora<\/a> upon killing them.<\/li><li>Found on Anri's corpse in <a data-e=\"smouldering-lake\">Smouldering Lake<\/a> if they are told of <a data-e=\"horace-the-hushed\">Horace's<\/a> location without killing him.<\/li><li>Given to the player by <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> after assisting Anri in defeating <a data-e=\"aldrich-devourer-of-gods\">Aldrich, Devourer of Gods<\/a> in their world.<ul><li>If following this method and Ludleth dies before the player obtains the sword, it will become unobtainable.<\/li><\/ul><\/li><li>Found within Gwyn's honorary tomb in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a> if <a data-e=\"yuria-of-londor\">Yuria of Londor<\/a>'s questline is being followed. After performing the marriage ritual on Anri's corpse, reload the area.<\/li><\/ul>","notes":"<ul><li>Regenerates a constant 2 HP per 2 seconds while equipped.<\/li><li>Inflicts 10% bonus damage against undead enemies.<\/li><li>It cannot be infused, but it is buffable by spells and items.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Anri's_Straight_Sword"},{"id":"aquamarine-dagger","kind":"weapon","name":"Aquamarine Dagger","page":"Aquamarine Dagger","img":"assets/img/Aquamarine_Dagger.webp","wtype":"Dagger","group":"melee","paired":false,"atk":{"phys":67,"mag":67,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":5,"dex":14,"int":18,"fth":null},"scale":{"str":"E","dex":"D","int":"D","fth":"-"},"defs":{"phys":35,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":1.5,"durability":50,"skill":"Crystal Blade","dmg_type":"Slash/Thrust","cast":0,"fp":"8(2/3)","buy":null,"desc":"A dagger fitted with aquamarine crystal.\nEngraved with a prayer in the old tongue to ward off incident. Perhaps it was a parting gift given to one sent off on great travels.\nSkill: Crystal Blade\nRelease magic for the aquamarine crystals, creating a fleeting blue crystal blade, lengthy enough to swing as a straight sword.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"the-dreg-heap\">The Dreg Heap<\/a>. After the initial drop-down from the <a data-e=\"stone-humped-hag\">Stone-humped Hag<\/a>'s perch, there is a path right that leads further down, and a path left that leads to an elevated battlement guarded by a Harald Legion Knight. The item can be found in an area up the stairs behind the Harald Knight.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Aquamarine_Dagger"},{"id":"arbalest","kind":"weapon","name":"Arbalest","page":"Arbalest","img":"assets/img/Arbalest.webp","wtype":"Crossbow","group":"ranged","paired":false,"atk":{"phys":78,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":8,"int":0,"fth":0},"scale":{"str":"-","dex":"-","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":6,"durability":50,"skill":"Tackle","dmg_type":"None","cast":null,"fp":"7(-/-)","buy":null,"desc":"The largest crossbow, and suitably powerful for its size.\nThe bow string is made of metal, requiring great strength to fire.\nSkill: Tackle\nLunge into a shoulder tackle, pushing back enemies to create distance.","boss_weapon":false,"avail":"<ul><li><a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a><ul><li>Dropped by crossbow-wielding Devouts of the Deep.<\/li><li>At the very top of the Cathedral that leads into the rafters, after taking an elevator up from the second shortcut, head down a path along the second flying buttress after crossing from the elevator tower. The Arbalest can be found at the end.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Arbalest"},{"id":"archdeacons-great-staff","kind":"weapon","name":"Archdeacon's Great Staff","page":"Archdeacon's Great Staff","img":"assets/img/Archdeacon_s_Great_Staff.webp","wtype":"Staff","group":"catalyst","paired":false,"atk":{"phys":89,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":0,"int":12,"fth":12},"scale":{"str":"D","dex":"-","int":"-","fth":"A"},"defs":{"phys":25,"mag":25,"fire":10,"ltn":10,"dark":15},"stability":15,"weight":2.5,"durability":55,"skill":"Steady Chant","dmg_type":"Strike","cast":200,"fp":"7(-/-)","buy":null,"desc":"Large staff bestowed upon Archdeacons of the Cathedral of the Deep.\nThe Archdeacon McDonnell's trespass, the sin of channeling faith for sorcery, transformed what was once merely a symbol of ecclesiastic authority into a catalyst for sorceries.\nSkill: Steady Chant\nBoost the strength of sorceries for a very short period. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Obtained by reaching Rank 2 in the <a data-e=\"aldrich-faithful\">Aldrich Faithful<\/a> covenant.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Archdeacon's_Great_Staff"},{"id":"arstors-spear","kind":"weapon","name":"Arstor's Spear","page":"Arstor's Spear","img":"assets/img/Arstor_s_Spear.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":118,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":36,"fst":0},"req":{"str":11,"dex":19,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":6.5,"durability":90,"skill":"Shield Splitter","dmg_type":"Thrust","cast":null,"fp":"16(-/-)","buy":1000,"desc":"One of the curses that festered within the belly of the Greatwood, and a terrible weapon favored by Earl Arstor the Impaler.\nThe spear is enwreathed in rotten, heavily poisonous meat. Defeating foes restores HP.\nSkill: Shield Splitter\nTake a large step forward and make a single focused thrust to puncture enemy shields and inflict damage.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-the-rotted-greatwood\">Soul of the Rotted Greatwood<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> for 1,000 souls.<\/p>","notes":"","from_soul":[{"soul":"soul-of-the-rotted-greatwood","cost":"1,000 souls"}],"url":"https://darksouls.fandom.com/wiki/Arstor's_Spear"},{"id":"astora-greatsword","kind":"weapon","name":"Astora Greatsword","page":"Astora Greatsword","img":"assets/img/Astora_Greatsword.webp","wtype":"Ultra Greatsword","group":"melee","paired":false,"atk":{"phys":132,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":16,"dex":18,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":50,"mag":40,"fire":35,"ltn":35,"dark":40},"stability":40,"weight":8,"durability":75,"skill":"Charge","dmg_type":"Standard/Thrust","cast":null,"fp":"13(-/13)","buy":null,"desc":"This greatsword, bestowed only upon elite knights, is a relic of the ruined land of Astora.\nDesigned for a focus on thrust attacks, this sword is hard and sharp, but not unusually heavy.\nSkill: Charge\nHold sword at waist and charge at foe. Use strong attack while charging to extend the length of the charge.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>.<\/p><p>From the Cleansing Chapel, head toward the graveyard and follow the first pathway on the left. The sword is on a corpse in front of a big tombstone, guarded by a kneeling Reanimated Corpse.<\/p>","notes":"<ul><li>Despite being said to be focused on thrust attacks, its moveset is relatively unchanged for its weapon class. Even stranger, its rolling attacks are overhead slams while many other ultra greatswords have thrusts.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Astora_Greatsword"},{"id":"astora-straight-sword","kind":"weapon","name":"Astora Straight Sword","page":"Astora Straight Sword","img":"assets/img/Astora_Straight_Sword.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":129,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":10,"int":0,"fth":12},"scale":{"str":"D","dex":"E","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":3,"durability":80,"skill":"Stance","dmg_type":"Standard/Thrust","cast":null,"fp":"-(17/20)","buy":null,"desc":"A well-crafted sword named after the ruined land.\nAstora, before its fall, was a land replete with royal blood, and this weapon is both a reminder and heirloom of that era.\nSkill: Stance\nWhile in stance, use normal attack to break a foe's guard from below, and strong attack to slash upwards with a forward lunge.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a>, on a path hidden behind some barrels after passing through the rooftop area, inside a chest after one drops down to the scaffolding below.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Astora_Straight_Sword"},{"id":"avelyn","kind":"weapon","name":"Avelyn","page":"Avelyn (Dark Souls III)","img":"assets/img/Avelyn__Dark_Souls_III.webp","wtype":"Crossbow","group":"ranged","paired":false,"atk":{"phys":64,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":16,"dex":14,"int":0,"fth":0},"scale":{"str":"-","dex":"-","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":7.5,"durability":35,"skill":"Tackle","dmg_type":"None","cast":null,"fp":"7(-/-)","buy":null,"desc":"An extremely rare rapid-firing crossbow.\nFires three successive bolts by means of an elaborate mechanism. Inflict heavy damage by making all three shots count.\nDespite its use as a weapon, this crossbow is also a priceless work of art, and it bears resemblance to a musical instrument.\nSkill: Tackle\nLunge into a shoulder tackle, pushing back enemies to create distance.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"grand-archives\">Grand Archives<\/a>, on top of a bookshelf on the right wing of the building.<\/p><p>Make way through the initial section of the archives and to the third floor, passing by the big wax container and a darkened room. Upon exiting the latter, head straight and either jump or roll diagonally and to the left from the top of the (kickable) ladder to land over a series of bookshelves where the crossbow lies.<\/p><p>It is advisable to equip the <a data-e=\"silvercat-ring\">Silvercat Ring<\/a> or cast <a data-e=\"spook\">Spook<\/a>, and also deal with the <a data-e=\"crystal-sage\">Crystal Sage<\/a> before attempting the jump.<\/p>","notes":"<ul><li>Can be traded with Pickle Pee in exchange for three <a data-e=\"titanite-scale\">Titanite Scales<\/a> (only once per playthrough).<\/li><\/ul><p><br><br><\/p>","url":"https://darksouls.fandom.com/wiki/Avelyn_(Dark_Souls_III)"},{"id":"bandits-knife","kind":"weapon","name":"Bandit's Knife","page":"Bandit's Knife (Dark Souls III)","img":"assets/img/Bandit_s_Knife__Dark_Souls_III.webp","wtype":"Dagger","group":"melee","paired":false,"atk":{"phys":79,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":6,"dex":12,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":35,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":1.5,"durability":50,"skill":"Quickstep","dmg_type":"Slash/Thrust","cast":null,"fp":"5(-/-)","buy":1500,"desc":"A wide single-edged shortsword.\nPrimarily a slicing weapon, but its blade is crafted to cause bleeding, making it a favorite of lowly thieves and bandits.\nSkill: Quickstep\nInstantly step behind or around the side of foes. Especially effective when locked on to target.","boss_weapon":false,"avail":"<ul><li>Starting weapon of the Thief class.<\/li><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 1,500 souls.<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> once she has been given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>.<\/li><\/ul><\/li><li>Dropped by <a data-e=\"greirat-of-the-undead-settlement\">Greirat<\/a> only if the player did not buy any of these knives from him.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Bandit's_Knife_(Dark_Souls_III)"},{"id":"barbed-straight-sword","kind":"weapon","name":"Barbed Straight Sword","page":"Barbed Straight Sword (Dark Souls III)","img":"assets/img/Barbed_Straight_Sword__Dark_Souls_III.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":111,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":11,"dex":11,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":35,"weight":3,"durability":65,"skill":"Stance","dmg_type":"Standard/Thrust","cast":null,"fp":"-(17/20)","buy":null,"desc":"Sword of Longfinger Kirk, the infamous Knight of Thorns. This sword's blade is lined with countless deadly thorns.\nThe thorns of this ominous weapon induce heavy bleeding.\nSkill: Stance\nWhile in stance, use normal attack to break a foe's guard from below, and strong attack to slash upwards with a forward lunge.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>. Guaranteed drop from Longfinger Kirk, who invades as a dark spirit upon reaching the main open area located between the two Giant Slaves.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Barbed_Straight_Sword_(Dark_Souls_III)"},{"id":"bastard-sword","kind":"weapon","name":"Bastard Sword","page":"Bastard Sword (Dark Souls III)","img":"assets/img/Bastard_Sword__Dark_Souls_III.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":138,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":16,"dex":10,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":50,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":35,"weight":8,"durability":75,"skill":"Stomp","dmg_type":"Standard","cast":null,"fp":"12(-/15)","buy":3000,"desc":"A widely-used heavy greatsword normally wielded with two hands.\nBroad horizontal sweeping attacks make this sword effective against multiple enemies, but unwieldy in narrow spaces.\nSkill: Stomp\nUse one's weight to lunge forward with a low stance and increased poise, and follow with a strong attack for an upward slash.","boss_weapon":false,"avail":"<ul><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 3,000 souls.<\/li><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> once she has been given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Bastard_Sword_(Dark_Souls_III)"},{"id":"battle-axe","kind":"weapon","name":"Battle Axe","page":"Battle Axe (Dark Souls III)","img":"assets/img/Battle_Axe__Dark_Souls_III.webp","wtype":"Axe","group":"melee","paired":false,"atk":{"phys":125,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":8,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":4,"durability":80,"skill":"Warcry","dmg_type":"Standard","cast":null,"fp":"20(-/-)","buy":null,"desc":"Easily-wielded axe crafted for battle and inflicting standard damage. It's weight can be used to inflict high damage, but must be used carefully as it leaves its wielder open to retaliation.\nSkill: Warcry\nLet out a spirited warcry that temporarily boosts attack, and enables a special consecutive strong attack.","boss_weapon":false,"avail":"<ul><li>Starting weapon of the Warrior class.<\/li><li><a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a> - A <a data-e=\"deep-gem\">Deep<\/a> Battle Axe is dropped by a Mimic found in a room below the fire breathing wyvern. The player can reach this place unharmed if they time their movements right between the wyvern's fire spewing.<\/li><\/ul>","notes":"<ul><li>The <a data-e=\"deep-gem\">Deep<\/a> Battle Axe found in the <a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a> has no scaling bonuses due to its infusion. However, it will still deal more damage to non-hollow enemies than most other weapons found early in the game.<ul><li>The infusion can be removed by using a <a data-e=\"shriving-stone\">Shriving Stone<\/a> with <a data-e=\"blacksmith-andre\">Blacksmith Andre<\/a>, revealing the weapon's base stats and bonuses.<\/li><\/ul><\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Battle_Axe_(Dark_Souls_III)"},{"id":"black-blade","kind":"weapon","name":"Black Blade","page":"Black Blade","img":"assets/img/Black_Blade.webp","wtype":"Katana","group":"melee","paired":false,"atk":{"phys":122,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":18,"dex":18,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":50,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":35,"weight":6.5,"durability":50,"skill":"Hold","dmg_type":"Slash/Thrust","cast":null,"fp":"-(17/5)","buy":null,"desc":"A short katana wielded by the swordsman and distinguished guest of High Lord Wolnir. This shiny black blade is thick, but shorter than the typical katana.\nThe swordsman was a master of a rare technique, traces of which can be observed in this weapon's strong attack.\nSkill: Hold\nAssume a holding stance to rapidly execute a lunging slash with normal attack, or a deflecting parry with strong attack.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a>, dropped by the Mimic at the end of the upper ledge surrounding the Demon, near the entrance to the <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Black_Blade"},{"id":"black-bow-of-pharis","kind":"weapon","name":"Black Bow of Pharis","page":"Black Bow of Pharis (Dark Souls III)","img":"assets/img/Black_Bow_of_Pharis__Dark_Souls_III.webp","wtype":"Bow","group":"ranged","paired":false,"atk":{"phys":67,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":9,"dex":18,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":3,"durability":65,"skill":"Pharis Triple-shot","dmg_type":"None","cast":null,"fp":"-(7/7)","buy":null,"desc":"A black longbow named after a hero of old. Known for the unusual stance from which it is fired.\nHas a longer range than standard bows, but successful usage requires a trained, dexterous hand.\nSkill: Pharis Triple-shot\nSwiftly nocks three arrows with finesse after drawing the bow, firing them simultaneously.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"farron-keep\">Farron Keep<\/a>. On the far left side of the swamp, three Elder Ghrus can be found congregating near the flame closest to the <a data-e=\"farron-keep\">Keep Ruins<\/a> bonfire. One of them will automatically drop the bow into the player's inventory when killed.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Black_Bow_of_Pharis_(Dark_Souls_III)"},{"id":"black-iron-greatshield","kind":"weapon","name":"Black Iron Greatshield","page":"Black Iron Greatshield (Dark Souls III)","img":"assets/img/Black_Iron_Greatshield__Dark_Souls_III.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":112,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":32,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":69,"fire":83,"ltn":53,"dark":69},"stability":64,"weight":14.5,"durability":150,"skill":"Shield Bash","dmg_type":"Strike","cast":null,"fp":"16(-/-)","buy":null,"desc":"Greatshield made of black iron, deeply feared for its association with Knightslayer Tsorig.\nBlack iron offers high defense, and is particularly effective at warding off fire.\nSkill: Shield Bash\nWithout lowering your guard, strike the enemy with the shield to knock them back or stagger them. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Obtained by defeating Knight Slayer Tsorig by the large lava pool in the <a data-e=\"smouldering-lake\">Demon Ruins<\/a>, beneath the <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Black_Iron_Greatshield_(Dark_Souls_III)"},{"id":"black-knight-glaive","kind":"weapon","name":"Black Knight Glaive","page":"Black Knight Glaive","img":"assets/img/Black_Knight_Glaive.webp","wtype":"Halberd","group":"melee","paired":false,"atk":{"phys":159,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":28,"dex":18,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":30,"ltn":20,"dark":25},"stability":25,"weight":9,"durability":115,"skill":"Spin Sweep","dmg_type":"Standard","cast":null,"fp":"8(-/14)","buy":null,"desc":"Glaive of the black knights who wander the lands. Used to face chaos demons.\nThe unique attack of this glaive greatly reduces enemy poise, reflecting the tremendous size of the enemies that the knights have fearlessly faced.\nSkill: Spin Sweep\nSweep foes in a large spinning motion, and utilize momentum to transition into and overhanded strong attack slash.","boss_weapon":false,"avail":"<p>Located in the <a data-e=\"untended-graves\">Untended Graves<\/a>, in the same arena where <a data-e=\"champion-gundyr\">Champion Gundyr<\/a> is fought.<\/p><p>The halberd can be picked up before starting the boss fight. As one enters the arena, immediately turn right and hug the wall to find it.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Black_Knight_Glaive"},{"id":"black-knight-greataxe","kind":"weapon","name":"Black Knight Greataxe","page":"Black Knight Greataxe (Dark Souls III)","img":"assets/img/Black_Knight_Greataxe__Dark_Souls_III.webp","wtype":"Greataxe","group":"melee","paired":false,"atk":{"phys":201,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":36,"dex":18,"int":0,"fth":0},"scale":{"str":"C","dex":"D","int":"-","fth":"-"},"defs":{"phys":60,"mag":45,"fire":50,"ltn":40,"dark":45},"stability":40,"weight":19.5,"durability":150,"skill":"Warcry","dmg_type":"Standard","cast":null,"fp":"20(-/-)","buy":null,"desc":"Greataxe of the black knights who wander the lands. Used to face chaos demons.\nThe unique attack of this axe greatly reduces enemy poise, reflecting the tremendous size of the enemies that the knights have fearlessly faced.\nSkill: Warcry\nLet out a spirited warcry that temporarily boosts attack, and enables a special consecutive attack.","boss_weapon":false,"avail":"<p>Dropped from the Black Knights who wield the weapon in <a data-e=\"smouldering-lake\">Smouldering Lake<\/a> and <a data-e=\"untended-graves\">Untended Graves<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Black_Knight_Greataxe_(Dark_Souls_III)"},{"id":"black-knight-greatsword","kind":"weapon","name":"Black Knight Greatsword","page":"Black Knight Greatsword (Dark Souls III)","img":"assets/img/Black_Knight_Greatsword__Dark_Souls_III.webp","wtype":"Ultra Greatsword","group":"melee","paired":false,"atk":{"phys":185,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":30,"dex":18,"int":0,"fth":0},"scale":{"str":"C","dex":"D","int":"-","fth":"-"},"defs":{"phys":65,"mag":50,"fire":50,"ltn":45,"dark":50},"stability":45,"weight":16,"durability":115,"skill":"Stomp","dmg_type":"Standard/Thrust","cast":null,"fp":"10(-/16)","buy":null,"desc":"Ultra greatsword wielded by the Black Knights who wander the lands.\nDesigned to face chaos demons.\nThe Black Knights constantly faced foes larger than themselves, and this sword's unique attack greatly reduces enemy poise.\nSkill: Stomp\nUse one's weight to lunge forward with a low stance and increased poise, and follow with a crushing strong attack.","boss_weapon":false,"avail":"<p>Dropped by the Black Knights who wield it. One can be found in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>, another in <a data-e=\"smouldering-lake\">Smouldering Lake<\/a> and two more in the <a data-e=\"untended-graves\">Untended Graves<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Black_Knight_Greatsword_(Dark_Souls_III)"},{"id":"black-knight-shield","kind":"weapon","name":"Black Knight Shield","page":"Black Knight Shield (Dark Souls III)","img":"assets/img/Black_Knight_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":113,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":65,"fire":85,"ltn":52,"dark":63},"stability":60,"weight":7.5,"durability":130,"skill":"Weapon Skill","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Shield of the Black Knights who roam the lands. A flowing canal is chiseled deeply into its face.\nLong ago, the black knights faced the chaos demons, and were charred black, but their shields became highly resistant to fire.\nSkill: Weapon Skill\nEquipping this shield in the left hand allows one to perform the Skill of the right hand weapon.","boss_weapon":false,"avail":"<p>Dropped by Black Knights.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Black_Knight_Shield_(Dark_Souls_III)"},{"id":"black-knight-sword","kind":"weapon","name":"Black Knight Sword","page":"Black Knight Sword (Dark Souls III)","img":"assets/img/Black_Knight_Sword__Dark_Souls_III.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":173,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":20,"dex":18,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":55,"mag":40,"fire":40,"ltn":35,"dark":40},"stability":40,"weight":10,"durability":100,"skill":"Perseverance","dmg_type":"Standard/Thrust","cast":null,"fp":"10(-/-)","buy":null,"desc":"Greatsword wielded by the Black Knights who wander the lands. Designed to face chaos demons.\nThe unique attack of this sword greatly reduces enemy poise, reflecting the tremendous size of the enemies that the knights have fearlessly faced.\nSkill: Perseverance\nRaise sword in the name of the First Lord to temporarily boost poise. Damage reduced while activated.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>, behind an illusory wall.<\/p><p>From the Demon Ruins bonfire, descend two sets of stairs to reach a big room with two Demon Clerics. Turn right and proceed straightforward into a passage at the end. Hit the carved wall at the very end of this passage to reveal a hidden room with a Black Knight slaying a Ghru. The sword can be found inside.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Black_Knight_Sword_(Dark_Souls_III)"},{"id":"blacksmith-hammer","kind":"weapon","name":"Blacksmith Hammer","page":"Blacksmith Hammer (Dark Souls III)","img":"assets/img/Blacksmith_Hammer__Dark_Souls_III.webp","wtype":"Hammer","group":"melee","paired":false,"atk":{"phys":105,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":13,"dex":13,"int":0,"fth":0},"scale":{"str":"C","dex":"-","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":5,"durability":95,"skill":"Perseverance","dmg_type":"Strike","cast":null,"fp":"9(-/-)","buy":null,"desc":"Metal hammer passed down amongst blacksmiths of the shrine. Serves as a strike weapon, but also excels at reducing poise and breaking the guard of a shield.\nOf course, a hammer's true potential is realized in the hands of a blacksmith.\nSkill: Perseverance\nAssume an unfaltering stance of prayer to temporarily boost poise. Damage reduced while activated.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"untended-graves\">Untended Graves<\/a>, lying on <a data-e=\"blacksmith-andre\">Andre<\/a>'s anvil at the spot where he normally can be found in <a data-e=\"firelink-shrine\">Firelink Shrine<\/a>.<\/p>","notes":"<ul><li>Can be traded with Pickle Pee in exchange for a <a data-e=\"titanite-scale\">Titanite Scale<\/a>.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Blacksmith_Hammer_(Dark_Souls_III)"},{"id":"bloodlust","kind":"weapon","name":"Bloodlust","page":"Bloodlust","img":"assets/img/Bloodlust.webp","wtype":"Katana","group":"melee","paired":false,"atk":{"phys":105,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":34,"psn":0,"fst":0},"req":{"str":11,"dex":24,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":45,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":30,"weight":5,"durability":40,"skill":"Bloodlust","dmg_type":"Slash/Thrust","cast":null,"fp":"10(-/-)","buy":null,"desc":"Katana of the old Mound-Maker.\nThe Mound-Maker piled sacrifices upon the altar, but became the final offering himself, leaving this katana as a gift for his dear family.\nSkill: Bloodlust\nStain blade with one's own blood to temporarily grant uncanny sharpness. For one driven by bloodlust, nothing deserves to remain standing.","boss_weapon":false,"avail":"<p>Awarded for attaining Rank 1 in the <a data-e=\"mound-makers\">Mound-makers<\/a> covenant.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Bloodlust"},{"id":"blue-wooden-shield","kind":"weapon","name":"Blue Wooden Shield","page":"Blue Wooden Shield (Dark Souls III)","img":"assets/img/Blue_Wooden_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":77,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":56,"mag":70,"fire":54,"ltn":56,"dark":39},"stability":50,"weight":2.5,"durability":65,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"A wooden shield painted bright blue, the symbol of clerics who have become undead. Close to a small shield in size.\nWooden shields are light, manageable, and offer relatively high magic absorption.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Starting equipment of the <a data-e=\"cleric\">Cleric<\/a> class.<\/li><li>Found on a corpse in the graveyard in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Blue_Wooden_Shield_(Dark_Souls_III)"},{"id":"bonewheel-shield","kind":"weapon","name":"Bonewheel Shield","page":"Bonewheel Shield (Dark Souls III)","img":"assets/img/Bonewheel_Shield__Dark_Souls_III.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":111,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":30,"dex":10,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":63,"fire":59,"ltn":54,"dark":63},"stability":59,"weight":15,"durability":115,"skill":"Wheel of Fate","dmg_type":"Strike","cast":null,"fp":"14(-/-)","buy":null,"desc":"A giant wooden wheel, encircled by spikes and half-melded to a strange skeleton.\nCan serve as a makeshift greatshield, albeit one with great gaps. Its true value is revealed through use of its Skill.\nSkill: Wheel of Fate\nThrust out the wheel and give it a good spin, shredding enemies with the outer lining of spikes.","boss_weapon":false,"avail":"<p>Dropped by Skeleton Wheels in the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a> and the <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Bonewheel_Shield_(Dark_Souls_III)"},{"id":"brigand-axe","kind":"weapon","name":"Brigand Axe","page":"Brigand Axe","img":"assets/img/Brigand_Axe.webp","wtype":"Axe","group":"melee","paired":false,"atk":{"phys":124,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":8,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":3,"durability":75,"skill":"Warcry","dmg_type":"Standard","cast":null,"fp":"20(-/-)","buy":null,"desc":"Axe favored by brigands of a distant land.\nSurprisingly sturdy battle axe that requires more strength to wield than a standard axe.\nSkill: Warcry\nLet out a spirited warcry that temporarily boosts attack.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>, on a corpse behind the the madwoman, between the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a> and <a data-e=\"road-of-sacrifices\">Halfway Fortress<\/a> bonfires.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Brigand_Axe"},{"id":"brigand-twindaggers","kind":"weapon","name":"Brigand Twindaggers","page":"Brigand Twindaggers","img":"assets/img/Brigand_Twindaggers.webp","wtype":"Dagger","group":"melee","paired":true,"atk":{"phys":70,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":18,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":35,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":2.5,"durability":50,"skill":"Quickstep","dmg_type":"Slash/Thrust","cast":null,"fp":"5(-/-)","buy":null,"desc":"These paired daggers are the preferred weapons of the brigands of a distant land.\nWhen two-handed, the wielder holds a blade in each hand, allowing for divergent attacks that include left handed moves.\nSkill: Quickstep\nInstantly step behind or around the side of foes. Especially effective when locked on to target.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>, on a corpse behind where the madwoman spawns.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Brigand_Twindaggers"},{"id":"broadsword","kind":"weapon","name":"Broadsword","page":"Broadsword (Dark Souls III)","img":"assets/img/Broadsword__Dark_Souls_III.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":117,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":10,"int":0,"fth":0},"scale":{"str":"C","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":3,"durability":80,"skill":"Stance","dmg_type":"Standard","cast":null,"fp":"-(17/20)","buy":null,"desc":"A straight sword with a broad blade designed for slashing.\nA large sweeping attack makes this effective against crowds, but is prone to deflection from walls in narrow spaces.\nSkill: Stance\nWhile in stance, use normal attack to break a foe's guard from below, and strong attack to slash upwards with a forward lunge.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a>, beyond the <a data-e=\"high-wall-of-lothric\">Tower on the Wall<\/a> bonfire, in the room where <a data-e=\"greirat-of-the-undead-settlement\">Greirat<\/a>'s <a data-e=\"cell-key\">cell key<\/a> is found. The corpse holding it is found in a small room in which a longsword-wielding hollow is found guarding it.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Broadsword_(Dark_Souls_III)"},{"id":"broken-straight-sword","kind":"weapon","name":"Broken Straight Sword","page":"Broken Straight Sword (Dark Souls III)","img":"assets/img/Broken_Straight_Sword__Dark_Souls_III.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":70,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":8,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":30,"weight":1,"durability":30,"skill":"Stance","dmg_type":"Standard","cast":null,"fp":"-(17/20)","buy":null,"desc":"A straight sword with a broken blade.\nA weapon with no exceptional qualities. Only a mad Hollow would choose to fight with this.\nSkill: Stance\nWhile in stance, use normal attack to break a foe's guard from below, and strong attack to slash upwards with a forward lunge. Only, neither move will appear very impressive with a broken sword.","boss_weapon":false,"avail":"<ul><li>Dropped by Hollow Soldiers and Praying Hollow Soldiers.<\/li><li><a data-e=\"cemetery-of-ash\">Cemetery of Ash<\/a><ul><li>Found next to a gravestone after the Iudex Gundyr bonfire.<\/li><\/ul><\/li><li><a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a><ul><li>Dropped by Sage's Prentices.<\/li><\/ul><\/li><li><a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a><ul><li>Dropped by Devout Bombers.<\/li><\/ul><\/li><\/ul>","notes":"<ul><li>It shares the same weapon skill as the <a data-e=\"long-sword\">Long Sword<\/a>, but with much lower reach and overall reduced effectiveness.<\/li><li>Despite the name, it appears to be a Long Sword with most of the blade broken off.<\/li><li>It has one of the lowest sell values in the entire game, beaten only by certain consumables like <a data-e=\"cracked-red-eye-orb\">Cracked Red Eye Orbs<\/a>.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Broken_Straight_Sword_(Dark_Souls_III)"},{"id":"buckler","kind":"weapon","name":"Buckler","page":"Buckler (Dark Souls III)","img":"assets/img/Buckler__Dark_Souls_III.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":67,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":7,"dex":13,"int":0,"fth":0},"scale":{"str":"E","dex":"-","int":"-","fth":"-"},"defs":{"phys":49,"mag":35,"fire":30,"ltn":11,"dark":28},"stability":33,"weight":1.5,"durability":30,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":2000,"desc":"A very small round metal shield.\nIt features a large central protrusion designed for parrying attacks.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 2,000 souls.<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for the same price once she is given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Buckler_(Dark_Souls_III)"},{"id":"butcher-knife","kind":"weapon","name":"Butcher Knife","page":"Butcher Knife (Dark Souls III)","img":"assets/img/Butcher_Knife__Dark_Souls_III.webp","wtype":"Axe","group":"melee","paired":false,"atk":{"phys":95,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":24,"dex":0,"int":0,"fth":0},"scale":{"str":"A","dex":"-","int":"-","fth":"-"},"defs":{"phys":60,"mag":40,"fire":30,"ltn":30,"dark":40},"stability":35,"weight":7,"durability":75,"skill":"Sharpen","dmg_type":"Slash","cast":null,"fp":"18(-/-)","buy":null,"desc":"Butcher's knife with an oddly large blade wielded by the madwoman haunting the Road of Sacrifices.\nSquarely-landed hits restore HP.\nBack in the Undead Settlement, the woman acquired a taste for human flesh, of which she took glee in partaking.\nSkill: Sharpen\nSharpening the blade increases HP restored with each successful hit.","boss_weapon":false,"avail":"<p>Dropped by Isabella the Mad in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Butcher_Knife_(Dark_Souls_III)"},{"id":"caduceus-round-shield","kind":"weapon","name":"Caduceus Round Shield","page":"Caduceus Round Shield (Dark Souls III)","img":"assets/img/Caduceus_Round_Shield__Dark_Souls_III.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":69,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":0,"int":0,"fth":0},"scale":{"str":"E","dex":"-","int":"-","fth":"-"},"defs":{"phys":52,"mag":63,"fire":46,"ltn":36,"dark":25},"stability":39,"weight":1.5,"durability":55,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Standard round wooden shield. It is decorated with twin snakes, an ancient symbol of the Great Swamp.\nWooden shields are light, manageable, and offer relatively high magic absorption.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Starting equipment for the Pyromancer class.<\/li><li>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>. At the junction with the Peasant Hollows and Evangelist praying before the burning tree, turn right and traverse through the stable areas. After defeating the <a data-e=\"flamberge\">Flamberge<\/a>-wielding Thrall and opening the door, turn right and the shield can be found on a corpse.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Caduceus_Round_Shield_(Dark_Souls_III)"},{"id":"caestus","kind":"weapon","name":"Caestus","page":"Caestus (Dark Souls III)","img":"assets/img/Caestus__Dark_Souls_III.webp","wtype":"Fist","group":"melee","paired":false,"atk":{"phys":91,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":5,"dex":8,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":0.5,"durability":60,"skill":"Perseverance","dmg_type":"Strike","cast":null,"fp":"7(-/-)","buy":null,"desc":"A fistfighter's weapon made from thick straps of leather studded with iron rivets.\nWhen two handed, caesti are equipped in each hand.\nSkill: Perseverance\nCross arms in front of the body to temporarily boost poise. Damage reduced while activated.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, on a corpse in the sewers with several Hound Rats and one Giant Hound Rat, between <a data-e=\"undead-settlement\">Cliff Underside<\/a> and <a data-e=\"undead-settlement\">Dilapidated Bridge<\/a> bonfires.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Caestus_(Dark_Souls_III)"},{"id":"caithas-chime","kind":"weapon","name":"Caitha's Chime","page":"Caitha's Chime (Dark Souls III)","img":"assets/img/Caitha_s_Chime__Dark_Souls_III.webp","wtype":"Sacred Chime","group":"catalyst","paired":false,"atk":{"phys":74,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":3,"dex":0,"int":12,"fth":12},"scale":{"str":"E","dex":"-","int":"C","fth":"B"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":15,"dark":20},"stability":10,"weight":0.5,"durability":45,"skill":"Gentle Prayer","dmg_type":"Strike","cast":100,"fp":"13(-/-)","buy":null,"desc":"Sacred chime blessed by Caitha, goddess of tears. Rare even amongst Carim clerics.\nAffected by intelligence, a rare thing for miracle catalysts, and also agreeable with miracles that lean towards the Dark. Its existence is concealed in the name of the Archbishop, as it is anathema.\nSkill: Gentle Prayer\nRecovers HP for a period of time, albeit extremely slowly. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"lothric-castle\">Lothric Castle<\/a>. In the small chapel prior to encountering the <a data-e=\"dragonslayer-armour\">Dragonslayer Armour<\/a>, there is an exit on the opposite side and a drop-down from a broken railing. Dropping down below, the chime can be found on a corpse lying above a group of Lothric Knights, in the area just past the moat guarded by the two Lothric Wyverns.<\/p>","notes":"<ul><li>Can be traded with Pickle Pee in exchange for the <a data-e=\"hello-carving\">Help me! Carving<\/a> (only once per playthrough).<\/li><\/ul><p><br><br><\/p>","url":"https://darksouls.fandom.com/wiki/Caitha's_Chime_(Dark_Souls_III)"},{"id":"canvas-talisman","kind":"weapon","name":"Canvas Talisman","page":"Canvas Talisman (Dark Souls III)","img":"assets/img/Canvas_Talisman__Dark_Souls_III.webp","wtype":"Talisman","group":"catalyst","paired":false,"atk":{"phys":52,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":4,"dex":0,"int":0,"fth":14},"scale":{"str":"D","dex":"-","int":"-","fth":"B"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":15,"dark":15},"stability":10,"weight":0.5,"durability":55,"skill":"Unfaltering Prayer","dmg_type":"Strike","cast":112,"fp":"8(-/-)","buy":3000,"desc":"Medium for casting miracles of the Gods. Canvas talismans are austere items carried by heralds.\nEquip a talisman or a sacred chime to cast miracles. Miracles must be attuned at a bonfire before use.\nSkill: Unfaltering Prayer\nTemporarily increase poise while casting miracles, preventing enemy attacks from interrupting prayer. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 3,000 souls once she has been given the <a data-e=\"paladins-ashes\">Paladin's Ashes<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Canvas_Talisman_(Dark_Souls_III)"},{"id":"carthus-curved-greatsword","kind":"weapon","name":"Carthus Curved Greatsword","page":"Carthus Curved Greatsword","img":"assets/img/Carthus_Curved_Greatsword.webp","wtype":"Curved Greatsword","group":"melee","paired":false,"atk":{"phys":125,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":36,"psn":0,"fst":0},"req":{"str":18,"dex":22,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":50,"mag":40,"fire":35,"ltn":35,"dark":40},"stability":40,"weight":10.5,"durability":85,"skill":"Spin Slash","dmg_type":"Slash","cast":null,"fp":"9(-/13)","buy":null,"desc":"Large curved sword wielded by swordsmen of Carthus.\nThe lightest of the curved greatswords. Crafted to cause bleeding.\nSkill: Spin Slash\nSlice into foes with a large spinning motion, and continue spinning to transition into strong attack.","boss_weapon":false,"avail":"<p>Dropped by the Skeleton Swordsmen who wield them in the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Carthus_Curved_Greatsword"},{"id":"carthus-curved-sword","kind":"weapon","name":"Carthus Curved Sword","page":"Carthus Curved Sword","img":"assets/img/Carthus_Curved_Sword.webp","wtype":"Curved Sword","group":"melee","paired":false,"atk":{"phys":105,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":15,"dex":18,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":55,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":35,"weight":5.5,"durability":80,"skill":"Spin Slash","dmg_type":"Slash","cast":null,"fp":"6(-/12)","buy":null,"desc":"Curved sword of Carthus swordsmen.\nThis weapon's thick, heavy blade is crafted to cause bleeding, and requires ample strength and dexterity to wield effectively, suggesting that the swordsmen of Carthus were amongst the mightiest.\nSkill: Spin Slash\nSlice into foes with a large spinning motion, and continue spinning to transition into strong attack.","boss_weapon":false,"avail":"<p>Dropped by Skeleton Swordsmen in the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Carthus_Curved_Sword"},{"id":"carthus-shield","kind":"weapon","name":"Carthus Shield","page":"Carthus Shield","img":"assets/img/Carthus_Shield.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":56,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":61,"mag":45,"fire":21,"ltn":56,"dark":52},"stability":45,"weight":2.5,"durability":80,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"The tattered remnants of a leather shield used by a Carthus swordsman.\nThe swordsmen of Carthus were particularly agile, and this common shield is surprisingly light for one of medium size.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Dropped by Skeleton Swordsmen in the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Carthus_Shield"},{"id":"carthus-shotel","kind":"weapon","name":"Carthus Shotel","page":"Carthus Shotel","img":"assets/img/Carthus_Shotel.webp","wtype":"Curved Sword","group":"melee","paired":false,"atk":{"phys":106,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":12,"dex":19,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":40,"mag":35,"fire":25,"ltn":25,"dark":35},"stability":30,"weight":3,"durability":55,"skill":"Spin Slash","dmg_type":"Slash","cast":null,"fp":"5(-/12)","buy":null,"desc":"Strangely curved sword crafted to cause bleeding, wielded by Carthus swordsmen.\nShaped to sneak around the defenses of shields, this sword requires ample dexterity to wield effectively.\nSkill: Spin Slash\nSlice into foes with a large spinning motion, and continue spinning to transition into strong attack.","boss_weapon":false,"avail":"<p>Dropped by the Skeleton Swordsmen who wield them in the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Carthus_Shotel"},{"id":"cathedral-knight-greatshield","kind":"weapon","name":"Cathedral Knight Greatshield","page":"Cathedral Knight Greatshield","img":"assets/img/Cathedral_Knight_Greatshield.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":112,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":32,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":63,"fire":60,"ltn":54,"dark":83},"stability":67,"weight":15.5,"durability":150,"skill":"Shield Bash","dmg_type":"Strike","cast":null,"fp":"16(-/-)","buy":null,"desc":"A heavy iron shield used by the knights of the Cathedral of the Deep. The blessings of the Cathedral have granted it high dark absorption.\nThe face of the shield is decorated with the emblem of an old king of Lothric: a bold image of a great bird gazing skywards.\nSkill: Shield Bash\nWithout lowering your guard, strike the enemy with the shield to knock them back or stagger them. Works while equipped in either hand.","boss_weapon":false,"avail":"<p><a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a><\/p><ul><li>Dropped by <a data-e=\"heavy-crossbow\">crossbow<\/a>- and <a data-e=\"great-mace\">mace<\/a>-wielding Cathedral Knights.<\/li><\/ul><p><a data-e=\"consumed-kings-garden\">Consumed King's Garden<\/a><\/p><ul><li>Dropped by <a data-e=\"great-mace\">mace<\/a>-wielding Consumed King's Knights.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Cathedral_Knight_Greatshield"},{"id":"cathedral-knight-greatsword","kind":"weapon","name":"Cathedral Knight Greatsword","page":"Cathedral Knight Greatsword","img":"assets/img/Cathedral_Knight_Greatsword.webp","wtype":"Ultra Greatsword","group":"melee","paired":false,"atk":{"phys":149,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":26,"dex":10,"int":0,"fth":0},"scale":{"str":"C","dex":"E","int":"-","fth":"-"},"defs":{"phys":60,"mag":50,"fire":40,"ltn":40,"dark":50},"stability":45,"weight":15,"durability":120,"skill":"Stomp","dmg_type":"Strike","cast":null,"fp":"10(-/20)","buy":null,"desc":"Ultra greatsword wielded by the knights of the Cathedral of the Deep.\nHighly destructive if intolerably heavy.\nIts blade is flattened for use as a strike weapon, but the point at the end allows for thrusting.\nSkill: Stomp\nUse one's weight to lunge forward with a low stance and increased poise, and follow with a strong attack for a spinning slash.","boss_weapon":false,"avail":"<p><a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a><\/p><ul><li>Dropped by Cathedral Knights who wield them.<\/li><\/ul><p><a data-e=\"consumed-kings-garden\">Consumed King's Garden<\/a><\/p><ul><li>Dropped by Consumed King's Knights who wield them.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Cathedral_Knight_Greatsword"},{"id":"chaos-blade","kind":"weapon","name":"Chaos Blade","page":"Chaos Blade (Dark Souls III)","img":"assets/img/Chaos_Blade__Dark_Souls_III.webp","wtype":"Katana","group":"melee","paired":false,"atk":{"phys":103,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":34,"psn":0,"fst":0},"req":{"str":16,"dex":14,"int":0,"fth":0},"scale":{"str":"E","dex":"A","int":"-","fth":"-"},"defs":{"phys":45,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":30,"weight":6,"durability":35,"skill":"Hold","dmg_type":"Slash/Thrust","cast":null,"fp":"-(17/5)","buy":null,"desc":"A cursed sword of unknown origin bearing uncanny streaks on its blade.\nAttacks also damage its wielder.\nThe sword is not unlike a thing misshapen, granted life, but never welcome in this world. In other words, chaos itself.\nSkill: Hold\nAssume a holding stance to rapidly execute a lunging slash with normal attack, or a deflecting parry with strong attack.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"untended-graves\">Untended Graves<\/a>, uphill the left path before entering the remains of <a data-e=\"firelink-shrine\">Firelink Shrine<\/a>, on the same spot where the Sword Master was encountered in the <a data-e=\"cemetery-of-ash\">Cemetery of Ash<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Chaos_Blade_(Dark_Souls_III)"},{"id":"claw","kind":"weapon","name":"Claw","page":"Claw (Dark Souls III)","img":"assets/img/Claw__Dark_Souls_III.webp","wtype":"Claw","group":"melee","paired":false,"atk":{"phys":86,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":6,"dex":14,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":1.5,"durability":60,"skill":"Leaping Slash","dmg_type":"Slash/Thrust","cast":null,"fp":"10(-/-)","buy":null,"desc":"Weapon favored by intelligencers of an eastern land. The lacerations it inflicts do not mend easily.\nWhen two-handed, claws are equipped to each hand.\nSkill: Leaping Slash\nPerform a forward leaping slash at the opponent's head. When successful, functions as a head shot, inflicting heavy damage.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"consumed-kings-garden\">Consumed King's Garden<\/a>, beneath the central platform where a Consumed King's Knight stands guard and several Rotten Slugs lurk about.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Claw_(Dark_Souls_III)"},{"id":"claymore","kind":"weapon","name":"Claymore","page":"Claymore (Dark Souls III)","img":"assets/img/Claymore__Dark_Souls_III.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":138,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":16,"dex":13,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":50,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":35,"weight":9,"durability":75,"skill":"Stance","dmg_type":"Standard/Thrust","cast":null,"fp":"-(17/20)","buy":null,"desc":"An unusually large and heavy greatsword normally wielded with two hands.\nThis highly versatile weapon can be swung broadly or thrusted.\nSkill: Stance\nWhile in stance, use normal attacks to break a foe's guard from below, and strong attack to slash upwards with a forward lunge.","boss_weapon":false,"avail":"<ul><li><a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a><ul><li>Found at the end of the upper path where the fire-breathing Lothric Wyvern is encountered.<\/li><\/ul><\/li><li><a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a><ul><li>Dropped by the Irithyllian Slaves who wield them.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Claymore_(Dark_Souls_III)"},{"id":"clerics-candlestick","kind":"weapon","name":"Cleric's Candlestick","page":"Cleric's Candlestick","img":"assets/img/Cleric_s_Candlestick.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":70,"mag":77,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":12,"int":0,"fth":12},"scale":{"str":"D","dex":"D","int":"C","fth":"-"},"defs":{"phys":40,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":2,"durability":65,"skill":"Guiding Light","dmg_type":"Standard/Thrust","cast":100,"fp":"5(-/-)","buy":null,"desc":"Candle stick used as both sword and catalyst. Used for worship by the Deacons of the Deep.\nThe deacons, under the guidance of Archdeacon McDonnell, became both clergymen and sorcerers.\nSkill: Guiding Light\nA candle provides a temporary source of light which reveals additional guidance.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-the-deacons-of-the-deep\">Soul of the Deacons of the Deep<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"<ul><li>Despite being reinforced by regular Titanite, it cannot be buffed or infused.<\/li><li>It is the only soul-transposed weapon to not be upgraded with <a data-e=\"titanite-scale\">Titanite Scale<\/a>.<\/li><\/ul>","from_soul":[{"soul":"soul-of-the-deacons-of-the-deep","cost":null}],"url":"https://darksouls.fandom.com/wiki/Cleric's_Candlestick"},{"id":"clerics-sacred-chime","kind":"weapon","name":"Cleric's Sacred Chime","page":"Cleric's Sacred Chime (Dark Souls III)","img":"assets/img/Cleric_s_Sacred_Chime__Dark_Souls_III.webp","wtype":"Sacred Chime","group":"catalyst","paired":false,"atk":{"phys":52,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":3,"dex":0,"int":0,"fth":14},"scale":{"str":"D","dex":"-","int":"-","fth":"A"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":15,"dark":15},"stability":10,"weight":0.5,"durability":50,"skill":"Gentle Prayer","dmg_type":"Strike","cast":100,"fp":"13(-/-)","buy":null,"desc":"Sacred chime for casting miracles of the Gods. Chimes such as these are often given to clerics who become Undead.\nEquip a talisman or a sacred chime to cast miracles. Miracles must be attuned at a bonfire before use.\nSkill: Gentle Prayer\nRecovers HP for a period of time, albeit extremely slowly. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Starting equipment of the Cleric class.<\/li><li>Drops from the Gravetender Hollows in the <a data-e=\"cemetery-of-ash\">Cemetery of Ash<\/a> and <a data-e=\"untended-graves\">Untended Graves<\/a>.<\/li><\/ul>","notes":"<ul><li>Can be traded with Pickle Pee in exchange for the <a data-e=\"hello-carving\">Help me! Carving<\/a> (only once per playthrough), provided that it has not been upgraded.<\/li><\/ul><p><br><br><\/p>","url":"https://darksouls.fandom.com/wiki/Cleric's_Sacred_Chime_(Dark_Souls_III)"},{"id":"club","kind":"weapon","name":"Club","page":"Club (Dark Souls III)","img":"assets/img/Club__Dark_Souls_III.webp","wtype":"Hammer","group":"melee","paired":false,"atk":{"phys":108,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":0,"int":0,"fth":0},"scale":{"str":"C","dex":"-","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":35,"ltn":30,"dark":25},"stability":30,"weight":2.5,"durability":90,"skill":"Warcry","dmg_type":"Strike","cast":null,"fp":"20(-/-)","buy":null,"desc":"A simple wooden club. Characterized by savage leaping attacks.\nThis crude bladeless strike weapon is effective against most foes, and can break the guard of a shield.\nSkill: Warcry\nLet out a spirited warcry that temporarily boosts attack, and enabled a special consecutive strong attack.","boss_weapon":false,"avail":"<ul><li>Starting weapon of the <a data-e=\"deprived\">Deprived<\/a> class.<\/li><li>Found in the <a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a>, located on the upper path where the fire-breathing wyvern is encountered.<\/li><\/ul>","notes":"<p>Although <a data-e=\"raw-gem\">Raw<\/a> infusions are optimal at low Strength, it is always worth infusing the Club with a <a data-e=\"heavy-gem\">Heavy Gem<\/a> over leaving it uninfused, even at the base requirement of 10 Strength.<\/p>","url":"https://darksouls.fandom.com/wiki/Club_(Dark_Souls_III)"},{"id":"composite-bow","kind":"weapon","name":"Composite Bow","page":"Composite Bow (Dark Souls III)","img":"assets/img/Composite_Bow__Dark_Souls_III.webp","wtype":"Bow","group":"ranged","paired":false,"atk":{"phys":73,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":12,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":3.5,"durability":65,"skill":"Rapid Fire","dmg_type":"None","cast":null,"fp":"-(4/4)","buy":3500,"desc":"Composite short bow emphasizing power. Its size allows for quick shots.\nThough more powerful than standard bows, it also requires more strength of the user, and its range is short.\nSkill: Rapid Fire\nSwiftly nocks arrows with finesse after drawing the bow, allowing for consecutive shots.","boss_weapon":false,"avail":"<p>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 3,500 souls once she has been given the <a data-e=\"dreamchasers-ashes\">Dreamchaser's Ashes<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Composite_Bow_(Dark_Souls_III)"},{"id":"corvian-greatknife","kind":"weapon","name":"Corvian Greatknife","page":"Corvian Greatknife","img":"assets/img/Corvian_Greatknife.webp","wtype":"Dagger","group":"melee","paired":false,"atk":{"phys":93,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":16,"int":0,"fth":0},"scale":{"str":"E","dex":"E","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":2.5,"durability":55,"skill":"Blind Spot","dmg_type":"Slash/Thrust","cast":null,"fp":"10(-/-)","buy":null,"desc":"Dagger of the unwanted, those guided by heretical storytellers.\nA rather large dagger with a powerful attack, but this transparent attempt to intimidate foes reveals much about its owner's fears.\nSkill: Blind Spot\nUse against shielded foes to break through their guard by attacking from the side.","boss_weapon":false,"avail":"<p>Dropped by Corvians in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>, <a data-e=\"farron-keep\">Farron Keep<\/a>, <a data-e=\"painted-world-of-ariandel\">Painted World of Ariandel<\/a> and <a data-e=\"untended-graves\">Untended Graves<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Corvian_Greatknife"},{"id":"court-sorcerers-staff","kind":"weapon","name":"Court Sorcerer's Staff","page":"Court Sorcerer's Staff","img":"assets/img/Court_Sorcerer_s_Staff.webp","wtype":"Staff","group":"catalyst","paired":false,"atk":{"phys":60,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":6,"dex":0,"int":14,"fth":0},"scale":{"str":"E","dex":"-","int":"A","fth":"-"},"defs":{"phys":25,"mag":25,"fire":10,"ltn":10,"dark":15},"stability":10,"weight":2,"durability":45,"skill":"Steady Chant","dmg_type":"Strike","cast":105,"fp":"15(-/-)","buy":null,"desc":"Catalyst used by the court sorcerers of the Profaned Capital. Very powerful when wielded by an exceptionally intelligent sorcerer.\nThe court sorcerers laid claim to the legacy of the renowned Big Hat Logan, going so far as to emulate him with copies of the staff he used.\nSkill: Steady Chant\nBoost the strength of sorceries for a very short period. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Dropped by a Mimic in the <a data-e=\"profaned-capital\">Profaned Capital<\/a>, inside the second floor of the building within the Toxic swamp. It is guarded by a Monstrosity of Sin.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Court_Sorcerer's_Staff"},{"id":"crescent-axe","kind":"weapon","name":"Crescent Axe","page":"Crescent Axe (Dark Souls III)","img":"assets/img/Crescent_Axe__Dark_Souls_III.webp","wtype":"Halberd","group":"melee","paired":false,"atk":{"phys":119,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":12,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":6,"durability":75,"skill":"Warcry","dmg_type":"Slash","cast":null,"fp":"20(-/-)","buy":4000,"desc":"A crescent-shaped halberd resembling a long-handled battle axe.\nTraditionally wielded by Way of White clerics.\nSkill: Warcry\nLet out a spirited warcry that temporarily boosts attack, and enables a special consecutive strong attack.","boss_weapon":false,"avail":"<p>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 4,000 souls once she has been given the <a data-e=\"paladins-ashes\">Paladin's Ashes<\/a>.<\/p>","notes":"<ul><li>Unlike its previous appearances in the series, the Crescent Axe in <i>Dark Souls III<\/i> is a halberd, instead of an axe or a greataxe, and does not have an innate Magic infusion.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Crescent_Axe_(Dark_Souls_III)"},{"id":"crescent-moon-sword","kind":"weapon","name":"Crescent Moon Sword","page":"Crescent Moon Sword","img":"assets/img/Crescent_Moon_Sword.webp","wtype":"Curved Sword","group":"melee","paired":false,"atk":{"phys":78,"mag":78,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":16,"int":0,"fth":0},"scale":{"str":"-","dex":"C","int":"D","fth":"-"},"defs":{"phys":40,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":2.5,"durability":70,"skill":"Crescent Blade","dmg_type":"Slash","cast":null,"fp":"15(-/-)","buy":null,"desc":"Ringfinger Leonhard's weapon of choice, a type of shotel imbued with the power of the moon.\nLeonhard set out on a journey of rebirth, but decided instead to serve the goddess as a knight, and inherited this weapon.\nSkill: Crescent Blade\nAssume a broad stance and fire off crescent moon blades.","boss_weapon":false,"avail":"<p>Dropped by <a data-e=\"ringfinger-leonhard\">Ringfinger Leonhard<\/a>, when defeated through using the <a data-e=\"black-eye-orb\">Black Eye Orb<\/a> in Gwynevere's chamber in <a data-e=\"anor-londo\">Anor Londo<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Crescent_Moon_Sword"},{"id":"crest-shield","kind":"weapon","name":"Crest Shield","page":"Crest Shield (Dark Souls III)","img":"assets/img/Crest_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":95,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":67,"fire":56,"ltn":43,"dark":86},"stability":49,"weight":5,"durability":90,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"A knight's shield engraved with a crest.\nOne of the enchanted blue shields. The Crest Shield greatly reduces dark damage.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>. From the first bonfire, head towards the stairs but look for a path on the right. Follow it as it leads up the hillside, and the shield will be on a corpse at the top.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Crest_Shield_(Dark_Souls_III)"},{"id":"crimson-parma","kind":"weapon","name":"Crimson Parma","page":"Crimson Parma (Dark Souls III)","img":"assets/img/Crimson_Parma__Dark_Souls_III.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":69,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":7,"dex":0,"int":0,"fth":0},"scale":{"str":"E","dex":"-","int":"-","fth":"-"},"defs":{"phys":52,"mag":63,"fire":40,"ltn":36,"dark":39},"stability":39,"weight":1.5,"durability":55,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":800,"desc":"Standard round wooden shield. It is daubed with a red paint that symbolizes the blood of warriors.\nWooden shields are light, manageable, and offer relatively high magic absorption.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 800 souls.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Crimson_Parma_(Dark_Souls_III)"},{"id":"crow-quills","kind":"weapon","name":"Crow Quills","page":"Crow Quills","img":"assets/img/Crow_Quills.webp","wtype":"Thrusting Sword","group":"melee","paired":false,"atk":{"phys":98,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":9,"dex":16,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":35,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":4,"durability":60,"skill":"Quill Dart","dmg_type":"Slash/Thrust","cast":null,"fp":"7(-/8)","buy":null,"desc":"Thrusting sword wielded by Corvian Knights, and a special paired weapon. When twin-handed, brandish four thin-edge blades in the left hand.\nIn their infatuation with Sister Friede, the Corvian Knights swore to protect the painting from fire, and to this end, took to the execution of their own brethren.\nSkill: Quill Dart\nSimultaneously throw temporarily substantial illusions of the four thin-edged blades wielded in the left hand.","boss_weapon":false,"avail":"<p>From the Corvian Settlement bonfire, head out and across the bridge. Follow the wall of the house on your left until you see a smaller bridge. Go across and follow the path to the left. On your left you will see two entrances across a small gap. Jump it and go into the house on your right. Barrels will be blocking a platform that you need to run and leap off of and land on the elevated platform with the Crow Quills.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Crow_Quills"},{"id":"crow-talons","kind":"weapon","name":"Crow Talons","page":"Crow Talons","img":"assets/img/Crow_Talons.webp","wtype":"Claw","group":"melee","paired":true,"atk":{"phys":91,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":6,"dex":19,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":null,"mag":null,"fire":null,"ltn":null,"dark":null},"stability":null,"weight":3,"durability":65,"skill":"Raptor Flurry","dmg_type":"Slash/Thrust","cast":null,"fp":"15(-/-)","buy":null,"desc":"Talons used by Corvian Knights. Inflicts five perpendicular slashes, causing heavy bleeding.\nIn their infatuation with Sister Friede, the Corvian Knights swore to protect the painting from fire and to this end, too to the execution of their own brethren.\nSkill: Raptor Flurry\nSpread right and left talons like a broad set of wings and launch into a tornado of consecutive attacks.","boss_weapon":false,"avail":"<p>Found on the rooftops in the Corvian Settlement, guarded by two magic-wielding Corvians.<\/p>","notes":"<ul><li>The bleed build up of the Raptor Flurry is comparable to the bleed build up of the <a data-e=\"frayed-blade\">Frayed Blade<\/a>'s Hold skill.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Crow_Talons"},{"id":"crucifix-of-the-mad-king","kind":"weapon","name":"Crucifix of the Mad King","page":"Crucifix of the Mad King","img":"assets/img/Crucifix_of_the_Mad_King.webp","wtype":"Halberd","group":"melee","paired":false,"atk":{"phys":124,"mag":0,"fire":0,"ltn":0,"dark":74},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":19,"dex":null,"int":10,"fth":14},"scale":{"str":"D","dex":"-","int":"E","fth":"D"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":12,"durability":80,"skill":"Mad King's Folly","dmg_type":"Standard/Strike","cast":0,"fp":"-(-/17)","buy":null,"desc":"A cross spear hung with a malformed corpse.\nOnce, a mad king was born to the pygmy royalty and Shira, knight of Filianore, put him to rest. But Shira's cross spear, unable to kill the undying king, only pinned itself to him. Shira delivered them together to the darkroom, where she stayed and held them close.\nSkill: Mad King's Folly\nSlam malformed corpse into the ground to briefly awaken it, then fillet with strong attack to trigger a roar, a blessing, or vexation.","boss_weapon":false,"avail":"<p>Dropped by <a data-e=\"shira-knight-of-filianore\">Shira, Knight of Filianore<\/a> when she invades the player at Pygmy's Throne.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Crucifix_of_the_Mad_King"},{"id":"crystal-chime","kind":"weapon","name":"Crystal Chime","page":"Crystal Chime","img":"assets/img/Crystal_Chime.webp","wtype":"Sacred Chime","group":"catalyst","paired":false,"atk":{"phys":73,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":3,"dex":0,"int":18,"fth":18},"scale":{"str":"E","dex":"-","int":"D","fth":"D"},"defs":{"phys":25,"mag":20,"fire":10,"ltn":15,"dark":15},"stability":10,"weight":0.5,"durability":40,"skill":"Gentle Prayer","dmg_type":"Strike","cast":134,"fp":"13(-/-)","buy":null,"desc":"A sacred chime, once the possession of Gertrude, the Heavenly Daughter, and defiled by the scholars of the Grand Archives.\nThe power of crystals granted the scholars a degree of success. In this case, their work enabled this chime to be suitable for casting both miracles and sorceries.\nSkill: Gentle Prayer\nRecovers HP for a period of time, albeit extremely slowly. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"grand-archives\">Grand Archives<\/a>.<\/p><p>From the first wax pool on the first floor, navigate to the right of the entrance to the dark room and look for a corridor, where a red-eyed <a data-e=\"lothric-knight-long-spear\">spear<\/a>-wielding Lothric Knight is making rounds. The chime is inside a small room at the end of the corridor.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Crystal_Chime"},{"id":"crystal-sages-rapier","kind":"weapon","name":"Crystal Sage's Rapier","page":"Crystal Sage's Rapier","img":"assets/img/Crystal_Sage_s_Rapier.webp","wtype":"Thrusting Sword","group":"melee","paired":false,"atk":{"phys":55,"mag":82,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":13,"dex":18,"int":0,"fth":0},"scale":{"str":"E","dex":"E","int":"C","fth":"-"},"defs":{"phys":40,"mag":30,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":2.5,"durability":40,"skill":"Stance","dmg_type":"Thrust","cast":null,"fp":"-(15/15)","buy":null,"desc":"Thrusting sword with tiny crystals scattered across its blade, used by the Crystal Sages for self-defense.\nThe crystals boost the magic damage inflicted by the sword, and the item discovery of its wielder, fruits of the lifetime of research conducted by the sages.\nSkill: Stance\nFrom stance, use normal attack to back step and execute a surprise attack, or strong attack for consecutive thrusting.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-a-crystal-sage\">Soul of a Crystal Sage<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"","from_soul":[{"soul":"soul-of-a-crystal-sage","cost":null}],"url":"https://darksouls.fandom.com/wiki/Crystal_Sage's_Rapier"},{"id":"curse-ward-greatshield","kind":"weapon","name":"Curse Ward Greatshield","page":"Curse Ward Greatshield","img":"assets/img/Curse_Ward_Greatshield.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":125,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":34,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":75,"fire":69,"ltn":63,"dark":75},"stability":66,"weight":17,"durability":150,"skill":"Weapon Skill","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Greatshield given to those who resisted the curse long ago.\nFar too heavy for an ordinary person, perhaps it signifies the foolishness of resisting the curse.\nAnd yet, those who bear the weight of this shield will not find its protections against curses wanting.\nSkill: Weapon Skill\nEquipped this shield in the left hand allows one to perform the Skill of the right hand weapon.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>, on a corpse lying in the mausoleum located in front of the pair of large doors at the end of the graveyard on the upper level, and above the shortcut ladder that leads down to the stream with the Corpse Grubs.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Curse_Ward_Greatshield"},{"id":"dagger","kind":"weapon","name":"Dagger","page":"Dagger (Dark Souls III)","img":"assets/img/Dagger__Dark_Souls_III.webp","wtype":"Dagger","group":"melee","paired":false,"atk":{"phys":65,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":5,"dex":9,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":35,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":1.5,"durability":50,"skill":"Quickstep","dmg_type":"Slash/Thrust","cast":null,"fp":"5(-/-)","buy":300,"desc":"Standard small dagger.\nSmall daggers lack power or reach, but can deal quick consecutive hits due to their light weight. Highly effective when used for critical hits, such as after parrying or attacking from behind.\nSkill: Quickstep\nInstantly step behind or around the side of foes. Especially effective when locked on to target.","boss_weapon":false,"avail":"<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 300 souls.<\/li><li>Dropped by Hollow Assassins.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Dagger_(Dark_Souls_III)"},{"id":"dancers-enchanted-swords","kind":"weapon","name":"Dancer's Enchanted Swords","page":"Dancer's Enchanted Swords","img":"assets/img/Dancer_s_Enchanted_Swords.webp","wtype":"Curved Sword","group":"melee","paired":true,"atk":{"phys":79,"mag":62,"fire":62,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":20,"int":9,"fth":9},"scale":{"str":"D","dex":"D","int":"D","fth":"D"},"defs":{"phys":50,"mag":40,"fire":35,"ltn":25,"dark":30},"stability":35,"weight":8.5,"durability":80,"skill":"Dancer's Grace","dmg_type":"Slash","cast":null,"fp":"6(-/9)","buy":null,"desc":"Paired enchanted swords that Pontiff Sulyvahn bestowed upon the Dancer of the Boreal Valley.\nThese blades, symbolic of the Dancer's vows, are enchanted with dark magic in the right-hand, and fire in the left, mirroring the Pontiff.\nSkill: Dancer's Grace\nUnleash the fury of both blades in a dancing spin motion and use strong attack to continue the performance until stamina is exhausted.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-the-dancer\">Soul of the Dancer<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>. No souls are required in the transposition process.<\/p>","notes":"<ul><li>The magic sword is wielded in the main hand, and the fire sword is wielded in the off hand.<\/li><li>When equipped in the off-hand slot, the magic sword will be wielded, however when two-handed the swords will be equipped in their proper hands, with the off-hand holding the fire sword.<\/li><li>Use of the weapon's skill with the heavy attack exhausts not only stamina, but uses Focus Points, too, for the duration of the attack.<\/li><\/ul>","from_soul":[{"soul":"soul-of-the-dancer","cost":null}],"url":"https://darksouls.fandom.com/wiki/Dancer's_Enchanted_Swords"},{"id":"dark-hand","kind":"weapon","name":"Dark Hand","page":"Dark Hand (Dark Souls III)","img":"assets/img/Dark_Hand__Dark_Souls_III.webp","wtype":"Fist","group":"melee","paired":false,"atk":{"phys":88,"mag":0,"fire":0,"ltn":0,"dark":150},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":0,"dex":0,"int":0,"fth":0},"scale":{"str":"C","dex":"C","int":"D","fth":"D"},"defs":{"phys":65,"mag":65,"fire":65,"ltn":65,"dark":65},"stability":30,"weight":0,"durability":55,"skill":"Lifedrain","dmg_type":"Strike","cast":null,"fp":"18(-/-)","buy":12000,"desc":"Weapon that allows its wielder to evoke an art unique to Londor, the land of the Hollow. It is also said to be an ancient relic of a Primordial Serpent.\nThe Dark Hand mercilessly saps the essence of its victims, and can also double as a special shield. Cannot be used two-handed.\nSkill: Lifedrain\nEmbrace the victim and steal their HP. Can only be used against humans.","boss_weapon":false,"avail":"<p>Sold by <a data-e=\"yuria-of-londor\">Yuria of Londor<\/a> for 12,000 souls.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Dark_Hand_(Dark_Souls_III)"},{"id":"dark-sword","kind":"weapon","name":"Dark Sword","page":"Dark Sword","img":"assets/img/Dark_Sword.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":110,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":16,"dex":15,"int":0,"fth":0},"scale":{"str":"C","dex":"D","int":"-","fth":"-"},"defs":{"phys":55,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":35,"weight":4.5,"durability":80,"skill":"Stomp","dmg_type":"Standard/Thrust","cast":null,"fp":"13(-/13)","buy":null,"desc":"Pitch-black straight sword of the Darkwraith, survivor of the land swallowed by darkness.\nThe Darkwraiths were the first red orb invaders, and originators of a unique sword technique inspired by their thick, broad blades.\nSkill: Stomp\nUse one's weight to lunge forward with a low stance and increased poise, and follow with strong attack for an upward slash.","boss_weapon":false,"avail":"<p>Dropped by Darkwraiths in <a data-e=\"farron-keep\">Farron Keep<\/a> and <a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Dark_Sword"},{"id":"darkdrift","kind":"weapon","name":"Darkdrift","page":"Darkdrift (Dark Souls III)","img":"assets/img/Darkdrift__Dark_Souls_III.webp","wtype":"Katana","group":"melee","paired":false,"atk":{"phys":134,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":34,"psn":0,"fst":0},"req":{"str":10,"dex":28,"int":0,"fth":0},"scale":{"str":"E","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":30,"weight":3.5,"durability":35,"skill":"Darkdrift","dmg_type":"Slash/Thrust","cast":null,"fp":"20(-/-)","buy":null,"desc":"A cursed sword with an unseen blade, the choice weapon for Yuria of Londor.\nYuria, a mentor of the Sable Church and accomplished swordswoman, is said to have claimed a hundred lives with this weapon.\nSkill: Darkdrift\nAim carefully, and pierce with a large forward lunge. The unseen blade penetrates straight through shields, for nothing can defend from Darkdrift.","boss_weapon":false,"avail":"<ul><li><a data-e=\"firelink-shrine\">Firelink Shrine<\/a><ul><li>Dropped by <a data-e=\"yuria-of-londor\">Yuria of Londor<\/a>.<\/li><li>Alternatively, left at her normal location once she disappears after completing the Lord of Hollows ending.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Darkdrift_(Dark_Souls_III)"},{"id":"darkmoon-longbow","kind":"weapon","name":"Darkmoon Longbow","page":"Darkmoon Longbow","img":"assets/img/Darkmoon_Longbow.webp","wtype":"Bow","group":"ranged","paired":false,"atk":{"phys":36,"mag":44,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":7,"dex":16,"int":10,"fth":0},"scale":{"str":"-","dex":"E","int":"C","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":4.5,"durability":50,"skill":"Darkmoon Arrow","dmg_type":"None","cast":null,"fp":"-(10/10)","buy":5000,"desc":"Longbow of Darkmoon Gwyndolin. who was gradually devoured by Aldrich.\nThis golden bow is imbued with powerful magic and is most impressive with Moonlight Arrows.\nSkill: Darkmoon Arrow\nInfuse a readied arrow with Darkmoon essence, granting it magic damage and the ability to pierce shields.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-aldrich\">Soul of Aldrich<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> for 5,000 souls.<\/p>","notes":"","from_soul":[{"soul":"soul-of-aldrich","cost":"5,000 souls"}],"url":"https://darksouls.fandom.com/wiki/Darkmoon_Longbow"},{"id":"demons-fist","kind":"weapon","name":"Demon's Fist","page":"Demon's Fist","img":"assets/img/Demon_s_Fist.webp","wtype":"Fist","group":"melee","paired":false,"atk":{"phys":111,"mag":0,"fire":77,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":20,"dex":8,"int":9,"fth":9},"scale":{"str":"D","dex":"-","int":"E","fth":"E"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":5.5,"durability":100,"skill":"Flame Whirlwind","dmg_type":"Strike","cast":null,"fp":"10(-/10)","buy":null,"desc":"A demonic fist that burns with fiery essence. Its wielder can release this power through use of its Skill.\nWhen two-handed, fists are equipped in each hand.\nSkill: Flame Whirlwind\nSpin through opponents with abandon, flaming fists outstretched. Using a strong attack while spinning utilizes your momentum to slam the ground with both fists.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-a-demon\">Soul of a Demon<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"","from_soul":[{"soul":"soul-of-a-demon","cost":null}],"url":"https://darksouls.fandom.com/wiki/Demon's_Fist"},{"id":"demons-greataxe","kind":"weapon","name":"Demon's Greataxe","page":"Demon's Greataxe (Dark Souls III)","img":"assets/img/Demon_s_Greataxe__Dark_Souls_III.webp","wtype":"Greataxe","group":"melee","paired":false,"atk":{"phys":157,"mag":0,"fire":88,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":28,"dex":0,"int":12,"fth":12},"scale":{"str":"C","dex":"E","int":"D","fth":"D"},"defs":{"phys":50,"mag":40,"fire":35,"ltn":35,"dark":40},"stability":40,"weight":14.5,"durability":60,"skill":"Demonic Flare","dmg_type":"Standard","cast":null,"fp":"35(-/-)","buy":null,"desc":"This greataxe, a favorite among demons, contains the strength of fire.\nThe demons, born of Chaos, harbor fire, and yet they are twisted and malformed, such that they were never meant to be.\nSkill: Demonic Flare\nBriefly cause flame within to flare, and smash it upon earth and foes.","boss_weapon":true,"avail":"<p>Transpose the <a data-e=\"soul-of-a-demon\">Soul of a Demon<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"","from_soul":[{"soul":"soul-of-a-demon","cost":null}],"url":"https://darksouls.fandom.com/wiki/Demon's_Greataxe_(Dark_Souls_III)"},{"id":"demons-scar","kind":"weapon","name":"Demon's Scar","page":"Demon's Scar","img":"assets/img/Demon_s_Scar.webp","wtype":"Curved Sword","group":"melee","paired":false,"atk":{"phys":0,"mag":0,"fire":99,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":0,"dex":16,"int":17,"fth":17},"scale":{"str":"-","dex":"E","int":"D","fth":"D"},"defs":{"phys":25,"mag":35,"fire":65,"ltn":30,"dark":35},"stability":30,"weight":0.5,"durability":70,"skill":"Spin Slash","dmg_type":"Slash","cast":119,"fp":"7(-/20)","buy":10000,"desc":"This chaotic thing, the last flame kindled by the demon prince, is shaped like the claw marks of a demon.\nIt is both a fiery bladed weapon and pyromancy flame.\nSkill: Spin Slash\nSpin to stoke a fierce chaos flame, and use momentum to transition into a spinning strong attack, creating a short-lived lava pool.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-the-demon-prince\">Soul of the Demon Prince<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> for a cost of 10,000 souls.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Demon's_Scar"},{"id":"dragon-crest-shield","kind":"weapon","name":"Dragon Crest Shield","page":"Dragon Crest Shield (Dark Souls III)","img":"assets/img/Dragon_Crest_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":95,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":67,"fire":89,"ltn":43,"dark":53},"stability":49,"weight":5,"durability":90,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"A knight's shield engraved with a crest depicting a dragon.\nOne of the enchanted blue shields. The Dragon Crest Shield greatly reduces fire damage.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"farron-keep\">Farron Keep<\/a>. On the bridge above the <a data-e=\"farron-keep\">Old Wolf of Farron<\/a> bonfire, turn right and head towards the closed gate, then drop off the destroyed railing to the right. Navigate the platforms to reach the other side, the shield will be found on a corpse near the dead wyvern, amongst scattered Crystal Lizards.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Dragon_Crest_Shield_(Dark_Souls_III)"},{"id":"dragon-tooth","kind":"weapon","name":"Dragon Tooth","page":"Dragon Tooth (Dark Souls III)","img":"assets/img/Dragon_Tooth__Dark_Souls_III.webp","wtype":"Great Hammer","group":"melee","paired":false,"atk":{"phys":188,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":40,"dex":0,"int":0,"fth":0},"scale":{"str":"C","dex":"-","int":"-","fth":"-"},"defs":{"phys":60,"mag":45,"fire":40,"ltn":40,"dark":45},"stability":45,"weight":21,"durability":340,"skill":"Perseverance","dmg_type":"Strike","cast":null,"fp":"12(-/-)","buy":null,"desc":"Created from an everlasting dragon tooth that will never break.\nLeft by Havel himself, along with his boulder-like great shield. Grants its wielder resistance to magic and fire.\nSkill: Perseverance\nAnchor weapon in earth to temporarily boost poise. Damage reduced while activated.","boss_weapon":false,"avail":"<ul><li>Only one per playthrough can be obtained at <a data-e=\"archdragon-peak\">Archdragon Peak<\/a>:<ul><li>Dropped by Havel the Rock at the top of the Great Belfry.<\/li><li>The two Man Serpent Summoners have a small chance of summoning Havel as well.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Dragon_Tooth_(Dark_Souls_III)"},{"id":"dragonhead-greatshield","kind":"weapon","name":"Dragonhead Greatshield","page":"Dragonhead Greatshield","img":"assets/img/Dragonhead_Greatshield.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":145,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":35,"dex":null,"int":null,"fth":15},"scale":{"str":"D","dex":"-","int":"-","fth":"E"},"defs":{"phys":100,"mag":55,"fire":90,"ltn":30,"dark":55},"stability":60,"weight":18,"durability":150,"skill":"Dragon Roar","dmg_type":"Strike","cast":0,"fp":"16(-/-)","buy":null,"desc":"This shield, as hard as a great boulder, is formed by the head of the descendant of an Archdragon.\nThe Ringed Knights, by command of the gods, stood amongst the ranks who set out to slay the dragons, but their contributions were never lauded.\nSkill: Dragon Roar\nEven the descendant of an Archdragon perishes not, and use of this skill restores its former strength, sending surrounding foes flying with a dragon roar.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"the-ringed-city\">The Ringed City<\/a>. Located beneath the bridge where <a data-e=\"darkeater-midir\">Darkeater Midir<\/a> is first encountered near the <a data-e=\"the-ringed-city\">Ringed City Streets<\/a> bonfire. The shield is guarded by a Ringed Knight.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Dragonhead_Greatshield"},{"id":"dragonhead-shield","kind":"weapon","name":"Dragonhead Shield","page":"Dragonhead Shield","img":"assets/img/Dragonhead_Shield.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":116,"mag":0,"fire":12,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":null,"int":11,"fth":12},"scale":{"str":"D","dex":"-","int":"E","fth":"E"},"defs":{"phys":70,"mag":65,"fire":90,"ltn":35,"dark":55},"stability":40,"weight":4.5,"durability":85,"skill":"Dragon Breath","dmg_type":"Strike","cast":0,"fp":"12(-/-)","buy":null,"desc":"This shield, as hard as a great boulder, is formed by the head of the descendant of an Archdragon.\nThe Ringed Knights, by command of the gods, stood amongst the ranks who set out to slay the dragons, but their contributions were never lauded.\nSkill: Dragon Breath\nEven the descendant of an Archdragon perishes not, and use of this skill restores its former strength, sweeping foes with a frontal exhalation of dragon breath.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"the-ringed-city\">The Ringed City<\/a>. Past the &quot;Show your humanity&quot; puzzle near the Ringed City Streets bonfire, proceed past the Judicator Giant and two Ringed Knights. After climbing down the ladder towards the Purging Monument, make a hard right before the bridge to the monument, and follow the path to a dead end where the shield can be found.<\/p>","notes":"<ul><li>Even if players run out of FP, they can still use the shield's skill; however, it will come at a damage penalty of about 50%.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Dragonhead_Shield"},{"id":"dragonrider-bow","kind":"weapon","name":"Dragonrider Bow","page":"Dragonrider Bow (Dark Souls III)","img":"assets/img/Dragonrider_Bow__Dark_Souls_III.webp","wtype":"Bow","group":"ranged","paired":false,"atk":{"phys":110,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":19,"dex":15,"int":0,"fth":0},"scale":{"str":"D","dex":"E","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":6.5,"durability":75,"skill":"Puncture","dmg_type":"None","cast":null,"fp":"-(9/9)","buy":null,"desc":"Longbow of the Dragonriders, who served the Old King of Want.\nThe Dragonriders were the Old King's royal guard, and great strength was demanded of them. Merely drawing this bow calls for inhuman strength. The worthy few who can master this bow, however, use it to devastating effect.\nSkill: Puncture\nPull the arrow even further back for a more powerful shot that can also pierce shields.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>.<\/p><p>From the <a data-e=\"smouldering-lake\">Demon Ruins<\/a> bonfire, make way to the lowest floor. Climb up the stairs after the area with several Basilisks and cross a bridge with a Black Knight standing guard at the other end. Climb up the two sets of ladders nearby, turn around and drop to a small niche on the right wall with a corpse holding the bow.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Dragonrider_Bow_(Dark_Souls_III)"},{"id":"dragonslayer-greataxe","kind":"weapon","name":"Dragonslayer Greataxe","page":"Dragonslayer Greataxe","img":"assets/img/Dragonslayer_Greataxe.webp","wtype":"Greataxe","group":"melee","paired":false,"atk":{"phys":200,"mag":0,"fire":0,"ltn":74,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":40,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"E","int":"-","fth":"D"},"defs":{"phys":55,"mag":45,"fire":40,"ltn":40,"dark":45},"stability":40,"weight":20,"durability":165,"skill":"Falling Bolt","dmg_type":"Standard","cast":null,"fp":"35(-/-)","buy":null,"desc":"Melted iron greataxe that once formed part of the Dragonslayer Armour.\nThickly imbued with the power of lightning. Use skill to draw upon the techniques used to slay the archdragons.\nSkill: Falling Bolt\nHold axe high in air to gather fierce lightning, and smash ground to whip the bolts to the ground.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-dragonslayer-armour\">Soul of Dragonslayer Armour<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"","from_soul":[{"soul":"soul-of-dragonslayer-armour","cost":null}],"url":"https://darksouls.fandom.com/wiki/Dragonslayer_Greataxe"},{"id":"dragonslayer-greatbow","kind":"weapon","name":"Dragonslayer Greatbow","page":"Dragonslayer Greatbow (Dark Souls III)","img":"assets/img/Dragonslayer_Greatbow__Dark_Souls_III.webp","wtype":"Greatbow","group":"melee","paired":false,"atk":{"phys":126,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":20,"dex":20,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":10,"durability":100,"skill":"Puncturing Arrow","dmg_type":"None","cast":null,"fp":"-(20/20)","buy":null,"desc":"Greatbow used by the Dragonslayers during the age of gods. Far greater in size than any normal bow, and far more devastating.\nThe bow must be anchored to the ground when fired, a time-consuming operation that leaves the user vulnerable. Only specialized great arrows can be fired from the bow.\nSkill: Puncturing Arrow\nMasterfully fires off a great arrow that pierces through all enemies in its path, inflicting damage.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/p><ul><li>Dropped by Silver Knight archers.<\/li><li>One is found along with five <a data-e=\"dragonslayer-greatarrow\">Dragonslayer Greatarrows<\/a> on a corpse lying beneath the flying buttresses where most of the Silver Knights are posted.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Dragonslayer_Greatbow_(Dark_Souls_III)"},{"id":"dragonslayer-greatshield","kind":"weapon","name":"Dragonslayer Greatshield","page":"Dragonslayer Greatshield","img":"assets/img/Dragonslayer_Greatshield.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":134,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":38,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":71,"fire":70,"ltn":95,"dark":77},"stability":74,"weight":26,"durability":190,"skill":"Shield Bash","dmg_type":"Strike","cast":null,"fp":"16(-/-)","buy":null,"desc":"Melted iron shield that once formed part of the Dragonslayer Armour.\nThe shield offers high protection to lightning, which the Dragonslayer commanded as his own, and its Skill has faint echoes of the Dragonslayer's own fighting style.\nSkill: Shield Bash\nWithout lowering your guard, strike the enemy with the shield to knock them back or stagger them. Works while equipped in either hand.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-dragonslayer-armour\">Soul of Dragonslayer Armour<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> at <a data-e=\"firelink-shrine\">Firelink Shrine<\/a>.<\/p>","notes":"","from_soul":[{"soul":"soul-of-dragonslayer-armour","cost":null}],"url":"https://darksouls.fandom.com/wiki/Dragonslayer_Greatshield"},{"id":"dragonslayer-spear","kind":"weapon","name":"Dragonslayer Spear","page":"Dragonslayer Spear (Dark Souls III)","img":"assets/img/Dragonslayer_Spear__Dark_Souls_III.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":97,"mag":0,"fire":0,"ltn":70,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":20,"dex":20,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"D"},"defs":{"phys":50,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":9.5,"durability":80,"skill":"Lightning Charge","dmg_type":"Thrust","cast":null,"fp":"17(-/12)","buy":null,"desc":"Cross spear associated with Ornstein the Dragonslayer. A weapon of the gods imbued with the strength of lightning.\nTwo-handed thrust utilizes the support of the cross and requires great might, but can pierce deep into the flesh of dragons, and send mere men flying.\nSkill: Lightning Charge\nCharge with spear at waist to enwreathe with lightning, then release bolts with final thrust.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"archdragon-peak\">Archdragon Peak<\/a>. From the Dragon-Kin Mausoleum bonfire, proceed up the nearby stairs and the spear can be obtained by interacting with the metal gate that leads to the courtyard below <a data-e=\"the-nameless-king\">the Nameless King<\/a>'s arena.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Dragonslayer_Spear_(Dark_Souls_III)"},{"id":"dragonslayer-swordspear","kind":"weapon","name":"Dragonslayer Swordspear","page":"Dragonslayer Swordspear","img":"assets/img/Dragonslayer_Swordspear.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":128,"mag":0,"fire":0,"ltn":34,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":16,"dex":22,"int":0,"fth":18},"scale":{"str":"D","dex":"D","int":"-","fth":"D"},"defs":{"phys":55,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":25,"weight":14.5,"durability":100,"skill":"Falling Bolt","dmg_type":"Standard/Thrust","cast":null,"fp":"20(-/-)","buy":10000,"desc":"A dragon hunting weapon from the age of the gods. The earliest form of the cross spear, serving as both sword and spear.\nIts owner was the Nameless King and deific hunter of dragons. The swordspear is imbued with lightning, of which he was the heir.\nSkill: Falling Bolt\nHold swordspear high in the air to summon fierce lightning that descends upon distant foes.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-the-nameless-king\">Soul of the Nameless King<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> for 10,000 souls.<\/p>","notes":"","from_soul":[{"soul":"soul-of-the-nameless-king","cost":"10,000 souls"}],"url":"https://darksouls.fandom.com/wiki/Dragonslayer_Swordspear"},{"id":"dragonslayers-axe","kind":"weapon","name":"Dragonslayer's Axe","page":"Dragonslayer's Axe","img":"assets/img/Dragonslayer_s_Axe.webp","wtype":"Axe","group":"melee","paired":false,"atk":{"phys":105,"mag":0,"fire":0,"ltn":105,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":14,"int":0,"fth":0},"scale":{"str":"D","dex":"E","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":4,"durability":70,"skill":"Warcry","dmg_type":"Standard","cast":null,"fp":"20(-/-)","buy":null,"desc":"Axe favored by Creighton the Wanderer, infamous deserter of the Knights of Mirrah.\nCalled Dragonslayer's Axe for the lightning that pulsates within its blade, but Creighton used it to slay men.\nSkill: Warcry\nLet out a spirited warcry that temporarily boosts attack.","boss_weapon":false,"avail":"<p>Obtained after defeating Creighton the Wanderer in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>. He will invade near a large tombstone outside of the Church of Yorshka and will only invade after defeating him with <a data-e=\"sirris-of-the-sunless-realms\">Sirris of the Sunless Realms<\/a> on the bridge to Irithyll.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Dragonslayer's_Axe"},{"id":"drakeblood-greatsword","kind":"weapon","name":"Drakeblood Greatsword","page":"Drakeblood Greatsword (Dark Souls III)","img":"assets/img/Drakeblood_Greatsword__Dark_Souls_III.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":89,"mag":71,"fire":0,"ltn":71,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":16,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":50,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":35,"weight":6,"durability":75,"skill":"Stance","dmg_type":"Standard/Thrust","cast":null,"fp":"-(17/20)","buy":null,"desc":"Greatsword wielded by an order of knights who venerate dragon blood.\nThis sword, its blade engraved with script symbolizing dragon blood, inflicts magic and lightning damage.\nSkill: Stance\nWhile in stance, use normal attack to break a foe's guard from below, and strong attack to slash upwards with a forward lunge.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"archdragon-peak\">Archdragon Peak<\/a>. Guaranteed drop from the first Drakeblood Knight spawned by the Man Serpent Summoner in the <a data-e=\"archdragon-peak\">Dragon-Kin Mausoleum<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Drakeblood_Greatsword_(Dark_Souls_III)"},{"id":"drang-hammers","kind":"weapon","name":"Drang Hammers","page":"Drang Hammers","img":"assets/img/Drang_Hammers.webp","wtype":"Hammer","group":"melee","paired":true,"atk":{"phys":110,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":16,"int":0,"fth":0},"scale":{"str":"C","dex":"E","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":9,"durability":80,"skill":"Spin Bash","dmg_type":"Strike","cast":null,"fp":"7(-/15)","buy":null,"desc":"Paired hammers of the Drang Knights, proclaimed descendants from the land known for the legend of the Linking of the Fire. When the Drang Knights disbanded, they scattered across the lands as sellswords. They quickly became known for shieldless, aggressive tactics that struck fear into the hearts of men.\nSkill: Spin Bash\nBash foes with a large spinning motion, and utilize momentum to transition into an overhanded strong attack smash.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a> by the staircase that leads to the <a data-e=\"deacons-of-the-deep\">Deacons of the Deep<\/a> boss area, at the feet of a Giant Slave in a pool containing many Writhing Rotten Flesh and one Man-grub.<\/p>","notes":"<p>This weapon does very large amounts of Poise damage, useful against high poise enemies and bosses.<\/p>","url":"https://darksouls.fandom.com/wiki/Drang_Hammers"},{"id":"drang-twinspears","kind":"weapon","name":"Drang Twinspears","page":"Drang Twinspears","img":"assets/img/Drang_Twinspears.webp","wtype":"Spear","group":"melee","paired":true,"atk":{"phys":100,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":20,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":8,"durability":70,"skill":"Charge","dmg_type":"Standard/Thrust","cast":null,"fp":"13(-/9)","buy":null,"desc":"Paired spears of the Drang Knights, proclaimed descendants from the land known for the legend of the Linking of the Fire. When the Drang Knights disbanded, they scattered across the lands as sellswords. They quickly became known for shieldless, aggressive tactics that struck fear into the hearts of men.\nSkill: Charge\nHold spear at waist and charge at foe. Use strong attack while charging to extend the length of the charge.","boss_weapon":false,"avail":"<p>Dropped by the Drang Knight who wields them in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>, in the courtyard after <a data-e=\"pontiff-sulyvahn\">Pontiff Sulyvahn<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Drang_Twinspears"},{"id":"earth-seeker","kind":"weapon","name":"Earth Seeker","page":"Earth Seeker","img":"assets/img/Earth_Seeker.webp","wtype":"Greataxe","group":"melee","paired":false,"atk":{"phys":154,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":24,"dex":0,"int":0,"fth":15},"scale":{"str":"C","dex":"-","int":"-","fth":"D"},"defs":{"phys":55,"mag":45,"fire":40,"ltn":40,"dark":45},"stability":40,"weight":17,"durability":115,"skill":"Earthen Wrath","dmg_type":"Standard","cast":null,"fp":"30(-/-)","buy":null,"desc":"This large twin-bladed axe forged with bronze is a ceremonial weapon normally used in sacred rites.\nMillwood is a land of primitive earth worship where chieftain knights served as high priests.\nSkill: Earthen Wrath\nThrust weapon into earth with a prayer to trigger explosive tremors.","boss_weapon":false,"avail":"<p>In the Snowy Mountain Pass area, inside the large valley area being patrolled by Millwood Knights and the large tree in the center. The Earth Seeker is within a cave area at the back of the valley, being guarded by a Millwood Knight who is himself wielding an Earth Seeker.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Earth_Seeker"},{"id":"east-west-shield","kind":"weapon","name":"East-West Shield","page":"East-West Shield (Dark Souls III)","img":"assets/img/East_West_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":76,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":55,"mag":70,"fire":53,"ltn":56,"dark":46},"stability":45,"weight":2,"durability":60,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"A wooden shield decorated with the ancient symbol of the two-headed eagle. Close to a small shield in size.\nWooden shields are light, manageable, and offer relatively high magic absorption.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"cemetery-of-ash\">Cemetery of Ash<\/a>. Take the path on the left before entering <a data-e=\"firelink-shrine\">Firelink Shrine<\/a>; the shield can be looted from a corpse lying on the branches of a tree found before encountering the Sword Master.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/East-West_Shield_(Dark_Souls_III)"},{"id":"eastern-iron-shield","kind":"weapon","name":"Eastern Iron Shield","page":"Eastern Iron Shield","img":"assets/img/Eastern_Iron_Shield.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":81,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":85,"mag":40,"fire":41,"ltn":22,"dark":39},"stability":48,"weight":3,"durability":100,"skill":"Weapon Skill","dmg_type":"Strike","cast":null,"fp":null,"buy":3000,"desc":"A thick, round metal shield decorated with the unique crest of an eastern land.\nHeaviest of the small shields, it is impressively weighty and thus able to deflect attacks with ease.\nSkill: Weapon Skill\nEquipping this shield in the left hand allows one to perform the Skill of the right hand weapon.","boss_weapon":false,"avail":"<p>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 3,000 souls once she has been given the <a data-e=\"easterners-ashes\">Easterner's Ashes<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Eastern_Iron_Shield"},{"id":"eleonora","kind":"weapon","name":"Eleonora","page":"Eleonora","img":"assets/img/Eleonora.webp","wtype":"Axe","group":"melee","paired":false,"atk":{"phys":156,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":20,"dex":8,"int":0,"fth":0},"scale":{"str":"D","dex":"E","int":"-","fth":"-"},"defs":{"phys":55,"mag":40,"fire":30,"ltn":30,"dark":40},"stability":35,"weight":6.5,"durability":90,"skill":"Feast Bell","dmg_type":"Standard","cast":null,"fp":"24(-/-)","buy":null,"desc":"A strange weapon found among malformed inhabitants of the Profaned Capital.\nThe Profaned Flame was triggered by the curse of these women, relatives of a certain oracle, but despite their culpability, they went on living without any cares.\nSkill: Feast Bell\nHold up axe and wave to emit a solemn chime to temporarily make weapons lacerating, and to restore HP for each hit.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"profaned-capital\">Profaned Capital<\/a>. Guaranteed drop from the already awoken Monstrosity of Sin found on the lower level of the ruined chapel that lies in the toxic swamp.<\/p>","notes":"<ul><li>Once per playthrough, one can be traded with the <a data-e=\"nestling\">Nestling<\/a> in exchange for a <a data-e=\"hollow-gem\">Hollow Gem<\/a>.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Eleonora"},{"id":"elkhorn-round-shield","kind":"weapon","name":"Elkhorn Round Shield","page":"Elkhorn Round Shield","img":"assets/img/Elkhorn_Round_Shield.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":69,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":0,"int":0,"fth":0},"scale":{"str":"E","dex":"-","int":"-","fth":"-"},"defs":{"phys":59,"mag":63,"fire":33,"ltn":36,"dark":25},"stability":39,"weight":1.5,"durability":55,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":1500,"desc":"Standard round wooden shield. The blue antlers are reminiscent of designs found in Mirrah.\nWooden shields are light, manageable, and offer relatively high magic absorption.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 1,500 souls.<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for the same price once she is given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Elkhorn_Round_Shield"},{"id":"estoc","kind":"weapon","name":"Estoc","page":"Estoc (Dark Souls III)","img":"assets/img/Estoc__Dark_Souls_III.webp","wtype":"Thrusting Sword","group":"melee","paired":false,"atk":{"phys":105,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":12,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":3.5,"durability":60,"skill":"Shield Splitter","dmg_type":"Standard/Thrust","cast":null,"fp":"14(-/-)","buy":3000,"desc":"Large thrusting sword used for piercing through the armor of knights.\nThe sharp edge of the sword's rock-solid blade can also be used in slashing attacks.\nSkill: Shield Splitter\nAim carefully, and attack in a large forward lunge to pierce through enemy shields and inflict damage directly.","boss_weapon":false,"avail":"<ul><li>Starting equipment of the Assassin class.<\/li><li><a data-e=\"firelink-shrine\">Firelink Shrine<\/a><ul><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat<\/a> for 3,000 souls once he returns from his first scavenge expedition in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<\/li><\/ul><\/li><\/ul>","notes":"<ul><li>Accepts all infusions.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Estoc_(Dark_Souls_III)"},{"id":"ethereal-oak-shield","kind":"weapon","name":"Ethereal Oak Shield","page":"Ethereal Oak Shield","img":"assets/img/Ethereal_Oak_Shield.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":103,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":65,"fire":35,"ltn":70,"dark":60},"stability":50,"weight":5,"durability":80,"skill":"Weapon Skill","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Charbronze shield used by Millwood Knights that slowly regenerates HP.\nThis shield appears to be blessed by a great, if faded, image of the ethereal oak.\nSkill: Weapon Skill\nEquipping this shield in the left hand allows one to perform the Skill of the right hand weapon.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"painted-world-of-ariandel\">Painted World of Ariandel<\/a>, on a corpse found in a tower of the Millwood ruins. The corpse is located at the bottom half of the tower after going up a ladder and then going down the stairs.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Ethereal_Oak_Shield"},{"id":"executioners-greatsword","kind":"weapon","name":"Executioner's Greatsword","page":"Executioner's Greatsword","img":"assets/img/Executioner_s_Greatsword.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":134,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":19,"dex":13,"int":0,"fth":0},"scale":{"str":"C","dex":"E","int":"-","fth":"-"},"defs":{"phys":50,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":40,"weight":9,"durability":85,"skill":"Stomp","dmg_type":"Strike","cast":null,"fp":"12(-/17)","buy":null,"desc":"Greatsword of a debauched executioner used for beheadings.\nThis sword retains a keen memory of its executioner's duty, and absorbs FP from each fallen foe.\nSkill: Stomp\nUse one's weight to lunge forward with a low stance and increased poise, and follow with strong attack for a spinning slash.","boss_weapon":false,"avail":"<p>Found at the graveyard in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>.<\/p><p>From the Cleansing Chapel, make way into the graveyard and proceed in the general straightforward direction until reaching the other end. A small enclosed area with several corpses and some loot can be found, one of which is the sword. Upon picking it up, however, the corpses, some of which are infested, will come to life and ambush the player.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Executioner's_Greatsword"},{"id":"exile-greatsword","kind":"weapon","name":"Exile Greatsword","page":"Exile Greatsword","img":"assets/img/Exile_Greatsword.webp","wtype":"Curved Greatsword","group":"melee","paired":false,"atk":{"phys":148,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":24,"dex":16,"int":0,"fth":0},"scale":{"str":"C","dex":"D","int":"-","fth":"-"},"defs":{"phys":65,"mag":50,"fire":45,"ltn":45,"dark":50},"stability":45,"weight":17,"durability":120,"skill":"Spin Slash","dmg_type":"Slash","cast":null,"fp":"12(-/13)","buy":null,"desc":"Bloodstained greatsword wielded by one of the Watchdogs of Farron, who preside over the slumber of fallen warriors. The blade is a reminder of the exile's past misdeeds.\nInhuman strength is required to wield this heaviest of curved greatswords.\nSkill: Spin Slash\nSlice into foes with a large spinning motion, and continue spinning to transition into a strong attack.","boss_weapon":false,"avail":"<p>Dropped by the Exile Watchdog that wields it in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Exile_Greatsword"},{"id":"falchion","kind":"weapon","name":"Falchion","page":"Falchion (Dark Souls III)","img":"assets/img/Falchion__Dark_Souls_III.webp","wtype":"Curved Sword","group":"melee","paired":false,"atk":{"phys":117,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":9,"dex":13,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":35,"weight":4,"durability":70,"skill":"Spin Slash","dmg_type":"Slash","cast":null,"fp":"6(-/12)","buy":null,"desc":"Standard curved sword and widely-used slashing weapon.\nThe falchion's flesh-rending slash attacks are greatly compromised against armor and tough scale-covered hides.\nSkill: Spin Slash\nSlice into foes with a large spinning motion, and continue spinning to transition into strong attack.","boss_weapon":false,"avail":"<p>Dropped by falchion-wielding Skeletons (with heads) in the <a data-e=\"undead-settlement\">Undead Settlement<\/a> and <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a>.<\/p>","notes":"<ul><li>When held in two hands, this weapon's attacks do not rebound off of shields.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Falchion_(Dark_Souls_III)"},{"id":"farron-greatsword","kind":"weapon","name":"Farron Greatsword","page":"Farron Greatsword","img":"assets/img/Farron_Greatsword.webp","wtype":"Ultra Greatsword","group":"melee","paired":false,"atk":{"phys":141,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":20,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":55,"mag":45,"fire":40,"ltn":40,"dark":45},"stability":45,"weight":12.5,"durability":90,"skill":"Parry","dmg_type":"Standard/Thrust","cast":null,"fp":null,"buy":null,"desc":"Greatsword of the Abyss Watchers which is atypically paired with an unusual dagger.\nThe dagger is utilized as a wedge in the left hand while the greatsword is held in the right, a unique technique that was synonymous with the Undead Legion. Confounds foes in the manner of wolves hunting prey.\nSkill: Parry\nDeflect an attack when timed properly and follow up with a critical hit, executed with the dagger.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-the-blood-of-the-wolf\">Soul of the Blood of the Wolf<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> at no soul cost.<\/p>","notes":"<ul><li>Deals increased damage to abyssal enemies.<\/li><\/ul>","from_soul":[{"soul":"soul-of-the-blood-of-the-wolf","cost":null}],"url":"https://darksouls.fandom.com/wiki/Farron_Greatsword"},{"id":"firelink-greatsword","kind":"weapon","name":"Firelink Greatsword","page":"Firelink Greatsword","img":"assets/img/Firelink_Greatsword.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":128,"mag":0,"fire":89,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":20,"dex":10,"int":10,"fth":10},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":55,"mag":35,"fire":40,"ltn":30,"dark":35},"stability":40,"weight":9,"durability":105,"skill":"Ember","dmg_type":"Standard","cast":null,"fp":"25(-/-)","buy":15000,"desc":"The Lords of Cinder linked the First Flame, and this Greatsword was wielded by their deific manifestation.\nThis coiled sword, found thrust in the bonfire, existed long before the throneless lords themselves.\nSkill: Ember\nThe fading flame momentarily illuminates and launches itself forward.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-the-lords\">Soul of the Lords<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"","from_soul":[{"soul":"soul-of-the-lords","cost":"15,000 souls"}],"url":"https://darksouls.fandom.com/wiki/Firelink_Greatsword"},{"id":"flamberge","kind":"weapon","name":"Flamberge","page":"Flamberge (Dark Souls III)","img":"assets/img/Flamberge__Dark_Souls_III.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":158,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":36,"psn":0,"fst":0},"req":{"str":15,"dex":14,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":50,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":35,"weight":8.5,"durability":70,"skill":"Stance","dmg_type":"Slash","cast":null,"fp":"-(17/20)","buy":null,"desc":"Greatsword with an undulating blade. The blade, resembling flame, was crafted to mutilate flesh and induce bleeding.\nSkill: Stance\nWhile in stance, use normal attack to break a foe's guard from below, and strong attack to slash upwards with a forward lunge.","boss_weapon":false,"avail":"<p>Drop from the Flamberge-wielding Thralls in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>, <a data-e=\"grand-archives\">Grand Archives<\/a> and Dreg Heap.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Flamberge_(Dark_Souls_III)"},{"id":"follower-javelin","kind":"weapon","name":"Follower Javelin","page":"Follower Javelin","img":"assets/img/Follower_Javelin.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":106,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":12,"int":0,"fth":0},"scale":{"str":"C","dex":"E","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":4,"durability":70,"skill":"Hurl Spear","dmg_type":"Thrust","cast":null,"fp":"15(-/-)","buy":null,"desc":"Light spear wielded by the Farron Followers. Balanced to allow for throwing.\nThe Followers attack in groups, surrounding foes, shielding themselves, and thrusting their spears at their foes. On a final command, they hurl their spears at their fallen foe, to give the retired warrior an honorable send-off.\nSkill: Hurl Spear\nEmulate the practice of the Followers by throwing an illusory spear that assumes temporary form.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"painted-world-of-ariandel\">Painted World of Ariandel<\/a>:<br><br>From the Snowfield bonfire, run to the right toward the collapsing snowy ridge. After falling down the collapsing ridge, hug the right wall to avoid the wolves. After a little bit of walking you will encounter a path up guarded by a wolf. Up at the very top of the path there is a group of about five Farron Followers who will all attack you at once if you get near, so prepare for a fight. Behind them is a corpse holding the Follower Javelin.<\/p>","notes":"<ul><li>Unlike other weapons, a jumping attack cannot be followed with another attack. This is possibly a bug.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Follower_Javelin"},{"id":"follower-sabre","kind":"weapon","name":"Follower Sabre","page":"Follower Sabre","img":"assets/img/Follower_Sabre.webp","wtype":"Curved Sword","group":"melee","paired":false,"atk":{"phys":108,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":9,"dex":14,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":4,"durability":70,"skill":"Prying Wedge","dmg_type":"Slash","cast":null,"fp":"9(-/9)","buy":null,"desc":"Great curved sword wielded by Farron Followers. Its great weight enables heavy-handed chain attacks.\nThe Followers brandish their swords to hunt warriors taken by the Abyss. Their technique is honed to face men, implying those yet to lose their human aspect are their likeliest prey.\nSkill: Prying Wedge\nA chain attack that wedges below foes and swings upward, breaking their guard. Strong attack can be used to follow up the onslaught with a fatal blow.","boss_weapon":false,"avail":"<p>From the <a data-e=\"painted-world-of-ariandel\">Ariandel Chapel<\/a>, head back toward the bridge and cut it down. Climb down the ladder and continue on the rooted path. After several drop-downs, there will be a circular area with several roots leading downward, the Follower Sabre will be on a corpse above a torch-carrying Farron Follower.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Follower_Sabre"},{"id":"follower-shield","kind":"weapon","name":"Follower Shield","page":"Follower Shield","img":"assets/img/Follower_Shield.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":84,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":9,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":80,"mag":50,"fire":35,"ltn":50,"dark":65},"stability":55,"weight":3.5,"durability":55,"skill":"Weapon Skill","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Standard shield used by the Farron Followers. Crafted with wood and reinforced with metal.\nImbued with a faint resistance to the Abyss.\nSkill: Weapon Skill\nEquipping this shield in the left hand allows one to perform the Skill of the right hand weapon.","boss_weapon":false,"avail":"<p>From the Snowy Mountain Pass bonfire, head forward until you reach the bell. Once you see the bell, head left until you reach the cliff and turn left again following the ridge; you should then see the corpse containing the Follower Shield.<\/p>","notes":"<p>Can be buffed and infused.<\/p>","url":"https://darksouls.fandom.com/wiki/Follower_Shield"},{"id":"follower-torch","kind":"weapon","name":"Follower Torch","page":"Follower Torch","img":"assets/img/Follower_Torch.webp","wtype":"Torch","group":"melee","paired":false,"atk":{"phys":90,"mag":0,"fire":65,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":0,"int":10,"fth":10},"scale":{"str":"D","dex":"E","int":"E","fth":"E"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":6,"durability":45,"skill":"Breathe Fire","dmg_type":"Strike","cast":null,"fp":"11(-/-)","buy":null,"desc":"An offensive torch used by the Farron Followers. Provides light and doubles as a weapon.\nSome forms of the Abyss manifest as pus within the body, treated from ancient times with fire.\nSkill: Breathe Fire\nSpit a combustible fuel across the torch to breathe flame in a front-sweeping motion.","boss_weapon":false,"avail":"<p>Can be found after the Snowy Mountain Pass bonfire. Proceed forward until you reach the bell. Run past it to just before the collapsing ridge leading to the <a data-e=\"earth-seeker\">Earth Seeker<\/a>. Instead of taking the ridge down, turn left and continue until you reach a cliff. Drop down to the path below the cliff and proceed right to find a corpse containing the weapon, guarded by a Farron Follower.<\/p>","notes":"<ul><li>For the purposes of critical attacks, this weapon uses the multipliers of the Hammer weapon class.<\/li><\/ul><p><br><br><\/p>","url":"https://darksouls.fandom.com/wiki/Follower_Torch"},{"id":"four-pronged-plow","kind":"weapon","name":"Four-Pronged Plow","page":"Four-Pronged Plow (Dark Souls III)","img":"assets/img/Four_Pronged_Plow__Dark_Souls_III.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":105,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":13,"dex":11,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":6.5,"durability":55,"skill":"Charge","dmg_type":"Thrust","cast":null,"fp":"13(-/9)","buy":null,"desc":"This four-pronged plow is shaped like a fist, and is a worker's tool in the Undead Settlement.\nNot originally intended for battle, but serves as a deadly weapon owing to its sharp points.\nSkill: Charge\nHold spear at waist and charge at foe. Only, it is important to have good footing.","boss_weapon":false,"avail":"<p>Dropped by Peasant Hollows who wield them in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Four-Pronged_Plow_(Dark_Souls_III)"},{"id":"frayed-blade","kind":"weapon","name":"Frayed Blade","page":"Frayed Blade","img":"assets/img/Frayed_Blade.webp","wtype":"Katana","group":"melee","paired":false,"atk":{"phys":101,"mag":0,"fire":0,"ltn":0,"dark":41},"aux":{"bld":34,"psn":0,"fst":0},"req":{"str":11,"dex":40,"int":null,"fth":null},"scale":{"str":"E","dex":"B","int":"-","fth":"-"},"defs":{"phys":45,"mag":25,"fire":30,"ltn":15,"dark":40},"stability":30,"weight":8,"durability":20,"skill":"Hold","dmg_type":"Slash/Thrust","cast":0,"fp":"-(18/11)","buy":5000,"desc":"A dragon weapon symbolizing Darkeater Midir.\nThe once-exquisite blade is now stained black, and frayed at the hilt. Without its sheath, it will soon crumble into nothing.\nSkill: Hold\nAssume a holding stance in which a normal attack sends a shockwave along the earth, and a strong attack commences a series of slashes.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-darkeater-midir\">Soul of Darkeater Midir<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> for 5,000 souls.<\/p>","notes":"<ul><li>It can deflect certain projectiles<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Frayed_Blade"},{"id":"friedes-great-scythe","kind":"weapon","name":"Friede's Great Scythe","page":"Friede's Great Scythe","img":"assets/img/Friede_s_Great_Scythe.webp","wtype":"Reaper","group":"melee","paired":false,"atk":{"phys":110,"mag":77,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":45},"req":{"str":12,"dex":16,"int":12,"fth":11},"scale":{"str":"E","dex":"B","int":"C","fth":"E"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":13,"durability":60,"skill":"Elfriede's Stance","dmg_type":"Slash","cast":null,"fp":"-(-/18)","buy":10000,"desc":"A great scythe wielded by Sister Elfriede, with a curved blade thinly coated by Painted World frost that easily breaks the guard of shields.\nIn the painting, the scythe is a symbol of a long-lost home, possibly explaining Elfriede's preference for it.\nSkill: Elfriede's Stance\nConjure a magic bladed support scythe into the left hand while the great scythe remains in the right, a stance derived from Elfriede's former swordmanship. Use normal attack to leap forward and swing twice, or strong attack to coat the earth with running frost.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-sister-friede\">Soul of Sister Friede<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> for 10,000 souls.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Friede's_Great_Scythe"},{"id":"fume-ultra-greatsword","kind":"weapon","name":"Fume Ultra Greatsword","page":"Fume Ultra Greatsword (Dark Souls III)","img":"assets/img/Fume_Ultra_Greatsword__Dark_Souls_III.webp","wtype":"Ultra Greatsword","group":"melee","paired":false,"atk":{"phys":149,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":50,"dex":10,"int":0,"fth":0},"scale":{"str":"A","dex":"E","int":"-","fth":"-"},"defs":{"phys":80,"mag":55,"fire":65,"ltn":60,"dark":65},"stability":55,"weight":25.5,"durability":170,"skill":"Stomp","dmg_type":"Strike","cast":null,"fp":"10(-/18)","buy":null,"desc":"This twisted sword, the heaviest of all ultra greatswords, resembles black slate.\nThis weapon, said to belong to a traitor from long ago, was so heavy that it found no owner, and became a forgotten relic of history.\nSkill: Stomp\nUse one's weight to lunge forward with a low stance and increased poise, and follow with a crushing strong attack.","boss_weapon":false,"avail":"<p>Obtained by defeating Knight Slayer Tsorig by the large lava pool in the Demon Ruins, beneath <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>.<\/p>","notes":"<p>Cannot be infused.<\/p>","url":"https://darksouls.fandom.com/wiki/Fume_Ultra_Greatsword_(Dark_Souls_III)"},{"id":"gaels-greatsword","kind":"weapon","name":"Gael's Greatsword","page":"Gael's Greatsword","img":"assets/img/Gael_s_Greatsword.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":147,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":19,"dex":13,"int":null,"fth":null},"scale":{"str":"C","dex":"D","int":"-","fth":"-"},"defs":{"phys":50,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":40,"weight":9,"durability":55,"skill":"Blade of Peril","dmg_type":"Strike/Thrust","cast":0,"fp":"8(17/17)","buy":20000,"desc":"Greatsword of Slave Knight Gael, the only weapon that he kept with him from beginning to end.\nOriginally an executioner's sword made for decapitation, this blade is heavily chipped and stained with the blood of countless battles.\nSkill: Blade of Peril\nA precarious technique unique to undead Gael. Leap in any direction, slamming the greatsword to the ground, then follow with normal attack for a large spinning slash, or strong attack to back-step and jump forward in an overhead slam.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-slave-knight-gael\">Soul of Slave Knight Gael<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> for 20,000 souls.<\/p>","notes":"<ul><li>One of the most versatile weapons in game due to its ability to deal Thrust and Strike damage exclusively with a very effective moveset.<\/li><li>Like the <a data-e=\"executioners-greatsword\">Executioner's Greatsword<\/a>, it is a very effective weapon to use against skeletal enemies.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Gael's_Greatsword"},{"id":"gargoyle-flame-hammer","kind":"weapon","name":"Gargoyle Flame Hammer","page":"Gargoyle Flame Hammer","img":"assets/img/Gargoyle_Flame_Hammer.webp","wtype":"Great Hammer","group":"melee","paired":false,"atk":{"phys":122,"mag":0,"fire":100,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":22,"dex":0,"int":9,"fth":9},"scale":{"str":"D","dex":"-","int":"E","fth":"E"},"defs":{"phys":55,"mag":40,"fire":35,"ltn":35,"dark":40},"stability":45,"weight":11,"durability":150,"skill":"Kindled Flurry","dmg_type":"Strike","cast":null,"fp":"12(-/15)","buy":null,"desc":"Stone torch hammer wielded by gargoyles of the Profaned Capital.\nThe Profaned Flame, which never goes out, imbues this weapon with a fire attack.\nSkill: Kindled Flurry\nAnchor weapon in earth and use strong attack to launch successive volleys of fire form the tip of the hammer.","boss_weapon":false,"avail":"<p>Dropped by hammer-wielding Gargoyles in the <a data-e=\"profaned-capital\">Profaned Capital<\/a> and <a data-e=\"grand-archives\">Grand Archives<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Gargoyle_Flame_Hammer"},{"id":"gargoyle-flame-spear","kind":"weapon","name":"Gargoyle Flame Spear","page":"Gargoyle Flame Spear","img":"assets/img/Gargoyle_Flame_Spear.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":90,"mag":0,"fire":83,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":15,"dex":18,"int":9,"fth":9},"scale":{"str":"E","dex":"D","int":"E","fth":"E"},"defs":{"phys":50,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":9.5,"durability":70,"skill":"Kindled Charge","dmg_type":"Thrust","cast":null,"fp":"13(-/15)","buy":null,"desc":"Stone torch spear wielded by gargoyles of the Profaned Capital.\nThe Profaned Flame, which never goes out, imbues this weapon with a fire attack.\nSkill: Kindled Charge\nHold spear at waist and charge at foe, and use momentum to transition to a fiery strong attack.","boss_weapon":false,"avail":"<ul><li>Dropped by spear-wielding Gargoyles in the <a data-e=\"profaned-capital\">Profaned Capital<\/a> and <a data-e=\"grand-archives\">Grand Archives<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Gargoyle_Flame_Spear"},{"id":"ghru-rotshield","kind":"weapon","name":"Ghru Rotshield","page":"Ghru Rotshield","img":"assets/img/Ghru_Rotshield.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":78,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":36,"fst":0},"req":{"str":5,"dex":0,"int":0,"fth":0},"scale":{"str":"E","dex":"-","int":"-","fth":"-"},"defs":{"phys":62,"mag":43,"fire":39,"ltn":34,"dark":37},"stability":44,"weight":1.5,"durability":55,"skill":"Shield Bash","dmg_type":"Strike","cast":null,"fp":"12(-/-)","buy":null,"desc":"A rotting makeshift shield scavenged by the forest-dwelling Ghrus.\nBarely effective as a shield. However, its rotten state has made it poisonous, and resistant to other poisons as a result.\nSkill: Shield Bash\nWithout lowering your guard, strike the enemy with the shield to knock them back or stagger them. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Dropped by spear-wielding Ghrus in <a data-e=\"farron-keep\">Farron Keep<\/a>.<\/li><li>Dropped by spear-wielding Smouldering Ghrus in <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Ghru_Rotshield"},{"id":"giant-door-shield","kind":"weapon","name":"Giant Door Shield","page":"Giant Door Shield","img":"assets/img/Giant_Door_Shield.webp","wtype":"Greatshield","group":"melee","paired":true,"atk":{"phys":107,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":45,"dex":null,"int":null,"fth":null},"scale":{"str":"C","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":75,"fire":45,"ltn":80,"dark":75},"stability":60,"weight":21.5,"durability":150,"skill":"Lockout","dmg_type":"Strike","cast":0,"fp":"-(17/20)","buy":null,"desc":"Unusually shaped paired greatshields resembling great doors.\nHeirlooms of the knight who was known as the protector of the meek, yet who failed to protect anyone.\nSkill: Lockout\nGet a stalwart defense, and shield bash, or strong attack for a heave that holds shields to block nearly all damage.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"the-dreg-heap\">The Dreg Heap<\/a>. Shortly past the <a data-e=\"the-dreg-heap\">Earthen Peak Ruins<\/a> bonfire, an Angel and several Thralls guard an open area. The Giant Door Shields can be found at the end of a path leading to the bottom of a cliff, where another Thrall guards it.<\/p>","notes":"<ul><li>Cannot be buffed offensively or defensively (e.g., neither <a data-e=\"magic-shield\">Magic Shield<\/a> nor <a data-e=\"blessed-weapon\">Blessed Weapon<\/a> can be applied, regardless of infusion or which hand the weapon is held in).<\/li><li>When out of FP, activating Lockout will still block without change, but the fortification state becomes obsolete, it simply becomes a regular block.<\/li><li>Blocking does not negate status effects, not even during its fortification state.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Giant_Door_Shield"},{"id":"glaive","kind":"weapon","name":"Glaive","page":"Glaive","img":"assets/img/Glaive.webp","wtype":"Halberd","group":"melee","paired":false,"atk":{"phys":141,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":17,"dex":11,"int":0,"fth":0},"scale":{"str":"D","dex":"E","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":11,"durability":95,"skill":"Spin Sweep","dmg_type":"Slash","cast":null,"fp":"8(-/14)","buy":3500,"desc":"This halberd with a large blade was a scythe refitted for battle.\nDesigned for slicing, and inflicts slash damage.\nSkill: Spin Sweep\nSweep foes in a large spinning motion, and utilize momentum to transition into an overhanded strong attack smash.","boss_weapon":false,"avail":"<p>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat<\/a> for 3,500 souls once he returns from his first scavenge run in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Glaive"},{"id":"golden-falcon-shield","kind":"weapon","name":"Golden Falcon Shield","page":"Golden Falcon Shield (Dark Souls III)","img":"assets/img/Golden_Falcon_Shield__Dark_Souls_III.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":74,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":59,"mag":45,"fire":39,"ltn":20,"dark":37},"stability":48,"weight":2.5,"durability":85,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"A metal shield fashioned in the form of a falcon with wings outstretched.\nThe golden falcon was the emblem of an ancient band of sellswords, and even to this day, many mercenaries remain who look upon it as a token of good fortune.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"road-of-sacrifices\">Crucifixion Woods<\/a> area of the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>. Near the end of the ruins that lead to the <a data-e=\"crystal-sage\">Crystal Sage<\/a>, there is an area to the right guarded by several Sage's Prentices and a Sage's Devout, with a stairway that eventually leads to a <a data-e=\"ring-of-sacrifice\">Ring of Sacrifice<\/a>. Before reaching the top of the stairs, exit out of the structure through the broken wall, and follow the ledges to the left, where the shield can be found on a corpse, overlooking the area guarded by the two Exile Watchdogs.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Golden_Falcon_Shield_(Dark_Souls_III)"},{"id":"golden-ritual-spear","kind":"weapon","name":"Golden Ritual Spear","page":"Golden Ritual Spear","img":"assets/img/Golden_Ritual_Spear.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":73,"mag":77,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":10,"int":18,"fth":14},"scale":{"str":"E","dex":"D","int":"-","fth":"B"},"defs":{"phys":40,"mag":30,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":3,"durability":50,"skill":"Steady Chant","dmg_type":"Thrust","cast":100,"fp":"9(-/-)","buy":null,"desc":"A ritual spear presented to Darkmoon Knights before Sulyvahn claimed the title of Pontiff.\nCan also be used as a staff. Sorceries cast using this weapon channel the wielder's faith.\nSkill: Steady Chant\nBoost the strength of sorceries for a very short period.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>. From the <a data-e=\"pontiff-sulyvahn\">Pontiff Sulyvahn<\/a> bonfire, exit the cathedral and hug the left wall, going indoors temporarily and then going up the stairs leading to the Deacons patrolling the upper walkway. Turn around and re-enter the cathedral, then cross the bridge and turn right, leading to a Mimic that drops it.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Golden_Ritual_Spear"},{"id":"golden-wing-crest-shield","kind":"weapon","name":"Golden Wing Crest Shield","page":"Golden Wing Crest Shield","img":"assets/img/Golden_Wing_Crest_Shield.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":102,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":75,"fire":50,"ltn":57,"dark":47},"stability":50,"weight":5.5,"durability":100,"skill":"Spell Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"A blue knight's shield engraved with a golden wing crest.\nThis shield is exceptional amongst the enchanted blue shields; not only does it boast high magic absorption, but also enables its wielder to parry spells.\nSkill: Spell Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand. Also deflects spells.","boss_weapon":false,"avail":"<p>Dropped by Lion Knight Albert after defeating him at the <a data-e=\"grand-archives\">Grand Archives<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Golden_Wing_Crest_Shield"},{"id":"gotthard-twinswords","kind":"weapon","name":"Gotthard Twinswords","page":"Gotthard Twinswords","img":"assets/img/Gotthard_Twinswords.webp","wtype":"Straight Sword","group":"melee","paired":true,"atk":{"phys":100,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":18,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":50,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":6.5,"durability":70,"skill":"Spin Slash","dmg_type":"Standard/Thrust","cast":null,"fp":"5(-/17)","buy":null,"desc":"The hunters known as the King's Black Hands wielded paired weapons. These belonged to Gotthard, who fled the castle.\nGotthard rose quickly through the knighthood, no surprise to those who have witnessed his swordsmanship.\nSkill:Spin Slash\nSlice into foes with a large spinning motion, and use strong attack to lengthen attack and end with a double-bladed thrust.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"lothric-castle\">Lothric Castle<\/a>, on the lifeless body of <a data-e=\"black-hand-gotthard\">Black Hand Gotthard<\/a>, just before the entrance to the <a data-e=\"grand-archives\">Grand Archives<\/a>. The body will only appear once the player has defeated the first three Lords of Cinder: <a data-e=\"abyss-watchers\">Abyss Watchers<\/a>, <a data-e=\"aldrich-devourer-of-gods\">Aldrich<\/a> and <a data-e=\"yhorm-the-giant\">Yhorm<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Gotthard_Twinswords"},{"id":"grass-crest-shield","kind":"weapon","name":"Grass Crest Shield","page":"Grass Crest Shield (Dark Souls III)","img":"assets/img/Grass_Crest_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":92,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":89,"mag":43,"fire":38,"ltn":33,"dark":36},"stability":50,"weight":4.5,"durability":75,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Old medium metal shield of unknown origin.\nThe grass crest is lightly imbued with magic, which slightly speeds stamina recovery.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>, near the Crucifixion Woods bonfire. The shield can be looted from a corpse lying beside a tree near the first Great Crab.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Grass_Crest_Shield_(Dark_Souls_III)"},{"id":"great-club","kind":"weapon","name":"Great Club","page":"Great Club (Dark Souls III)","img":"assets/img/Great_Club__Dark_Souls_III.webp","wtype":"Great Hammer","group":"melee","paired":false,"atk":{"phys":152,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":28,"dex":0,"int":0,"fth":0},"scale":{"str":"C","dex":"-","int":"-","fth":"-"},"defs":{"phys":55,"mag":40,"fire":45,"ltn":40,"dark":40},"stability":40,"weight":12,"durability":280,"skill":"Warcry","dmg_type":"Strike","cast":null,"fp":"20(-/-)","buy":null,"desc":"Wood club fashioned from the branch of a giant tree. Requires considerable strength to wield.\nA hard, durable weapon. Its weight makes it easier to break the guard of shields.\nSkill: Warcry\nLet out a spirited war cry that temporarily boosts attack, and enables special consecutive attacks.","boss_weapon":false,"avail":"<p>Guaranteed drop from the Exile Watchdog who wields it in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>.<\/p>","notes":"<ul><li>With a Heavy Infusion and 99 Strength, the Great Club has an attack rating of 641, and over 700 with Warcry active.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Great_Club_(Dark_Souls_III)"},{"id":"great-corvian-scythe","kind":"weapon","name":"Great Corvian Scythe","page":"Great Corvian Scythe","img":"assets/img/Great_Corvian_Scythe.webp","wtype":"Reaper","group":"melee","paired":false,"atk":{"phys":97,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":38,"psn":0,"fst":0},"req":{"str":16,"dex":18,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":20,"ltn":20,"dark":30},"stability":25,"weight":9,"durability":55,"skill":"Neck Swipe","dmg_type":"Slash","cast":null,"fp":"13(-/-)","buy":null,"desc":"Great scythe of the forlorn souls guided by heretical storytellers.\nThe mistress of the Painted World is said to wield a great scythe herself.\nGreat scythes inflict profuse bleeding, such that the blood splatters on the wielder.\nSkill: Neck Swipe\nThis attack aims for the scruff of a foe's neck, and when successful, functions as a head shot, inflicting heavy damage.","boss_weapon":false,"avail":"<p>Dropped by scythe-wielding Corvians.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Great_Corvian_Scythe"},{"id":"great-mace","kind":"weapon","name":"Great Mace","page":"Great Mace","img":"assets/img/Great_Mace.webp","wtype":"Great Hammer","group":"melee","paired":false,"atk":{"phys":185,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":32,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":55,"mag":45,"fire":50,"ltn":45,"dark":45},"stability":45,"weight":18,"durability":150,"skill":"Perseverance","dmg_type":"Strike","cast":null,"fp":"12(-/-)","buy":null,"desc":"Large mace wielded by the knights of the Cathedral of the Deep.\nThe extremely heavy strike attacks of this weapon are devastating and will break weaker shields with a single blow. Wielding such a weapon will require inhuman strength.\nSkill: Perseverance\nAnchor weapon in earth to temporarily boost poise. Damage reduced while activated.","boss_weapon":false,"avail":"<p><a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a><\/p><ul><li>Dropped by Cathedral Knights who wield them.<\/li><\/ul><p><a data-e=\"consumed-kings-garden\">Consumed King's Garden<\/a><\/p><ul><li>Dropped by Consumed King's Knights who wield them.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Great_Mace"},{"id":"great-machete","kind":"weapon","name":"Great Machete","page":"Great Machete (Dark Souls III)","img":"assets/img/Great_Machete__Dark_Souls_III.webp","wtype":"Greataxe","group":"melee","paired":false,"atk":{"phys":167,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":24,"dex":10,"int":0,"fth":0},"scale":{"str":"D","dex":"E","int":"-","fth":"-"},"defs":{"phys":50,"mag":40,"fire":35,"ltn":35,"dark":40},"stability":35,"weight":14,"durability":85,"skill":"Sharpen","dmg_type":"Slash","cast":null,"fp":"20(-/-)","buy":null,"desc":"This giant machete has a slash attack, and is a worker's tool in the Undead Settlement.\nThis dismantling tool was not originally intended for use in battle.\nSkill: Sharpen\nScrape the blade to sharpen and enable a cleaner cut.","boss_weapon":false,"avail":"<p>Dropped by Hollow Manservants in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Great_Machete_(Dark_Souls_III)"},{"id":"great-scythe","kind":"weapon","name":"Great Scythe","page":"Great Scythe (Dark Souls III)","img":"assets/img/Great_Scythe__Dark_Souls_III.webp","wtype":"Reaper","group":"melee","paired":false,"atk":{"phys":105,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":14,"dex":14,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":7,"durability":60,"skill":"Neck Swipe","dmg_type":"Slash","cast":null,"fp":"13(-/-)","buy":null,"desc":"Attacks with this large scythe, normally used for crop harvesting, are effective at breaking past shields.\nThe magnificent sharp curved blade instils fear in opponents. Perhaps it is their survival instinct at work.\nSkill: Neck Swipe\nThis attack aims for the scruff of a foe's neck, and when successful, functions as a head shot, inflicting heavy damage.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>. From the <a data-e=\"undead-settlement\">Dilapidated Bridge<\/a> bonfire, head onward and enter the destroyed house located in front of the graveyard where the <a data-e=\"giant-archer-of-the-undead-settlement\">giant archer<\/a>'s arrows start raining down. Go upstairs, turn around and jump toward the broken wooden floorboards to reach it.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Great_Scythe_(Dark_Souls_III)"},{"id":"great-wooden-hammer","kind":"weapon","name":"Great Wooden Hammer","page":"Great Wooden Hammer","img":"assets/img/Great_Wooden_Hammer.webp","wtype":"Great Hammer","group":"melee","paired":false,"atk":{"phys":125,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":0,"int":0,"fth":0},"scale":{"str":"C","dex":"-","int":"-","fth":"-"},"defs":{"phys":50,"mag":40,"fire":35,"ltn":35,"dark":40},"stability":40,"weight":6,"durability":135,"skill":"Spin Bash","dmg_type":"Strike","cast":null,"fp":"13(-/10)","buy":null,"desc":"This giant wooden hammer is a worker's tool in the Undead Settlement.\nIntended to grind flesh and bone to prepare for burial, rather than use in battle.\nSkill: Spin Bash\nBash foes with a large spinning motion, utilizing momentum to transition into a overhand strong attack smash.","boss_weapon":false,"avail":"<p>Dropped by Peasant Hollows who wield them in the <a data-e=\"undead-settlement\">Undead Settlement<\/a> and <a data-e=\"irithyll-dungeon\">Irithyll Dungeon<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Great_Wooden_Hammer"},{"id":"greataxe","kind":"weapon","name":"Greataxe","page":"Greataxe (Dark Souls III)","img":"assets/img/Greataxe__Dark_Souls_III.webp","wtype":"Greataxe","group":"melee","paired":false,"atk":{"phys":188,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":32,"dex":8,"int":0,"fth":0},"scale":{"str":"D","dex":"E","int":"-","fth":"-"},"defs":{"phys":55,"mag":45,"fire":40,"ltn":40,"dark":45},"stability":40,"weight":16,"durability":135,"skill":"Warcry","dmg_type":"Standard","cast":null,"fp":"20(-/-)","buy":null,"desc":"Greataxe resembling a hunk of raw iron.\nIf one possesses the inhuman strength required to lift the weapon, the great heft of its attacks will send foes flying.\nHowever, since every swing makes use of one's entire body, attacks leave the wielder wide open retaliation.\nSkill: Warcry\nLet out a spirited warcry that temporarily boosts attack.","boss_weapon":false,"avail":"<p><a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a><\/p><ul><li>Dropped by greataxe-wielding Large Hollow Soldiers.<\/li><\/ul><p><a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a><\/p><ul><li>Dropped by greataxe-wielding Large Devouts.<\/li><\/ul><p><a data-e=\"farron-keep\">Farron Keep<\/a><\/p><ul><li>Found in the ruined fortress. From the <a data-e=\"farron-keep\">Old Wolf of Farron<\/a> bonfire, take the lift up. The weapon can be looted from a corpse near the Stray Demon.<\/li><\/ul><p><a data-e=\"lothric-castle\">Lothric Castle<\/a><\/p><ul><li>Dropped by greataxe-wielding Large Hollow Soldiers.<\/li><\/ul>","notes":"<ul><li>Although the weapon description states that the axe resembles a hunk of iron, in actuality it is fully embossed on both sides with a full floral design.<\/li><li>The hollows that use this weapon never use its weapon art. They also hold it differently than you can.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Greataxe_(Dark_Souls_III)"},{"id":"greatlance","kind":"weapon","name":"Greatlance","page":"Greatlance","img":"assets/img/Greatlance.webp","wtype":"Pike","group":"melee","paired":false,"atk":{"phys":129,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":21,"dex":16,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":50,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":10.5,"durability":90,"skill":"Charge","dmg_type":"Thrust","cast":null,"fp":"15(-/15)","buy":null,"desc":"This lance features a long pole, and was originally intended to be used by knights for jousting.\nThis weapon is primarily used in charging attacks, and would require tremendous strength and dexterity to be handled by a mere foot soldier.\nSkill: Charge\nHold spear at waist and charge at foe. Only, it is important to have good footing.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"lothric-castle\">Lothric Castle<\/a>.<\/p><p>From the Dragon Barracks, go upstairs and head left to find the Greatlance guarded by a red-eyed Lothric Knight.<\/p>","notes":"<p>Can benefit from <a data-e=\"leo-ring\">Leo Ring<\/a>.<\/p>","url":"https://darksouls.fandom.com/wiki/Greatlance"},{"id":"greatshield-of-glory","kind":"weapon","name":"Greatshield of Glory","page":"Greatshield of Glory (Dark Souls III)","img":"assets/img/Greatshield_of_Glory__Dark_Souls_III.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":134,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":40,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":70,"fire":65,"ltn":52,"dark":63},"stability":80,"weight":18.5,"durability":190,"skill":"Shield Bash","dmg_type":"Strike","cast":null,"fp":"16(-/-)","buy":null,"desc":"A greatshield adorned with flowing patterns, a celebration of an ancient glory.\nBoasts the highest stability of such shields, but with reduced stamina regeneration speed.\nPerhaps it is glory that begets indolence.\nSkill: Shield Bash\nWithout lowering your guard, strike the enemy with the shield to knock them back or stagger them. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Dropped by a Mimic in the <a data-e=\"profaned-capital\">Profaned Capital<\/a>, in the treasury room to the right of <a data-e=\"yhorm-the-giant\">Yhorm the Giant<\/a>'s boss arena.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Greatshield_of_Glory_(Dark_Souls_III)"},{"id":"greatsword","kind":"weapon","name":"Greatsword","page":"Greatsword (Dark Souls III)","img":"assets/img/Greatsword__Dark_Souls_III.webp","wtype":"Ultra Greatsword","group":"melee","paired":false,"atk":{"phys":159,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":28,"dex":10,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":65,"mag":50,"fire":45,"ltn":45,"dark":50},"stability":45,"weight":20,"durability":100,"skill":"Stomp","dmg_type":"Standard","cast":null,"fp":"10(-/20)","buy":null,"desc":"This ultra greatsword, with its thick blade, is one of the heaviest of its kind.\nHighly destructive if intolerably heavy.\nThere would appear to be some credence to the rumors that this sword tested the true limits of human strength.\nSkill: Stomp\nUse one's weight to lunge forward with a low stance and increased poise, and follow with strong attack for a spinning slash.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"farron-keep\">Farron Keep<\/a>, on top of one of the two broken bridge sections, near the area with the first brazier and opposite to some <a data-e=\"purple-moss-clump\">Purple Moss Clumps<\/a>.<\/p>","notes":"<ul><li>At 99 Strength, a fully upgraded Heavy Greatsword has 676 AR.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Greatsword_(Dark_Souls_III)"},{"id":"greatsword-of-judgment","kind":"weapon","name":"Greatsword of Judgment","page":"Greatsword of Judgment","img":"assets/img/Greatsword_of_Judgment.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":110,"mag":86,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":17,"dex":15,"int":12,"fth":0},"scale":{"str":"D","dex":"D","int":"C","fth":"-"},"defs":{"phys":50,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":40,"weight":9,"durability":85,"skill":"Stance of Judgment","dmg_type":"Standard","cast":null,"fp":"-(19/22)","buy":3000,"desc":"A ceremonial sword, held in Pontiff Sulyvahn's left hand, representing the judgment of the moon, but with magic far closer to sorcery than any existing lunar power. Its dark blue hues, deeper than the darkest moon, reflect sorcerer Sulyvahn's true nature.\nSkill: Stance of Judgment\nAssume stance to unleash dark magic. Use normal attack for a lunging thrust, and strong attack to emit side-sweeping wave.","boss_weapon":true,"avail":"<p>Transpose the <a data-e=\"soul-of-pontiff-sulyvahn\">Soul of Pontiff Sulyvahn<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> for 3,000 souls.<\/p>","notes":"","from_soul":[{"soul":"soul-of-pontiff-sulyvahn","cost":"3,000 souls"}],"url":"https://darksouls.fandom.com/wiki/Greatsword_of_Judgment"},{"id":"gundyrs-halberd","kind":"weapon","name":"Gundyr's Halberd","page":"Gundyr's Halberd","img":"assets/img/Gundyr_s_Halberd.webp","wtype":"Halberd","group":"melee","paired":false,"atk":{"phys":145,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":30,"dex":15,"int":0,"fth":0},"scale":{"str":"C","dex":"E","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":13,"durability":500,"skill":"Champion's Charge","dmg_type":"Standard","cast":null,"fp":"15(-/15)","buy":null,"desc":"Halberd of Gundyr the Champion, received when he was charged with his duty.\nThis old cast-iron halberd has the power to break poise, and is said to never crumble, seeming to suggest that Gundyr was fated to eternal service from the beginning.\nSkill: Champion's Charge\nHold spear at waist and charge at foe, and use momentum to transition into sweeping strong attack.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-champion-gundyr\">Soul of Champion Gundyr<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"","from_soul":[{"soul":"soul-of-champion-gundyr","cost":null}],"url":"https://darksouls.fandom.com/wiki/Gundyr's_Halberd"},{"id":"halberd","kind":"weapon","name":"Halberd","page":"Halberd (Dark Souls III)","img":"assets/img/Halberd__Dark_Souls_III.webp","wtype":"Halberd","group":"melee","paired":false,"atk":{"phys":125,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":16,"dex":12,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":8,"durability":75,"skill":"Charge","dmg_type":"Standard/Thrust","cast":null,"fp":"15(-/13)","buy":1500,"desc":"This long-hilted weapon mixing spear and axe is difficult to handle, requiring both strength and dexterity.\nCan be thrust like a spear or swept sideways like an axe, making it a versatile weapon effective against multiple foes.\nSkill: Charge\nHold spear at waist and charge at foe. Use strong attack while charging to extend the length of the charge.","boss_weapon":false,"avail":"<p><a data-e=\"firelink-shrine\">Firelink Shrine<\/a><\/p><ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 1,500 souls.<\/li><\/ul><p><a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a><\/p><ul><li>Dropped by Large Hollow Soldiers who wield them.<\/li><\/ul><p><a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a><\/p><ul><li>Dropped by Large Devouts of the Deep who wield them.<\/li><\/ul><p><a data-e=\"lothric-castle\">Lothric Castle<\/a><\/p><ul><li>Dropped by Large Hollow Soldiers who wield them.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Halberd_(Dark_Souls_III)"},{"id":"hand-axe","kind":"weapon","name":"Hand Axe","page":"Hand Axe (Dark Souls III)","img":"assets/img/Hand_Axe__Dark_Souls_III.webp","wtype":"Axe","group":"melee","paired":false,"atk":{"phys":110,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":9,"dex":8,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":2.5,"durability":60,"skill":"Warcry","dmg_type":"Standard","cast":null,"fp":"20(-/-)","buy":null,"desc":"A crude hand-axe that serves both as a weapon, and a tool of many uses.\nFavored by pyromancers of the Great Swamp, this axe has a short range but only moderate weight, and reasonable damage. Easily wielded, and more powerful than it appears.\nSkill: Warcry\nLet out a spirited warcry that temporarily boosts attack.","boss_weapon":false,"avail":"<ul><li>Starting weapon of the <a data-e=\"pyromancer\">Pyromancer<\/a> class.<\/li><li><a data-e=\"undead-settlement\">Undead Settlement<\/a><ul><li>Found on a corpse next to <a data-e=\"cornyx-of-the-great-swamp\">Cornyx<\/a>'s cell, just above the <b>Cliff Underside<\/b> bonfire.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Hand_Axe_(Dark_Souls_III)"},{"id":"handmaids-dagger","kind":"weapon","name":"Handmaid's Dagger","page":"Handmaid's Dagger","img":"assets/img/Handmaid_s_Dagger.webp","wtype":"Dagger","group":"melee","paired":false,"atk":{"phys":85,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":4,"dex":8,"int":0,"fth":0},"scale":{"str":"E","dex":"E","int":"-","fth":"-"},"defs":{"phys":30,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":0.5,"durability":40,"skill":"Blind Spot","dmg_type":"Slash/Thrust","cast":null,"fp":"10(-/-)","buy":null,"desc":"Dagger used by handmaids of the Profaned Capital.\nEach successful attack replenishes a slight amount of FP.\nIt is said that these women took pleasure in wounding others.\nSkill: Blind Spot\nUse against shielded opponents to break through their guard by attacking from the side.","boss_weapon":false,"avail":"<p>Dropped by Jailer Handmaids in the <a data-e=\"profaned-capital\">Profaned Capital<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Handmaid's_Dagger"},{"id":"harald-curved-greatsword","kind":"weapon","name":"Harald Curved Greatsword","page":"Harald Curved Greatsword","img":"assets/img/Harald_Curved_Greatsword.webp","wtype":"Curved Greatsword","group":"melee","paired":false,"atk":{"phys":140,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":22,"dex":18,"int":null,"fth":null},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":60,"mag":50,"fire":40,"ltn":40,"dark":50},"stability":45,"weight":14,"durability":120,"skill":"Sever","dmg_type":"Slash","cast":0,"fp":"9(20/9)","buy":null,"desc":"Giant gold-decorated curved sword wielded by warriors of the Harald Legion, who sought the dark soul.\nThe swords sank into the dark with the legion, where their blades were severely corroded.\nSkill: Sever\nHold the giant blade with both hands and slash repeatedly at foe's feet.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"the-dreg-heap\">The Dreg Heap<\/a>.<\/p><p>From the <a data-e=\"the-dreg-heap\">Earthen Peak Ruins<\/a> bonfire, proceed through the area with the firing Angel. Keep descending while heading toward the general right direction until reaching the poison swamp. Run past a cluster of Poisonhorn Bugs. The greatsword can be looted from a corpse lying below a big log that serves as a bridge.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Harald_Curved_Greatsword"},{"id":"harpe","kind":"weapon","name":"Harpe","page":"Harpe","img":"assets/img/Harpe.webp","wtype":"Dagger","group":"melee","paired":false,"atk":{"phys":62,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":10,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":35,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":1.5,"durability":45,"skill":"Quickstep","dmg_type":"Slash/Thrust","cast":null,"fp":"5(-/-)","buy":null,"desc":"The large sickle-shaped body, used for severing corpses, is a worker's tool in the Undead Settlement.\nThe sharp edge is on the inside of the weapon, itself designed for cutting and pulling, the allowing for good damage against shielded foes.\nSkill: Quickstep\nInstantly step behind or around the side of foes. Especially effective when lock on to target.","boss_weapon":false,"avail":"<p>Dropped by the sickle-wielding Peasant Hollows in the <a data-e=\"undead-settlement\">Undead Settlement<\/a> and <a data-e=\"irithyll-dungeon\">Irithyll Dungeon<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Harpe"},{"id":"havels-greatshield","kind":"weapon","name":"Havel's Greatshield","page":"Havel's Greatshield (Dark Souls III)","img":"assets/img/Havel_s_Greatshield__Dark_Souls_III.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":143,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":40,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":83,"fire":83,"ltn":82,"dark":83},"stability":75,"weight":28,"durability":270,"skill":"Stone Flesh","dmg_type":"Strike","cast":null,"fp":"16(-/-)","buy":null,"desc":"A tremendously solid and heavy greatshield, cut straight from a great slab of stone.\nSaid to be a relic of the legendary Havel the Rock, along with the Dragon Tooth. The shield is imbued with a special power reminiscent of Havel himself.\nSkill: Stone Flesh\nRaise the shield in silent prayer, turning the user's body into a solid mass of stone.","boss_weapon":false,"avail":"<ul><li>Dropped by Havel the Rock in <a data-e=\"archdragon-peak\">Archdragon Peak<\/a>. Accessed by heading down the stairs from the <a data-e=\"archdragon-peak\">Great Belfry<\/a> bonfire, moving across the courtyard and up another set of stairs. There will be a ladder on the left side, ascend it and Havel can be found standing before a dead <a data-e=\"ancient-wyvern\">wyvern<\/a>.<\/li><li>Alternatively, the Man Serpent Summoners have a small chance of summoning Havel. The first time he is defeated, he will drop the greatshield along with the <a data-e=\"dragon-tooth\">Dragon Tooth<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Havel's_Greatshield_(Dark_Souls_III)"},{"id":"hawkwoods-shield","kind":"weapon","name":"Hawkwood's Shield","page":"Hawkwood's Shield","img":"assets/img/Hawkwood_s_Shield.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":72,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":5,"dex":0,"int":0,"fth":0},"scale":{"str":"E","dex":"-","int":"-","fth":"-"},"defs":{"phys":56,"mag":35,"fire":58,"ltn":45,"dark":55},"stability":41,"weight":2,"durability":60,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Shield that belonged to Hawkwood, a deserter from the Undead Legion.\nThe unique swordsmanship of the Watchers does not normally allow for the use of shields. The unique swordsmanship of the Watchers would not allow such a shield, and Hawkwood's very possession of it was telltale of his defeat.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"cemetery-of-ash\">Cemetery of Ash<\/a>, in front of a gravestone located on the right path before entering <a data-e=\"firelink-shrine\">Firelink Shrine<\/a>, guarded by a Starved Hound. It is the same grave where  <a data-e=\"hawkwood\">Hawkwood the Deserter<\/a> can sometimes be found praying.<\/p><p>The shield will only appear here if Hawkwood is killed, or after he leaves the shrine once the <a data-e=\"abyss-watchers\">Abyss Watchers<\/a> have been defeated.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Hawkwood's_Shield"},{"id":"heavy-crossbow","kind":"weapon","name":"Heavy Crossbow","page":"Heavy Crossbow (Dark Souls III)","img":"assets/img/Heavy_Crossbow__Dark_Souls_III.webp","wtype":"Crossbow","group":"ranged","paired":false,"atk":{"phys":72,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":8,"int":0,"fth":0},"scale":{"str":"-","dex":"-","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":4.5,"durability":55,"skill":"Tackle","dmg_type":"None","cast":null,"fp":"7(-/-)","buy":null,"desc":"A large, powerful crossbow. Must be readied before firing.\nBolts must be equipped in order to use crossbows. Up to two kinds of bolts can be equipped at a time, and these can be switched as necessary.\nSkill: Tackle\nLunge into a shoulder tackle, pushing back enemies to create distance.","boss_weapon":false,"avail":"<p>Dropped by the crossbow-wielding Cathedral Knight found on the rafters of the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Heavy_Crossbow_(Dark_Souls_III)"},{"id":"heretics-staff","kind":"weapon","name":"Heretic's Staff","page":"Heretic's Staff","img":"assets/img/Heretic_s_Staff.webp","wtype":"Staff","group":"catalyst","paired":false,"atk":{"phys":63,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":0,"int":16,"fth":0},"scale":{"str":"D","dex":"-","int":"B","fth":"-"},"defs":{"phys":30,"mag":25,"fire":10,"ltn":10,"dark":20},"stability":15,"weight":3,"durability":55,"skill":"Steady Chant","dmg_type":"Strike","cast":113,"fp":"7(-/-)","buy":null,"desc":"Catalyst used by generations of heretic sorcerers.\nSorcery is a logical academic discipline, and the power of sorceries depends heavily on the caster's intelligence.\nSkill: Steady Chant\nBoost the strength of sorceries for a very short period. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found on a corpse on the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>. From the <a data-e=\"road-of-sacrifices\">Crucifixion Woods<\/a> bonfire, head into the nearby ruins that lead to the <a data-e=\"crystal-sage\">Crystal Sage<\/a>. Inside the first room with several Sage's Prentice and a Sage's Devout the staff can be found inside an alcove on the first floor next to the stairs.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Heretic's_Staff"},{"id":"heysel-pick","kind":"weapon","name":"Heysel Pick","page":"Heysel Pick","img":"assets/img/Heysel_Pick.webp","wtype":"Hammer","group":"melee","paired":false,"atk":{"phys":93,"mag":70,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":10,"int":19,"fth":0},"scale":{"str":"D","dex":"E","int":"B","fth":"-"},"defs":{"phys":50,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":35,"weight":4.5,"durability":70,"skill":"Steady Chant","dmg_type":"Thrust","cast":102,"fp":"9(-/-)","buy":null,"desc":"Choice weapon of Yellowfinger Heysel, a Finger of Rosaria and xanthous scholar.\nThis is both a weapon and a sorcery staff. The gold specks are remnants of lost sorceries.\nSkill: Steady Chant\nFor a short moment, boost the strength of sorceries. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li><a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a><ul><li>Dropped by Yellowfinger Heysel. She will only drop it once, regardless of where she is defeated or if she invades the player multiple times.<\/li><\/ul><\/li><li><a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a><ul><li>Dropped by the Man-grub in Rosaria's Bed Chamber. It will only appear after both <a data-e=\"aldrich-devourer-of-gods\">Aldrich, Devourer of Gods<\/a> and <a data-e=\"yhorm-the-giant\">Yhorm the Giant<\/a> have been defeated.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Heysel_Pick"},{"id":"hollowslayer-greatsword","kind":"weapon","name":"Hollowslayer Greatsword","page":"Hollowslayer Greatsword","img":"assets/img/Hollowslayer_Greatsword.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":145,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":18,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":50,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":35,"weight":8.5,"durability":70,"skill":"Stance","dmg_type":"Standard/Thrust","cast":null,"fp":"-(17/20)","buy":1000,"desc":"Greatsword used for a lifetime by a masked knight. Harbors the fears that lurk within the minds of Hollows, and is particularly effective against them.\nBestowed to a proper Mirrah knight long ago. Two-hand to execute special sword techniques.\nSkill: Stance\nWhile in stance, use normal attack to break a foe's guard from below, and strong attack to slash upwards with a forward lunge.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-the-rotted-greatwood\">Soul of the Rotted Greatwood<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> for 1,000 souls.<\/p>","notes":"<ul><li>Deals 20% bonus damage to Hollow enemies (does not apply to hollowed players in PvP).<\/li><\/ul>","from_soul":[{"soul":"soul-of-the-rotted-greatwood","cost":"1,000 souls"}],"url":"https://darksouls.fandom.com/wiki/Hollowslayer_Greatsword"},{"id":"immolation-tinder","kind":"weapon","name":"Immolation Tinder","page":"Immolation Tinder","img":"assets/img/Immolation_Tinder.webp","wtype":"Halberd","group":"melee","paired":false,"atk":{"phys":118,"mag":0,"fire":75,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":18,"int":12,"fth":12},"scale":{"str":"D","dex":"D","int":"B","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":25,"weight":10,"durability":85,"skill":"Punitive Flame","dmg_type":"Thrust","cast":100,"fp":"20(-/-)","buy":null,"desc":"Profaned Flame wielded by the Irithyllian witches, frigid spirits roaming the Boreal Valley.\nThis torch, both a weapon and a staff, is enshrouded in an everlasting flame.\nSkill: Punitive Flame\nPunish foes with a flame that blankets the ground.","boss_weapon":false,"avail":"<p>Dropped by the Fire Witches in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/p>","notes":"<ul><li>Much like the <a data-e=\"gargoyle-flame-spear\">Gargoyle Flame Spear<\/a> and <a data-e=\"gargoyle-flame-hammer\">hammer<\/a>, the tinder can be used as a makeshift torch to light up spaces.<\/li><li>Due to the strong attack being used to cast sorcery, it's impossible to do a standard strong attack with this weapon.<\/li><li>The weapon's skill doesn't go nearly as far as when the fire witches use the same weapon art. It also lacks the explosive attack that can launch you in the air that the fire witches use against you, through this weapon.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Immolation_Tinder"},{"id":"irithyll-rapier","kind":"weapon","name":"Irithyll Rapier","page":"Irithyll Rapier","img":"assets/img/Irithyll_Rapier.webp","wtype":"Thrusting Sword","group":"melee","paired":false,"atk":{"phys":116,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":55},"req":{"str":10,"dex":16,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":3,"durability":70,"skill":"Shield Splitter","dmg_type":"Thrust","cast":null,"fp":"14(-/-)","buy":null,"desc":"Thrusting sword bestowed upon the Outrider Knights of the Boreal Valley. This weapon is shrouded in frost, and causes frostbite.\nEvery Outrider Knight one day devolves into a beast, constantly hounded by Pontiff Sulyvahn's black eyes.\nSkill: Shield Splitter\nAim carefully, and attack in a large forward lunge to pierce through enemy shields and inflict damage directly.","boss_weapon":false,"avail":"<p>Guaranteed drop from the Boreal Outrider Knight in <a data-e=\"lothric-castle\">Lothric Castle<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Irithyll_Rapier"},{"id":"irithyll-straight-sword","kind":"weapon","name":"Irithyll Straight Sword","page":"Irithyll Straight Sword","img":"assets/img/Irithyll_Straight_Sword.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":124,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":55},"req":{"str":12,"dex":14,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":50,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":35,"weight":4,"durability":80,"skill":"Stance","dmg_type":"Standard/Thrust","cast":null,"fp":"-(17/20)","buy":null,"desc":"Straight sword bestowed upon the Outrider Knights of the Boreal Valley. This weapon is enshrouded in frost, and causes frostbite.\nEvery Outrider Knight one day devolves into a beast, constantly hounded by Pontiff Sulyvahn's black eyes.\nSkill: Stance\nWhile in stance, use normal attack to break a foe's guard from below, and strong attack to slash upwards with a forward lunge.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>. Guaranteed drop from the Boreal Outrider Knight guarding the entrance to the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Irithyll_Straight_Sword"},{"id":"iron-round-shield","kind":"weapon","name":"Iron Round Shield","page":"Iron Round Shield (Dark Souls III)","img":"assets/img/Iron_Round_Shield__Dark_Souls_III.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":71,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":5,"dex":0,"int":0,"fth":0},"scale":{"str":"E","dex":"-","int":"-","fth":"-"},"defs":{"phys":67,"mag":44,"fire":38,"ltn":19,"dark":36},"stability":47,"weight":2,"durability":55,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"An orthodox, round small shield made from metal.\nSmall shields offer little damage absorption and stability, but they are lightweight and ideal for parrying.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Starting equipment for the Thief class.<\/li><li>Dropped by sword and shield-wielding Hollow Soldiers in the <a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a>, <a data-e=\"lothric-castle\">Lothric Castle<\/a> and <a data-e=\"grand-archives\">Grand Archives<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Iron_Round_Shield_(Dark_Souls_III)"},{"id":"izalith-staff","kind":"weapon","name":"Izalith Staff","page":"Izalith Staff","img":"assets/img/Izalith_Staff.webp","wtype":"Staff","group":"catalyst","paired":false,"atk":{"phys":120,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":0,"int":14,"fth":10},"scale":{"str":"D","dex":"D","int":"B","fth":"C"},"defs":{"phys":30,"mag":25,"fire":20,"ltn":20,"dark":20},"stability":15,"weight":3,"durability":55,"skill":"Steady Chant","dmg_type":"Strike","cast":100,"fp":"7(-/-)","buy":null,"desc":"Ancient catalyst of the Witch of Izalith and her daughters, used long before the dawn of chaos and of pyromancy.\nWith the birth of the Chaos Flame, the flame witches were at once both sorcerers and shamans. Faith adjusts the power of sorceries cast using this catalyst, and the staff also seems to boost the power of dark sorceries.\nSkill: Steady Chant\nBoost the strength of sorceries for a very short period. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>.<\/p><p>In the corridor with the Giant Hound Rat and numerous smaller Hound Rats before the Basilisks, there is an illusory wall that hides a chest. Behind that chest is a second illusory wall which leads to a drop-down alcove, above several Basilisks, where the staff can be found.<\/p>","notes":"<ul><li>As the longest staff in game, it has extended reach when casting <a data-e=\"farron-flashsword\">Farron Flashsword<\/a>.<\/li><li>This staff deals the most physical damage out of all the non-weapon staves.<\/li><\/ul><p><br><br><\/p>","url":"https://darksouls.fandom.com/wiki/Izalith_Staff"},{"id":"kite-shield","kind":"weapon","name":"Kite Shield","page":"Kite Shield","img":"assets/img/Kite_Shield.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":80,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":50,"fire":52,"ltn":33,"dark":50},"stability":47,"weight":4.5,"durability":80,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":4000,"desc":"An orthodox metal shield.\nMedium shields are the most average of shields, providing a practical balance of damage absorption, stability and weight.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Starting equipment of the Herald class.<\/li><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat<\/a> for 4,000 souls.<ul><li>Sold by <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> once she has been given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Kite_Shield"},{"id":"knight-shield","kind":"weapon","name":"Knight Shield","page":"Knight Shield (Dark Souls III)","img":"assets/img/Knight_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":79,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":13,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":51,"fire":46,"ltn":34,"dark":44},"stability":48,"weight":4.5,"durability":65,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":1500,"desc":"Orthodox shield of the kind commonly used by low-ranking knights.\nMedium shields are the most average of shields, providing a practical balance of damage absorption, stability and weight.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Starting equipment for the Knight class.<\/li><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 1,500 souls once he returns from pillaging the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> once she has been given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>, provided that he has returned from pillaging the Undead Settlement.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Knight_Shield_(Dark_Souls_III)"},{"id":"knights-crossbow","kind":"weapon","name":"Knight's Crossbow","page":"Knight's Crossbow","img":"assets/img/Knight_s_Crossbow.webp","wtype":"Crossbow","group":"ranged","paired":false,"atk":{"phys":40,"mag":0,"fire":0,"ltn":40,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":8,"int":0,"fth":0},"scale":{"str":"-","dex":"-","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":4,"durability":50,"skill":"Tackle","dmg_type":"None","cast":null,"fp":"7(-/-)","buy":3000,"desc":"Crossbow used by the proud knights of Lothric. It bears an elaborate gold design.\nThe crossbow has been blessed with the power of lightning, in anticipation of the use of Lightning Bolts.\nSkill: Tackle\nLunge into a shoulder tackle, pushing back enemies to create distance.","boss_weapon":false,"avail":"<ul><li>Dropped by <a data-e=\"lothric-knight-sword\">sword<\/a>-wielding Lothric Knights.<\/li><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 3,000 souls once he returns from pillaging <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> once she is given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>, provided that he has at attempted to pillage Irithyll of the Boreal Valley.<\/li><\/ul><\/li><\/ul>","notes":"<ul><li>This weapon is the only archery weapon in the entire game (including bows and greatbows) that has an elemental infusion.<\/li><li>Though it drops from Lothric knights, they don't actually use the weapon.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Knight's_Crossbow"},{"id":"large-club","kind":"weapon","name":"Large Club","page":"Large Club (Dark Souls III)","img":"assets/img/Large_Club__Dark_Souls_III.webp","wtype":"Great Hammer","group":"melee","paired":false,"atk":{"phys":148,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":22,"dex":0,"int":0,"fth":0},"scale":{"str":"C","dex":"-","int":"-","fth":"-"},"defs":{"phys":50,"mag":35,"fire":45,"ltn":40,"dark":35},"stability":40,"weight":10,"durability":125,"skill":"Warcry","dmg_type":"Strike","cast":null,"fp":"20(-/-)","buy":null,"desc":"Large wooden club. Requires considerable strength to wield.\nCharacterized by savage leaping attacks. Its weight makes it easier to break the guard of shields.\nSkill: Warcry\nLet out a spirited warcry that temporarily boosts attack, and enables a special consecutive strong attack.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, on a corpse near the Demon.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Large_Club_(Dark_Souls_III)"},{"id":"large-leather-shield","kind":"weapon","name":"Large Leather Shield","page":"Large Leather Shield (Dark Souls III)","img":"assets/img/Large_Leather_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":78,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":85,"mag":54,"fire":56,"ltn":58,"dark":48},"stability":51,"weight":3.5,"durability":75,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":800,"desc":"Orthodox round shield covered with leather.\nMedium shields are the most average of shields, providing a practical balance of damage absorption, stability and weight.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 800 souls.<\/p>","notes":"<ul><li>One can be traded with Pickle Pee in exchange for a <a data-e=\"twinkling-titanite\">Twinkling Titanite<\/a> (only once per playthrough).<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Large_Leather_Shield_(Dark_Souls_III)"},{"id":"leather-shield","kind":"weapon","name":"Leather Shield","page":"Leather Shield (Dark Souls III)","img":"assets/img/Leather_Shield__Dark_Souls_III.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":69,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":7,"dex":0,"int":0,"fth":0},"scale":{"str":"E","dex":"-","int":"-","fth":"-"},"defs":{"phys":52,"mag":38,"fire":40,"ltn":42,"dark":32},"stability":36,"weight":1.5,"durability":55,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":500,"desc":"An orthodox, round small shield covered with leather.\nSmall shields offer little damage absorption or stability, but they are lightweight and make ideal instruments for parrying.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Starting equipment for the Sorcerer class.<\/li><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 500 souls.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Leather_Shield_(Dark_Souls_III)"},{"id":"ledos-great-hammer","kind":"weapon","name":"Ledo's Great Hammer","page":"Ledo's Great Hammer","img":"assets/img/Ledo_s_Great_Hammer.webp","wtype":"Great Hammer","group":"melee","paired":false,"atk":{"phys":170,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":60,"dex":null,"int":null,"fth":null},"scale":{"str":"B","dex":"-","int":"-","fth":"-"},"defs":{"phys":85,"mag":55,"fire":60,"ltn":55,"dark":55},"stability":50,"weight":28,"durability":310,"skill":"Call to Stone","dmg_type":"Strike","cast":0,"fp":"25(-/25)","buy":null,"desc":"Great Hammer wielded by the Silver Knight Ledo. Ledo's Hammer is by far the heaviest weapon amongst those wielded by the knights of Anor Londo.\nLedo, an eccentric who traveled across the outskirts, became a close friend to the giants and even Havel, the Rock.\nSkill: Call to Stone\nSpin to lure stones to the steel hammer, and use strong attack to transition into an earth slam that shatters the stones in a shockwave.","boss_weapon":false,"avail":"<p>Dropped by Silver Knight Ledo.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Ledo's_Great_Hammer"},{"id":"light-crossbow","kind":"weapon","name":"Light Crossbow","page":"Light Crossbow (Dark Souls III)","img":"assets/img/Light_Crossbow__Dark_Souls_III.webp","wtype":"Crossbow","group":"ranged","paired":false,"atk":{"phys":64,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":8,"int":0,"fth":0},"scale":{"str":"-","dex":"-","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":3,"durability":45,"skill":"Tackle","dmg_type":"None","cast":null,"fp":"7(-/-)","buy":1000,"desc":"Standard crossbow wielded by common soldiers.\nMust be readied before firing.\nBolts must be equipped in order to use crossbows. Up to two kinds of bolt can be equipped at a time, and these can be switched between as necessary.\nSkill: Tackle\nLunge into a shoulder tackle, pushing back enemies to create distance.","boss_weapon":false,"avail":"<ul><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 1,000 souls.<\/li><li>Dropped by Hollow Soldiers.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Light_Crossbow_(Dark_Souls_III)"},{"id":"llewellyn-shield","kind":"weapon","name":"Llewellyn Shield","page":"Llewellyn Shield (Dark Souls III)","img":"assets/img/Llewellyn_Shield__Dark_Souls_III.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":76,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":68,"mag":69,"fire":63,"ltn":44,"dark":61},"stability":45,"weight":3,"durability":70,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Metal shield crafted by the great smith.\nFashioned from rare geisteel, it excels at various types of damage absorption.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Dropped by <a data-e=\"horace-the-hushed\">Horace the Hushed<\/a>. It can be obtained by killing him at any point in the game, including in <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Llewellyn_Shield_(Dark_Souls_III)"},{"id":"long-sword","kind":"weapon","name":"Long Sword","page":"Long Sword","img":"assets/img/Long_Sword.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":110,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":10,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":3,"durability":70,"skill":"Stance","dmg_type":"Standard/Thrust","cast":null,"fp":"-(17/20)","buy":1000,"desc":"A balanced, widely-used standard straight sword.\nInflicts reliable standard damage, as well as high thrust damage.\nSkill: Stance\nWhile in stance, use normal attack to break a foe's guard from below, and strong attack to slash upwards with a forward lunge.","boss_weapon":false,"avail":"<ul><li>Starting equipment of the Knight class.<\/li><li>Dropped by Hollow Soldiers who wield them.<\/li><li><a data-e=\"firelink-shrine\">Firelink Shrine<\/a><ul><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 1,000 souls.<\/li><\/ul><\/li><li><a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a><ul><li>Dropped by Sage's Prentices who wield them.<\/li><\/ul><\/li><li><a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a><ul><li>Dropped by Devouts of the Deep who wield them.<\/li><li>Dropped by Devout Bombers.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Long_Sword"},{"id":"longbow","kind":"weapon","name":"Longbow","page":"Longbow (Dark Souls III)","img":"assets/img/Longbow__Dark_Souls_III.webp","wtype":"Bow","group":"ranged","paired":false,"atk":{"phys":82,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":9,"dex":14,"int":0,"fth":0},"scale":{"str":"E","dex":"D","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":4,"durability":50,"skill":"Puncture","dmg_type":"None","cast":null,"fp":"-(9/9)","buy":null,"desc":"Longbow commonly used by hunters.\nArrows must be equipped in order to use bows. Up to two kinds of arrow can be equipped at a time, and these can be switched as necessary.\nSkill: Puncture\nPull the arrow further back for a more powerful shot that can also pierce shields.","boss_weapon":false,"avail":"<ul><li><a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a><ul><li>From the <a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a> bonfire, take down the stairs on the right and proceed onward through the area with two Starved Hounds and a couple of Large Hollow Soldiers. Climb up the stairs at the end and the bow can be looted from a corpse next to the first Pus of Man.<\/li><\/ul><\/li><li><a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a><ul><li>Dropped by bow-wielding Skeletons.<\/li><li>Dropped by the bow-wielding Skeleton Swordsmen.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Longbow_(Dark_Souls_III)"},{"id":"lorians-greatsword","kind":"weapon","name":"Lorian's Greatsword","page":"Lorian's Greatsword","img":"assets/img/Lorian_s_Greatsword.webp","wtype":"Ultra Greatsword","group":"melee","paired":false,"atk":{"phys":151,"mag":0,"fire":79,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":26,"dex":10,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"D","fth":"D"},"defs":{"phys":60,"mag":45,"fire":40,"ltn":40,"dark":45},"stability":45,"weight":14,"durability":115,"skill":"Flame of Lorian","dmg_type":"Standard/Thrust","cast":null,"fp":"10(-/18)","buy":null,"desc":"Ultra greatsword of Lorian, Prince Lothric's older brother. Cast in smoldering molten steel, and stained black.\nBefore Lorian embraced his brother's curse, he was a knight who single-handedly slayed the demon prince, but the victory eternally scorched his sword with flame.\nSkill: Flame of Lorian\nLunge forward to transform smolder into flame, and follow with strong attack to launch flame across ground.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-the-twin-princes\">Soul of the Twin Princes<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"<ul><li>Can be given to <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>, along with <a data-e=\"lothrics-holy-sword\">Lothric's Holy Sword<\/a>, to transpose them into the <a data-e=\"twin-princes-greatsword\">Twin Princes' Greatsword<\/a>.<\/li><\/ul>","from_soul":[{"soul":"soul-of-the-twin-princes","cost":null}],"url":"https://darksouls.fandom.com/wiki/Lorian's_Greatsword"},{"id":"lothric-knight-greatshield","kind":"weapon","name":"Lothric Knight Greatshield","page":"Lothric Knight Greatshield","img":"assets/img/Lothric_Knight_Greatshield.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":111,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":36,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":83,"fire":66,"ltn":54,"dark":63},"stability":64,"weight":15,"durability":140,"skill":"Shield Bash","dmg_type":"Strike","cast":null,"fp":"16(-/-)","buy":5000,"desc":"Greatshield of the renowned Lothric Knights, decorated with a holy symbol.\nThe knights who formed the High Priestess' guard carried greatshields such as these, which were granted high magic absorption through her blessing.\nSkill: Shield Bash\nWithout lowering your guard, strike the enemy with the shield to knock them back or stagger them. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Dropped by spear-wielding Lothric Knights.<\/li><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 5,000 souls after he returns from pillaging <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> if she is given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>, provided that he has successfully pillaged the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Lothric_Knight_Greatshield"},{"id":"lothric-knight-greatsword","kind":"weapon","name":"Lothric Knight Greatsword","page":"Lothric Knight Greatsword","img":"assets/img/Lothric_Knight_Greatsword.webp","wtype":"Ultra Greatsword","group":"melee","paired":false,"atk":{"phys":131,"mag":0,"fire":0,"ltn":87,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":24,"dex":16,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":55,"mag":45,"fire":40,"ltn":45,"dark":45},"stability":45,"weight":16.5,"durability":100,"skill":"Stomp","dmg_type":"Standard/Thrust","cast":null,"fp":"10(-/15)","buy":7000,"desc":"Ultra greatsword of the venerable knights of Lothric. Imbued with the strength of lightning, the trademark of dragon hunting.\nVery few have demonstrated the extreme strength and dexterity required for this weapon, even in the long history of the Lothric Knights.\nSkill: Stomp\nUse one's weight to lunge forward with a low stance and increased poise, and follow with strong attack for an upward slash.","boss_weapon":false,"avail":"<ul><li>Dropped by Lothric Knights who wield them.<\/li><li><a data-e=\"firelink-shrine\">Firelink Shrine<\/a><ul><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat<\/a> for 7,000 souls once he returns from his second scavenge expedition in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/li><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> once she has been given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>, by either killing him once he has successfully returned from pillaging Irithyll, or by looting his corpse there if he failed.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Lothric_Knight_Greatsword"},{"id":"lothric-knight-long-spear","kind":"weapon","name":"Lothric Knight Long Spear","page":"Lothric Knight Long Spear","img":"assets/img/Lothric_Knight_Long_Spear.webp","wtype":"Pike","group":"melee","paired":false,"atk":{"phys":112,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":20,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":8,"durability":80,"skill":"Charge","dmg_type":"Thrust","cast":null,"fp":"13(-/9)","buy":4500,"desc":"Long spear wielded by the proud Lothric Knights.\nDesigned for long-range thrusting.\nLothric spear knights are known for their steadfastness, and this spear boosts the poise of its wielder.\nSkill: Charge\nHold spear at waist and charge at foe. Use strong attack while charging to extend the length of the charge.","boss_weapon":false,"avail":"<ul><li>Dropped by pike-wielding Lothric Knights.<\/li><li><a data-e=\"firelink-shrine\">Firelink Shrine<\/a><ul><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 4,500 souls once he returns safely from pillaging <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/li><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> once she has been given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>, provided that Greirat has pillaged at least the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Lothric_Knight_Long_Spear"},{"id":"lothric-knight-shield","kind":"weapon","name":"Lothric Knight Shield","page":"Lothric Knight Shield","img":"assets/img/Lothric_Knight_Shield.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":83,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":59,"fire":53,"ltn":87,"dark":51},"stability":54,"weight":6,"durability":75,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":3500,"desc":"Shield of the renowned Lothric Knights, decorated with the royal crest.\nThe Lothric Knights contended with dragons, and their shields have suitably high lightning absorption befitting a Dragonslayer's arms.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Dropped by sword-wielding Lothric Knights.<\/li><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 3,000 souls once he returns from his second scavenge run in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Lothric_Knight_Shield"},{"id":"lothric-knight-sword","kind":"weapon","name":"Lothric Knight Sword","page":"Lothric Knight Sword","img":"assets/img/Lothric_Knight_Sword.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":103,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":11,"dex":18,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":35,"fire":25,"ltn":25,"dark":35},"stability":35,"weight":4,"durability":80,"skill":"Stance","dmg_type":"Standard/Thrust","cast":null,"fp":"-(17/20)","buy":4000,"desc":"A well-crafted straight sword designed for thrusting attacks, wielded by the venerable Knights of Lothric\nThe Knights of Lothric, with their drakes, once crushed anything that threatened their shores. Of course, that was a long, long time ago.\nSkill: Stance\nWhile in stance, use normal attack to break a foe's guard from below, and strong attack to slash upwards with a forward lunge.","boss_weapon":false,"avail":"<ul><li>Dropped by Lothric Knights who wield them.<\/li><li><a data-e=\"firelink-shrine\">Firelink Shrine<\/a><ul><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 4,000 souls once he returns from his second scavenge expedition in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Lothric_Knight_Sword"},{"id":"lothric-war-banner","kind":"weapon","name":"Lothric War Banner","page":"Lothric War Banner","img":"assets/img/Lothric_War_Banner.webp","wtype":"Pike","group":"melee","paired":false,"atk":{"phys":100,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":null,"psn":0,"fst":0},"req":{"str":14,"dex":14,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":5,"durability":70,"skill":"Lothric War Banner","dmg_type":"Thrust","cast":null,"fp":"35(-/-)","buy":null,"desc":"The flagpole that once carried the Lothric crest, and guided the knights long ago.\nThe tip of the pole is fitted with a sharply pointed decoration, letting it serve as a spear.\nSkill: Lothric War Banner\nWave the flagpole high in the air, like the days of yore, summoning an ethereal war banner that invigorates the attack of those who gather under it.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"the-dreg-heap\">The Dreg Heap<\/a>.<\/p><p>From the first bonfire, head forward and keep dropping through the level until breaking through a large stained glass window. Go through the archway on the left, immediately turn right and drop to a small patch of ash below. Head forward and enter the archway seen in the distance. Turn left, head toward the two Lothric Knights in this area and cross over the small fallen tower beyond them.<\/p><p>Keep heading forward and downward and make a big drop after passing the first Murkman, landing on another patch of ash barely visible below.<\/p><p>Keep advancing through the linear path and drop to a corridor with two red-eyed Lothric Knights. Follow this corridor until reaching a small terrace with a corpse holding the banner.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Lothric_War_Banner"},{"id":"lothrics-holy-sword","kind":"weapon","name":"Lothric's Holy Sword","page":"Lothric's Holy Sword","img":"assets/img/Lothric_s_Holy_Sword.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":107,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":18,"int":0,"fth":14},"scale":{"str":"D","dex":"D","int":"-","fth":"E"},"defs":{"phys":50,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":35,"weight":4,"durability":80,"skill":"Sacred Lothric Light","dmg_type":"Standard/Thrust","cast":null,"fp":"-(17/22)","buy":5000,"desc":"Prince Lothric's straight sword, blessed by Emma with potent magic.\nYoung Lothric was meant to be a champion, and was expected to wield this platinum sword, but some things will remain distant dreams forever.\nSkill: Sacred Lothric Light\nAssume stance to imbue sword with sacred light, and use strong attack to release light together with a great thrust of the sword.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-the-twin-princes\">Soul of the Twin Princes<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> for 5,000 souls.<\/p>","notes":"<ul><li>Can be given to <a data-e=\"ludleth-of-courland\">Ludleth<\/a>, along with <a data-e=\"lorians-greatsword\">Lorian's Greatsword<\/a>, to transpose them into the <a data-e=\"twin-princes-greatsword\">Twin Princes' Greatsword<\/a>.<\/li><\/ul>","from_soul":[{"soul":"soul-of-the-twin-princes","cost":"5,000 souls"}],"url":"https://darksouls.fandom.com/wiki/Lothric's_Holy_Sword"},{"id":"lucerne","kind":"weapon","name":"Lucerne","page":"Lucerne (Dark Souls III)","img":"assets/img/Lucerne__Dark_Souls_III.webp","wtype":"Halberd","group":"melee","paired":false,"atk":{"phys":126,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":15,"dex":13,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":7.5,"durability":75,"skill":"Spin Sweep","dmg_type":"Thrust","cast":null,"fp":"8(-/14)","buy":null,"desc":"A polearm with a sharp, hard pronged head that inflicts thrust attacks.\nThe Lucerne is wielded overhand like a hammer, or can be swung from the side to break through shields.\nSkill: Spin Sweep\nSweep foes in a large spinning motion, and utilize momentum to transition into an overhanded strong attack smash.","boss_weapon":false,"avail":"<p>Found on a corpse at the <a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a>, in the courtyard guarded by patrolling Lothric Knights, just before encountering <a data-e=\"vordt-of-the-boreal-valley\">Vordt of the Boreal Valley<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Lucerne_(Dark_Souls_III)"},{"id":"mace","kind":"weapon","name":"Mace","page":"Mace (Dark Souls III)","img":"assets/img/Mace__Dark_Souls_III.webp","wtype":"Hammer","group":"melee","paired":false,"atk":{"phys":115,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":7,"int":0,"fth":0},"scale":{"str":"C","dex":"E","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":5,"durability":80,"skill":"Perseverance","dmg_type":"Strike","cast":null,"fp":"9(-/-)","buy":600,"desc":"Iron hammer designed for use in battle. A common weapon for clerics.\nThis bladeless strike weapon is effective against most foes, and can break the guard of a shield.\nSkill: Perseverance\nAssume an unfaltering stance of prayer to temporarily boost poise. Damage reduced while activated.","boss_weapon":false,"avail":"<ul><li>Starting equipment of the <a data-e=\"cleric\">Cleric<\/a> class.<\/li><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 600 souls.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Mace_(Dark_Souls_III)"},{"id":"mail-breaker","kind":"weapon","name":"Mail Breaker","page":"Mail Breaker (Dark Souls III)","img":"assets/img/Mail_Breaker__Dark_Souls_III.webp","wtype":"Dagger","group":"melee","paired":false,"atk":{"phys":89,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":7,"dex":12,"int":0,"fth":0},"scale":{"str":"E","dex":"D","int":"-","fth":"-"},"defs":{"phys":35,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":1.5,"durability":50,"skill":"Shield Splitter","dmg_type":"Slash/Thrust","cast":null,"fp":"12(-/-)","buy":null,"desc":"A small sword made for thrusting attacks.\nThis hard, edgeless sword can pierce through tough armor, and boasts a deadly critical attack.\nSkill: Shield Splitter\nAim carefully, and attack in a large forward lunge to pierce through enemy shields and inflict damage directly.","boss_weapon":false,"avail":"<ul><li>Starting equipment for the <a data-e=\"sorcerer\">Sorcerer<\/a> class.<\/li><li><a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a><ul><li>Found on a corpse in the room prior to <a data-e=\"greirat-of-the-undead-settlement\">Greirat<\/a>'s cell.<\/li><\/ul><\/li><li><a data-e=\"firelink-shrine\">Firelink Shrine<\/a><ul><li><a data-e=\"sirris-of-the-sunless-realms\">Sirris<\/a> will gift the player a <a data-e=\"blessed-gem\">Blessed<\/a> Mail Breaker after assisting her in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Mail_Breaker_(Dark_Souls_III)"},{"id":"man-serpent-hatchet","kind":"weapon","name":"Man Serpent Hatchet","page":"Man Serpent Hatchet","img":"assets/img/Man_Serpent_Hatchet.webp","wtype":"Axe","group":"melee","paired":false,"atk":{"phys":125,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":16,"dex":13,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":4,"durability":80,"skill":"Warcry","dmg_type":"Standard","cast":null,"fp":"20(-/-)","buy":null,"desc":"Hatchet of the serpent men guarding Archdragon Peak.\nHas a unique, broadly curved blade that can sneak past shields.\nSkill: Warcry\nLet out a spirited warcry that temporarily boosts attack, and pierce through shields to inflict direct damage.","boss_weapon":false,"avail":"<p>Dropped by Man Serpents in <a data-e=\"archdragon-peak\">Archdragon Peak<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Man_Serpent_Hatchet"},{"id":"man-grubs-staff","kind":"weapon","name":"Man-grub's Staff","page":"Man-grub's Staff","img":"assets/img/Man_grub_s_Staff.webp","wtype":"Staff","group":"catalyst","paired":false,"atk":{"phys":60,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":9,"dex":0,"int":18,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":30,"mag":25,"fire":10,"ltn":10,"dark":15},"stability":15,"weight":3,"durability":65,"skill":"Steady Chant","dmg_type":"Strike","cast":100,"fp":"7(-/-)","buy":null,"desc":"Staff of the man-grubs who guard Rosaria's Bed Chamber. Their holy symbol is formed at the tip.\nWielder's luck strengthens the effects of sorceries.\nThe man-grubs have clearly been reborn, but as what?\nSkill: Steady Chant\nBoost the strength of sorceries for a very short period. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Reward for reaching Rank 2 in the <a data-e=\"rosarias-fingers\">Rosaria's Fingers<\/a> covenant.<\/p>","notes":"<ul><li>The Spell Buff is always displayed at 100, but it does in fact increase with higher investments of Luck.<\/li><li>However, weapon buffs such as <a data-e=\"great-magic-weapon\">Great Magic Weapon<\/a> will use the listed 100 Spell Buff.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Man-grub's_Staff"},{"id":"manikin-claws","kind":"weapon","name":"Manikin Claws","page":"Manikin Claws (Dark Souls III)","img":"assets/img/Manikin_Claws__Dark_Souls_III.webp","wtype":"Claw","group":"melee","paired":false,"atk":{"phys":81,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":8,"dex":18,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":1.5,"durability":35,"skill":"Quickstep","dmg_type":"Slash/Thrust","cast":null,"fp":"4(-/-)","buy":null,"desc":"Weapon of the Pale Shades, assassins of the Sable Church of Londor. The curved claws cause heavy bleeding.\nWhen two-handed, claws are equipped to each hand.\nSkill: Quick Step\nInstantly step behind or around the side of foes. Especially effective when locked on to target.","boss_weapon":false,"avail":"<p>Dropped by the Londor Pale Shade when defeated for the first time.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Manikin_Claws_(Dark_Souls_III)"},{"id":"mendicants-staff","kind":"weapon","name":"Mendicant's Staff","page":"Mendicant's Staff","img":"assets/img/Mendicant_s_Staff.webp","wtype":"Staff","group":"catalyst","paired":false,"atk":{"phys":60,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":7,"dex":0,"int":18,"fth":0},"scale":{"str":"D","dex":"-","int":"B","fth":"-"},"defs":{"phys":25,"mag":25,"fire":10,"ltn":10,"dark":15},"stability":10,"weight":2.5,"durability":55,"skill":"Steady Chant","dmg_type":"Strike","cast":100,"fp":"7(-/-)","buy":null,"desc":"A staff with a small bowl attached to the tip, similar to a mendicant's crook.\nAbsorb additional souls from fallen foes.\nThe staff's history is unclear. It may be a relic of an ancient serpent's greed, or a ritual artifact used to summon souls.\nSkill: Steady Chant\nBoost the strength of sorceries for a very short period. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Dropped by Man Serpent Summoners in <a data-e=\"archdragon-peak\">Archdragon Peak<\/a><\/p>","notes":"<ul><li>Can be traded with the <a data-e=\"nestling\">Nestling<\/a> in exchange for the <a data-e=\"sunlight-shield\">Sunlight Shield<\/a> (only once per playthrough).<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Mendicant's_Staff"},{"id":"millwood-battle-axe","kind":"weapon","name":"Millwood Battle Axe","page":"Millwood Battle Axe","img":"assets/img/Millwood_Battle_Axe.webp","wtype":"Axe","group":"melee","paired":false,"atk":{"phys":135,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":15,"dex":10,"int":0,"fth":0},"scale":{"str":"C","dex":"E","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":35,"weight":6.5,"durability":80,"skill":"Warcry","dmg_type":"Standard","cast":null,"fp":"20(-/-)","buy":null,"desc":"Battle axe wielded by Millwood Knights. Its blade is blessed by the symbol of the Ethereal Oak.\nA hefty axe normally wielded by the mightiest of warriors.\nSkill: Warcry\nThe unique warcry of the Millwood Knights entailed a leap straight toward the enemy and a fearsome roar.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"painted-world-of-ariandel\">Painted World of Ariandel<\/a>. Within the Snowfield area, enter the destroyed village guarded by Millwood Knights and ascend the tower. The axe is located on an isolated platform at the top that must be jumped or dropped down onto.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Millwood_Battle_Axe"},{"id":"millwood-greatbow","kind":"weapon","name":"Millwood Greatbow","page":"Millwood Greatbow","img":"assets/img/Millwood_Greatbow.webp","wtype":"Greatbow","group":"melee","paired":false,"atk":{"phys":139,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":28,"dex":12,"int":0,"fth":0},"scale":{"str":"C","dex":"E","int":"-","fth":"-"},"defs":{"phys":null,"mag":null,"fire":null,"ltn":null,"dark":null},"stability":null,"weight":9,"durability":100,"skill":"Pierce Earth","dmg_type":"None","cast":null,"fp":"-(20/20)","buy":null,"desc":"Greatbow crafted with black oak and wielded by Millwood Knights. Only specialized great arrows can be fired from the bow.\nIt is said that the Millwood Knights used these to face their sworn enemy, the Abyss Dragon.\nSkill: Pierce Earth\nFire a greatarrow with a burst of strength and a prayer that violently shakes its target and explodes on impact.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"painted-world-of-ariandel\">Snowfield<\/a> area of the Painted World of Ariandel.<\/p><p>Upon reaching the derelict village guarded by numerous Millwood Knights, an area looping back to the wooded overlook can be found, to the left before the valley where the <a data-e=\"champions-gravetender-and-gravetender-greatwolf\">Gravetender Greatwolf<\/a> ambushes the player for the second time. Hooking to the left again upon encountering the flame-tipped Birch Women, are two greatbow-wielding Millwood Knights and several wolves. The greatbow can be found on a corpse in the area, alongside five <a data-e=\"millwood-greatarrow\">Millwood Greatarrows<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Millwood_Greatbow"},{"id":"moaning-shield","kind":"weapon","name":"Moaning Shield","page":"Moaning Shield","img":"assets/img/Moaning_Shield.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":136,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":50,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":81,"fire":69,"ltn":76,"dark":67},"stability":77,"weight":21.5,"durability":205,"skill":"Moan","dmg_type":"Strike","cast":null,"fp":"10(-/-)","buy":null,"desc":"A deformed greatshield given to Eygon of Carim upon being conferred knighthood.\nThe giant woman's face that protects Eygon is that of his sister, some years his senior.\nSkill: Moan\nOffer a gentle prayer to the shield, causing the woman's face to give out a low moan and attract enemies.","boss_weapon":false,"avail":"<p>Dropped by <a data-e=\"eygon-of-carim\">Eygon of Carim<\/a>, or found on his corpse inside of <a data-e=\"irina-of-carim\">Irina of Carim<\/a>'s cell in the <a data-e=\"undead-settlement\">Undead Settlement<\/a> after completing her questline.<\/p>","notes":"<ul><li>Can be traded with Pickle Pee in exchange for a <a data-e=\"blessed-gem\">Blessed Gem<\/a> (only once per playthrough).<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Moaning_Shield"},{"id":"moonlight-greatsword","kind":"weapon","name":"Moonlight Greatsword","page":"Moonlight Greatsword (Dark Souls III)","img":"assets/img/Moonlight_Greatsword__Dark_Souls_III.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":69,"mag":130,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":16,"dex":11,"int":26,"fth":0},"scale":{"str":"E","dex":"-","int":"C","fth":"-"},"defs":{"phys":55,"mag":60,"fire":35,"ltn":35,"dark":40},"stability":40,"weight":10.5,"durability":75,"skill":"Moonlight Vortex","dmg_type":"Standard","cast":null,"fp":"18(-/-)","buy":10000,"desc":"Legendary dragon weapon associated with Seath the paledrake.\nCharge strong attack to its limit to unleash moonlight wave.\nOceiros, the Consumed King, was infatuated with the search for moonlight, but in the end, it never revealed itself to him.\nSkill: Moonlight Vortex\nDraw sword back and thrust to unleash torrential moonlight.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-consumed-oceiros\">Soul of Consumed Oceiros<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> for 10,000 souls.<\/p>","notes":"","from_soul":[{"soul":"soul-of-consumed-oceiros","cost":"10,000 souls"}],"url":"https://darksouls.fandom.com/wiki/Moonlight_Greatsword_(Dark_Souls_III)"},{"id":"morion-blade","kind":"weapon","name":"Morion Blade","page":"Morion Blade","img":"assets/img/Morion_Blade.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":131,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":34,"psn":0,"fst":0},"req":{"str":12,"dex":17,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":35,"fire":25,"ltn":25,"dark":35},"stability":35,"weight":4,"durability":80,"skill":"Stance","dmg_type":"Standard/Thrust","cast":null,"fp":"-(17/20)","buy":null,"desc":"A twisted sword resembling the towers of Londor's Sable Church. Eight branching blades and thorns induce bleeding.\nThe church's blessing makes the weapon revel in the agony of its owner. Heavy losses of HP boost attack, a curse most befitting its deformed appearance.\nSkill: Stance\nWhile in stance, use normal attack to break a foe's guard from below, and a strong attack to slash upwards with a forward lunge.","boss_weapon":false,"avail":"<p>Awarded by <a data-e=\"yuria-of-londor\">Yuria of Londor<\/a> for fulfilling her initial questline, where she tells the Ashen One how <a data-e=\"orbeck-of-vinheim\">Orbeck of Vinheim<\/a> has proclaimed himself to be the &quot;Lord of Hollows&quot; and asks if they can see into this matter.<\/p><p>The player must then obtain <a data-e=\"orbecks-ashes\">Orbeck's Ashes<\/a> and bring them back to Yuria in order to receive the sword.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Morion_Blade"},{"id":"mornes-great-hammer","kind":"weapon","name":"Morne's Great Hammer","page":"Morne's Great Hammer","img":"assets/img/Morne_s_Great_Hammer.webp","wtype":"Great Hammer","group":"melee","paired":false,"atk":{"phys":200,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":50,"dex":0,"int":0,"fth":30},"scale":{"str":"D","dex":"-","int":"-","fth":"D"},"defs":{"phys":70,"mag":50,"fire":45,"ltn":45,"dark":50},"stability":45,"weight":24,"durability":250,"skill":"Morne's Rage","dmg_type":"Strike","cast":null,"fp":"50(-/-)","buy":null,"desc":"Great Hammer bestowed upon Carim Knights with demonstrate outstanding strength and unwavering faith.\nDecorated by a warding charm of Carim Temple, and imbued with the twisted rage of Apostle Morne.\nSkill: Morne's Rage\nStick weapon into earth and emit a powerful shockwave. Also, similar to Perseverance, temporarily boosts poise and reduces damage received.","boss_weapon":false,"avail":"<ul><li>Dropped by <a data-e=\"eygon-of-carim\">Eygon of Carim<\/a>.<\/li><li>Alternatively, can be looted from Eygon's corpse in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, inside <a data-e=\"irina-of-carim\">Irina of Carim<\/a>'s cell. The body will appear after defeating the <a data-e=\"abyss-watchers\">Abyss Watchers<\/a> and <a data-e=\"dragonslayer-armour\">Dragonslayer Armour<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Morne's_Great_Hammer"},{"id":"morning-star","kind":"weapon","name":"Morning Star","page":"Morning Star (Dark Souls III)","img":"assets/img/Morning_Star__Dark_Souls_III.webp","wtype":"Hammer","group":"melee","paired":false,"atk":{"phys":122,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":11,"dex":9,"int":0,"fth":0},"scale":{"str":"D","dex":"E","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":5,"durability":75,"skill":"Perseverance","dmg_type":"Strike","cast":null,"fp":"9(-/-)","buy":2500,"desc":"Hammer with a sharp spike on its pommel.\nOne of the more barbaric cleric weapons.\nThe sharp thorns allow this strike weapon to induce bleeding.\nSkill: Perseverance\nAssume an unfaltering stance of prayer to temporarily boost poise. Damage reduced while activated.","boss_weapon":false,"avail":"<p>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 2,500 souls once she has been given the <a data-e=\"paladins-ashes\">Paladin's Ashes<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Morning_Star_(Dark_Souls_III)"},{"id":"murakumo","kind":"weapon","name":"Murakumo","page":"Murakumo (Dark Souls III)","img":"assets/img/Murakumo__Dark_Souls_III.webp","wtype":"Curved Greatsword","group":"melee","paired":false,"atk":{"phys":132,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":20,"dex":18,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":55,"mag":40,"fire":35,"ltn":35,"dark":40},"stability":45,"weight":11,"durability":105,"skill":"Spin Slash","dmg_type":"Slash","cast":null,"fp":"9(-/15)","buy":null,"desc":"The curved greatsword of Alva, Seeker of the Spurned, specially forged in an eastern land. Sharp but heavy, this sword requires extreme strength and dexterity to wield.\nThe search for the spurned had no end, and so the wayfaring knight warmed to a most deformed weapon.\nSkill: Spin Slash\nSlice into foes with a large spinning motion, and continue spinning to transition into a strong attack.","boss_weapon":false,"avail":"<p>Guaranteed drop from Alva, Seeker of the Spurned in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>, who invades as a dark spirit just before entering the <a data-e=\"irithyll-dungeon\">Irithyll Dungeon<\/a>. The player must be Embered in order to be invaded.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Murakumo_(Dark_Souls_III)"},{"id":"murky-hand-scythe","kind":"weapon","name":"Murky Hand Scythe","page":"Murky Hand Scythe","img":"assets/img/Murky_Hand_Scythe.webp","wtype":"Dagger","group":"melee","paired":false,"atk":{"phys":72,"mag":0,"fire":0,"ltn":0,"dark":22},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":6,"dex":11,"int":11,"fth":11},"scale":{"str":"D","dex":"D","int":"E","fth":"E"},"defs":{"phys":35,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":2,"durability":50,"skill":"Quickstep","dmg_type":"Slash","cast":0,"fp":"5(-/-)","buy":null,"desc":"A short-shafted hand scythe wielded by the murkmen who rise from the depths.\nEnveloped by a black dampness, and imbued with the strength of dark.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"the-dreg-heap\">the Dreg Heap<\/a>. After dropping through the glass ceiling, a set of stairs to the left will lead over a bookcase. A corpse will be holding the weapon.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Murky_Hand_Scythe"},{"id":"murky-longstaff","kind":"weapon","name":"Murky Longstaff","page":"Murky Longstaff","img":"assets/img/Murky_Longstaff.webp","wtype":"Staff","group":"catalyst","paired":false,"atk":{"phys":86,"mag":0,"fire":0,"ltn":0,"dark":20},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":6,"dex":0,"int":12,"fth":0},"scale":{"str":"D","dex":"D","int":"B","fth":"E"},"defs":{"phys":30,"mag":20,"fire":10,"ltn":10,"dark":25},"stability":15,"weight":3,"durability":55,"skill":"Chant from the Depths","dmg_type":"Strike","cast":100,"fp":"7(-/-)","buy":null,"desc":"The long-handled staff wielded by the murkmen who rise from the depths.\nSlathered with a black murkiness, and fit for dark sorceries.\nSkill: Chant from the Depths\nWorks with staff equipped in left or right hand. Briefly boosts the strength of dark sorceries.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"the-dreg-heap\">The Dreg Heap<\/a>. From <a data-e=\"the-dreg-heap\">The Dreg Heap<\/a> bonfire, proceed through the level until the church with two Lothric Knights. When leaving the church, proceed toward the right. In the back room of the building, a corpse will be holding the staff.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Murky_Longstaff"},{"id":"notched-whip","kind":"weapon","name":"Notched Whip","page":"Notched Whip (Dark Souls III)","img":"assets/img/Notched_Whip__Dark_Souls_III.webp","wtype":"Whip","group":"melee","paired":false,"atk":{"phys":95,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":6,"dex":19,"int":0,"fth":0},"scale":{"str":"-","dex":"D","int":"-","fth":"-"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":10,"dark":15},"stability":10,"weight":2,"durability":50,"skill":"Impact","dmg_type":"Slash","cast":null,"fp":"14(-/-)","buy":null,"desc":"A whip with thorny spikes that shred skin, causing heavy bleeding.\nThe Cleansing Chapel uses whips such as these in order to produce the drops as puddles to wipe clean during its rituals.\nSkill: Impact\nStrike from the left to evade shields and deal a stinging blow that temporarily slows stamina recovery. The shackles of bondage lie deep in the hearts of all humankind.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>, on a corpse lying on the right side of the Cleansing Chapel.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Notched_Whip_(Dark_Souls_III)"},{"id":"old-kings-great-hammer","kind":"weapon","name":"Old King's Great Hammer","page":"Old King's Great Hammer","img":"assets/img/Old_King_s_Great_Hammer.webp","wtype":"Great Hammer","group":"melee","paired":false,"atk":{"phys":180,"mag":0,"fire":69,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":30,"dex":0,"int":10,"fth":10},"scale":{"str":"D","dex":"-","int":"D","fth":"D"},"defs":{"phys":60,"mag":45,"fire":40,"ltn":40,"dark":45},"stability":45,"weight":18.5,"durability":185,"skill":"Molten Perseverance","dmg_type":"Strike","cast":null,"fp":"12(-/15)","buy":null,"desc":"Great Hammer of the Old Demon King.\nThis weapon has survived since old Izalith, and is imbued with remnants of the Chaos Flame.\nSkill: Molten Perseverance\nAnchor weapon in earth to temporarily boost poise, and use strong attack to repeatedly stab earth to trigger molten explosions.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-the-old-demon-king\">Soul of the Old Demon King<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"","from_soul":[{"soul":"soul-of-the-old-demon-king","cost":null}],"url":"https://darksouls.fandom.com/wiki/Old_King's_Great_Hammer"},{"id":"old-wolf-curved-sword","kind":"weapon","name":"Old Wolf Curved Sword","page":"Old Wolf Curved Sword","img":"assets/img/Old_Wolf_Curved_Sword.webp","wtype":"Curved Greatsword","group":"melee","paired":false,"atk":{"phys":155,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":19,"dex":25,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":55,"mag":45,"fire":40,"ltn":40,"dark":45},"stability":45,"weight":13,"durability":95,"skill":"Wolf Leap","dmg_type":"Slash","cast":null,"fp":"10(-/15)","buy":null,"desc":"Curved sword bearing the soul of the old wolf that stays with the Watchdogs of Farron.\nThis sword, like a wolf on the prowl, boosts attack and restores HP with each consecutive hit.\nSkill: Wolf Leap\nSlice into foes with a large spinning motion, then leap out of harms way and follow with a strong attack.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"farron-keep\">Farron Keep<\/a>. Reward for reaching Rank 1 in the <a data-e=\"watchdogs-of-farron\">Watchdogs of Farron<\/a> covenant.<\/p>","notes":"<ul><li>Boosts attacks by 10, as long attacking persists. See also the effect of the <a data-e=\"pontiffs-right-eye\">Pontiff's Right Eye<\/a>.<\/li><li>After six consecutive hits, it restores 120 HP. See also the effect of the <a data-e=\"pontiffs-left-eye\">Pontiff's Left Eye<\/a>.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Old_Wolf_Curved_Sword"},{"id":"onikiri-and-ubadachi","kind":"weapon","name":"Onikiri and Ubadachi","page":"Onikiri and Ubadachi","img":"assets/img/Onikiri_and_Ubadachi.webp","wtype":"Katana","group":"melee","paired":true,"atk":{"phys":104,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":13,"dex":25,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":45,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":30,"weight":8.5,"durability":35,"skill":"Onislayer","dmg_type":"Slash/Thrust","cast":null,"fp":"20(-/-)","buy":null,"desc":"The hunters known as the King's Black Hands wielded paired weapons. These belonged to Kamui, who looked after the prince.\nKamui brought Onikiri with him to the Undead Settlement, where he forged Ubadachi, and was finally prepared to join the ranks of the royal hunters.\nSkill: Onislayer\nLeap forward and slash mercilessly with both blades, cutting open foes.","boss_weapon":false,"avail":"<p>Dropped by Black Hand Kamui after defeating him at the <a data-e=\"grand-archives\">Grand Archives<\/a>.<\/p>","notes":"<ul><li>Shares the same skill as the <a data-e=\"claw\">Claw<\/a>, although they are called different names.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Onikiri_and_Ubadachi"},{"id":"onislayer-greatbow","kind":"weapon","name":"Onislayer Greatbow","page":"Onislayer Greatbow","img":"assets/img/Onislayer_Greatbow.webp","wtype":"Greatbow","group":"melee","paired":false,"atk":{"phys":111,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":24,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":7.5,"durability":65,"skill":"Puncturing Arrow","dmg_type":"None","cast":null,"fp":"-(17/17)","buy":null,"desc":"A unique greatbow handed down in an eastern land, where tales are told of its use in slaying giant horned oni.\nDrawing a bow of this size takes time, and leaves the user vulnerable. Only specialized great arrows can be fired from the bow.\nSkill: Puncturing Arrow\nMasterfully fires off a great arrow that pierces through all enemies in its path, inflicting damage.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"profaned-capital\">Profaned Capital<\/a>. From the <a data-e=\"profaned-capital\">Profaned Capital<\/a> bonfire, climb down the ladder towards <a data-e=\"yhorm-the-giant\">Yhorm the Giant<\/a>'s arena, and head towards the bridge guarded by the Headless Gargoyle. Drop off the right side of the bridge, and it can be found on a corpse along with eight <a data-e=\"onislayer-greatarrow\">Onislayer Greatarrows<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Onislayer_Greatbow"},{"id":"onyx-blade","kind":"weapon","name":"Onyx Blade","page":"Onyx Blade","img":"assets/img/Onyx_Blade.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":80,"mag":0,"fire":0,"ltn":0,"dark":115},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":12,"int":15,"fth":15},"scale":{"str":"E","dex":"E","int":"D","fth":"D"},"defs":{"phys":50,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":35,"weight":9,"durability":75,"skill":"Elfriede's Blackflame","dmg_type":"Standard/Thrust","cast":null,"fp":"19(-/-)","buy":null,"desc":"Elfriede, the eldest amongst her sisters and leader of the Sable Church, bestowed this sword to her knight.\nOnly, the sword was a farewell gift, and acceptance signified the knight's resignation from Elfriede's service.\nSkill: Elfriede's Blackflame\nEnwreath blade with blackflame, born of the similarly-hued flame that smolders within her.","boss_weapon":false,"avail":"<p>Dropped by <a data-e=\"sir-vilhelm\">Sir Vilhelm<\/a> when he is defeated in the <a data-e=\"painted-world-of-ariandel\">Corvian Settlement<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Onyx_Blade"},{"id":"painting-guardians-curved-sword","kind":"weapon","name":"Painting Guardian's Curved Sword","page":"Painting Guardian's Curved Sword","img":"assets/img/Painting_Guardian_s_Curved_Sword.webp","wtype":"Curved Sword","group":"melee","paired":false,"atk":{"phys":88,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":7,"dex":19,"int":0,"fth":0},"scale":{"str":"E","dex":"B","int":"-","fth":"-"},"defs":{"phys":35,"mag":25,"fire":25,"ltn":25,"dark":25},"stability":25,"weight":1.5,"durability":55,"skill":"Chained Dance","dmg_type":"Slash","cast":null,"fp":"5(-/15)","buy":null,"desc":"A weapon described in legends passed down amongst heretics, wielded by the Painting Guardians.\nA uniquely shaped weapon with a flat tip.\nSkill: Chained Dance\nExecute relentless consecutive attacks while tracing a circle in a unique dance of deadly grace.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>, on a corpse in the tower of the <a data-e=\"irithyll-of-the-boreal-valley\">Church of Yorshka<\/a>. After unlocking the <a data-e=\"anor-londo\">Prison Tower<\/a> bonfire, drop into the tower and navigate a series of drop-downs. The <a data-e=\"painting-guardian-set\">Painting Guardian Set<\/a> is also found in this same area.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Painting_Guardian's_Curved_Sword"},{"id":"parrying-dagger","kind":"weapon","name":"Parrying Dagger","page":"Parrying Dagger (Dark Souls III)","img":"assets/img/Parrying_Dagger__Dark_Souls_III.webp","wtype":"Dagger","group":"melee","paired":false,"atk":{"phys":60,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":5,"dex":14,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":30,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":1,"durability":40,"skill":"Parry","dmg_type":"Slash/Thrust","cast":null,"fp":null,"buy":2000,"desc":"Dagger with a greatly curved guard.\nA dagger made especially for parrying which is usually equipped in one's left hand in place of a shield.\nSkill: Parry\nDeflect an attack when timed properly and follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Sold by <a data-e=\"unbreakable-patches\">Unbreakable Patches<\/a> for 2,000 souls.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Parrying_Dagger_(Dark_Souls_III)"},{"id":"partizan","kind":"weapon","name":"Partizan","page":"Partizan (Dark Souls III)","img":"assets/img/Partizan__Dark_Souls_III.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":108,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":12,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":6.5,"durability":65,"skill":"Spin Sweep","dmg_type":"Standard/Thrust","cast":null,"fp":"11(-/11)","buy":null,"desc":"Spear with blade attached to broad point. Long reach, and can be used with shield up. Attacks faster with shield down.\nThis weapon can utilize its blade for slicing attacks, and is generally adaptable to many situations, but in cramped quarters, its slices ricochet off walls.\nSkill: Spin Sweep\nSweep foes in a large spinning motion, and utilize momentum to transition into an overhanded strong attack smash.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, on a hanging corpse above the stairs leading out of the <a data-e=\"undead-settlement\">Cliff Underside<\/a> bonfire. The corpse must be freed with a projectile weapon before the weapon can be obtained.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Partizan_(Dark_Souls_III)"},{"id":"pickaxe","kind":"weapon","name":"Pickaxe","page":"Pickaxe (Dark Souls III)","img":"assets/img/Pickaxe__Dark_Souls_III.webp","wtype":"Great Hammer","group":"melee","paired":false,"atk":{"phys":140,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":9,"int":0,"fth":0},"scale":{"str":"C","dex":"-","int":"-","fth":"-"},"defs":{"phys":50,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":40,"weight":8,"durability":105,"skill":"Galvanize","dmg_type":"Thrust","cast":null,"fp":"11(-/-)","buy":null,"desc":"Tool used by a miner for digging up earth. Not intended for use in battle.\nYet the strong downward swing of this tool once shattered large boulders, and easily punctures weaker armor.\nSkill: Galvanize\nTemporarily boost stamina recovery speed by sheer force of will, which an old miner needed to get through the day.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"irithyll-dungeon\">Irithyll Dungeon<\/a>, on a corpse near the sleeping Giant Slave.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Pickaxe_(Dark_Souls_III)"},{"id":"pierce-shield","kind":"weapon","name":"Pierce Shield","page":"Pierce Shield (Dark Souls III)","img":"assets/img/Pierce_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":87,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":93,"mag":62,"fire":50,"ltn":31,"dark":48},"stability":53,"weight":3.5,"durability":90,"skill":"Shield Bash","dmg_type":"Thrust","cast":null,"fp":"14(-/-)","buy":3000,"desc":"An unusual style of round shield peculiar to the knights of Catarina.\nThe center of the shield features a large, sharpened spike, which is used to skewer opponents.\nSkill: Shield Bash\nWithout lowering your guard, strike the enemy with the shield to knock them back or stagger them. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Dropped by <a data-e=\"siegward-of-catarina\">Siegward of Catarina<\/a> if he dies at any point during his quest.<\/li><li>Sold by <a data-e=\"unbreakable-patches\">Unbreakable Patches<\/a> for 3,000 souls.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Pierce_Shield_(Dark_Souls_III)"},{"id":"pike","kind":"weapon","name":"Pike","page":"Pike (Dark Souls III)","img":"assets/img/Pike__Dark_Souls_III.webp","wtype":"Pike","group":"melee","paired":false,"atk":{"phys":105,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":14,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":7.5,"durability":80,"skill":"Charge","dmg_type":"Thrust","cast":null,"fp":"13(-/9)","buy":null,"desc":"Long spear with a very long hilt. Designed for long-range thrusting.\nHas the longest range of the non-projectile weapons, but its very length makes it unwanted in certain situations.\nSkill: Charge\nHold spear at waist and charge at foe. Use strong attack while charging to extend distance.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>:<\/p><ul><li>Dropped by Lycanthrope Hunters.<\/li><li>Dropped by Sage's Prentices.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Pike_(Dark_Souls_III)"},{"id":"plank-shield","kind":"weapon","name":"Plank Shield","page":"Plank Shield (Dark Souls III)","img":"assets/img/Plank_Shield__Dark_Souls_III.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":53,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":0,"int":0,"fth":0},"scale":{"str":"E","dex":"-","int":"-","fth":"-"},"defs":{"phys":41,"mag":24,"fire":27,"ltn":23,"dark":25},"stability":34,"weight":1,"durability":40,"skill":"Shield Bash","dmg_type":"Strike","cast":null,"fp":"12(-/-)","buy":null,"desc":"Makeshift shield cobbled together from wooden planks.\nProvides minimal protection, and at the cost of moderate humiliation.\nSkill: Shield Bash\nWithout lowering your guard, strike the enemy with the shield to knock them back or stagger them. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Starting equipment for the Deprived class.<\/li><li>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>. Taking the right-side path from the burning tree with the praying Evangelist and Peasant Hollows, break some crates to the right before entering the stable area, to reveal a hidden path. Traverse the rooftops on the left, killing the Thralls along the way, to find it on a corpse before the Cage Madman.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Plank_Shield_(Dark_Souls_III)"},{"id":"pontiff-knight-curved-sword","kind":"weapon","name":"Pontiff Knight Curved Sword","page":"Pontiff Knight Curved Sword","img":"assets/img/Pontiff_Knight_Curved_Sword.webp","wtype":"Curved Sword","group":"melee","paired":false,"atk":{"phys":123,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":18,"int":10,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":3.5,"durability":90,"skill":"Frost Blade","dmg_type":"Slash","cast":null,"fp":"8(-/14)","buy":6000,"desc":"Curved sword wielded by the Pontiff’s knights, frigid spirits that linger in Irithyll.\nThe large blade appears to be eaten away by insects, making it lightweight but also brittle.\nSkill: Frost Blade\nExecute large spinning motion to imbue blade with frost, and follow through with a strong attack that slashes with a giant blade made of frost.","boss_weapon":false,"avail":"<ul><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 6,000 souls once he returns from his pillaging journey to the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> once she is given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>.<\/li><\/ul><\/li><li>Dropped by Pontiff Knights in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Pontiff_Knight_Curved_Sword"},{"id":"pontiff-knight-great-scythe","kind":"weapon","name":"Pontiff Knight Great Scythe","page":"Pontiff Knight Great Scythe","img":"assets/img/Pontiff_Knight_Great_Scythe.webp","wtype":"Reaper","group":"melee","paired":false,"atk":{"phys":100,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":14,"dex":19,"int":0,"fth":12},"scale":{"str":"E","dex":"A","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":7.5,"durability":55,"skill":"Frost","dmg_type":"Slash","cast":null,"fp":"15(-/-)","buy":null,"desc":"Great scythe wielded by the Pontiff's knights, frigid spirits that linger in Irithyll.\nThe large blade appears to be eaten away by insects, making it lightweight but also brittle.\nSkill: Frost\nCreate a bone-chilling frost with each swing of the greatscythe that causes a temporary frost effect.","boss_weapon":false,"avail":"<p>Dropped by the great scythe-wielding Pontiff Knight before <a data-e=\"pontiff-sulyvahn\">Pontiff Sulyvahn<\/a> in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/p>","notes":"<p>The Faith requirement does not affect its attack rating. However, casting the weapon art without the required Faith results in failure and does not consume FP, and attacks will consume more stamina. <br><br><\/p>","url":"https://darksouls.fandom.com/wiki/Pontiff_Knight_Great_Scythe"},{"id":"pontiff-knight-shield","kind":"weapon","name":"Pontiff Knight Shield","page":"Pontiff Knight Shield","img":"assets/img/Pontiff_Knight_Shield.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":63,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":12,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":73,"mag":79,"fire":69,"ltn":69,"dark":72},"stability":42,"weight":3.5,"durability":65,"skill":"Weapon Skill","dmg_type":"Strike","cast":null,"fp":null,"buy":3000,"desc":"Shield of the Pontiff's knights, frigid spirits that linger in Irithyll.\nThis blue-gray shield, shrouded in a thinly cold air, is light and brittle.\nSkill: Weapon Skill\nEquipping this shield in the left hand allows one to perform the skill of the right hand weapon.","boss_weapon":false,"avail":"<ul><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 3,000 souls once he returns from his pillaging journey to the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> once she is given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>.<\/li><\/ul><\/li><li>Dropped by Pontiff Knights who wield them in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Pontiff_Knight_Shield"},{"id":"porcine-shield","kind":"weapon","name":"Porcine Shield","page":"Porcine Shield (Dark Souls III)","img":"assets/img/Porcine_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":85,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":74,"mag":43,"fire":38,"ltn":27,"dark":36},"stability":48,"weight":4.5,"durability":70,"skill":"Shield Bash","dmg_type":"Strike","cast":null,"fp":"14(-/-)","buy":null,"desc":"Shield base on a pig's head, depicted with unsettling authenticity.\nShields such as these were made to shame weak-willed knights, and those who carried these shields were subject to merciless ridicule. No one will defend a craven who abases himself.\nSkill: Shield Bash\nWithout lowering your guard, give the enemy a good shove with the shameful pig's snout. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Obtained by trading an <a data-e=\"undead-bone-shard\">Undead Bone Shard<\/a> with Pickle Pee (only once per playthrough).<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Porcine_Shield_(Dark_Souls_III)"},{"id":"preachers-right-arm","kind":"weapon","name":"Preacher's Right Arm","page":"Preacher's Right Arm","img":"assets/img/Preacher_s_Right_Arm.webp","wtype":"Staff","group":"catalyst","paired":false,"atk":{"phys":109,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":0,"int":14,"fth":0},"scale":{"str":"E","dex":"-","int":"A","fth":"-"},"defs":{"phys":25,"mag":20,"fire":10,"ltn":10,"dark":15},"stability":10,"weight":2,"durability":50,"skill":"Feasting Branch","dmg_type":"Strike/Thrust","cast":100,"fp":"5(-/-)","buy":null,"desc":"The dessicated right hand of a white-faced locust that rose from the abyssal swamp, that happens to perform as a catalyst for sorcery.\nThe white-faced locusts were meant to beckon men to the dark with sermons, but most of them are unable to think past their own stomachs, the unruly mob!\nSkill: Feasting Branch\nUse souls to weave a sharp branch to fillet prey. Can be used repeatedly.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"the-ringed-city\">Ringed City<\/a>. From the <a data-e=\"the-ringed-city\">Ringed City Streets<\/a> bonfire, head into the swamp, turn right, and head straight toward the big building seen in the distance. Past a Judicator Giant and surrounded by several small White-faced Locusts, is the tip of a sunken tower, where a corpse sitting on it holds the staff.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Preacher's_Right_Arm"},{"id":"priests-chime","kind":"weapon","name":"Priest's Chime","page":"Priest's Chime (Dark Souls III)","img":"assets/img/Priest_s_Chime__Dark_Souls_III.webp","wtype":"Sacred Chime","group":"catalyst","paired":false,"atk":{"phys":52,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":3,"dex":0,"int":0,"fth":10},"scale":{"str":"E","dex":"-","int":"-","fth":"B"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":15,"dark":15},"stability":10,"weight":0.5,"durability":45,"skill":"Gentle Prayer","dmg_type":"Strike","cast":108,"fp":"13(-/-)","buy":4000,"desc":"Sacred chime for casting miracles of the Gods, of the type given to Lothric priests.\nTo cast a miracle, the caster learns a tale of the Gods, and says a prayer to be blessed by its revelations. The faith of the supplicant affects the strength of the miracle.\nSkill: Gentle Prayer\nRecovers HP for a period of time, albeit extremely slowly. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat<\/a> for 4,000 souls once he has returned from his scavenge expedition in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<\/p>","notes":"<ul><li>Can be traded with Pickle Pee in exchange for the <a data-e=\"hello-carving\">Help me! Carving<\/a>.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Priest's_Chime_(Dark_Souls_III)"},{"id":"profaned-greatsword","kind":"weapon","name":"Profaned Greatsword","page":"Profaned Greatsword","img":"assets/img/Profaned_Greatsword.webp","wtype":"Ultra Greatsword","group":"melee","paired":false,"atk":{"phys":161,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":22,"dex":10,"int":0,"fth":0},"scale":{"str":"C","dex":"D","int":"-","fth":"-"},"defs":{"phys":55,"mag":45,"fire":40,"ltn":40,"dark":45},"stability":45,"weight":13.5,"durability":100,"skill":"Profaned Flame","dmg_type":"Standard/Thrust","cast":null,"fp":"10(-/17)","buy":3000,"desc":"A ceremonial sword, held in Pontiff Sulyvahn's right hand, representing the Profaned Flame.\nLong ago, when Sulyvahn was yet a young sorcerer, he discovered the Profaned Capital and an unfading flame below a distant tundra of Irithyll, and a burning ambition took root within him.\nSkill: Profaned Flame\nTemporarily summon the Profaned Flame. Lunge forward and use strong attack to enshroud blade in flame.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-pontiff-sulyvahn\">Soul of Pontiff Sulyvahn<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> for 3,000 souls.<\/p>","notes":"","from_soul":[{"soul":"soul-of-pontiff-sulyvahn","cost":"3,000 souls"}],"url":"https://darksouls.fandom.com/wiki/Profaned_Greatsword"},{"id":"pyromancers-parting-flame","kind":"weapon","name":"Pyromancer's Parting Flame","page":"Pyromancer's Parting Flame","img":"assets/img/Pyromancer_s_Parting_Flame.webp","wtype":"Pyromancy Flame","group":"catalyst","paired":false,"atk":{"phys":0,"mag":0,"fire":110,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":15,"dex":0,"int":13,"fth":13},"scale":{"str":"-","dex":"-","int":"D","fth":"D"},"defs":{"phys":null,"mag":null,"fire":null,"ltn":null,"dark":null},"stability":null,"weight":0,"durability":65,"skill":"Parting Flame","dmg_type":"Strike","cast":114,"fp":"25(-/-)","buy":null,"desc":"The pyromancy flame of Livid Pyromancer Dunnel that attracts the echoes of the death.\nWhen Dunnel lost his hideous spouse, he gave his own pyromancy flame as an offering, which transformed into a parting flame. Not long after, Dunnel became a mad spirit, cursed to wander the lands.\nSkill: Parting Flame\nRelease store of death echoes to gain a modest dose of Estus.","boss_weapon":false,"avail":"<p>Found on a corpse in the <a data-e=\"painted-world-of-ariandel\">Painted World of Ariandel<\/a>, in the tower where Livid Pyromancer Dunnel invades (Crossbreed Priscilla's boss arena). The path to the tower is hidden behind an illusory wall in the lower level of Ariandel Chapel basement.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Pyromancer's_Parting_Flame"},{"id":"pyromancy-flame","kind":"weapon","name":"Pyromancy Flame","page":"Pyromancy Flame (Dark Souls III)","img":"assets/img/Pyromancy_Flame__Dark_Souls_III.webp","wtype":"Pyromancy Flame","group":"catalyst","paired":false,"atk":{"phys":0,"mag":0,"fire":100,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":0,"dex":0,"int":0,"fth":0},"scale":{"str":"-","dex":"-","int":"C","fth":"C"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":0,"durability":50,"skill":"Combustion","dmg_type":"Strike","cast":111,"fp":"12(-/-)","buy":null,"desc":"Flame catalyst used by pyromancers.\nEquip a pyromancy flame to utilize pyromancy. Pyromancies must be attuned at a bonfire to use.\nSkill: Combustion\nCreates a powerful flame in the wielder's hand. One of the most basic pyromancies, and for this very reason, the flame create is fierce. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Starting equipment of the Pyromancer class.<\/li><li>Given by <a data-e=\"cornyx-of-the-great-swamp\">Cornyx of the Great Swamp<\/a> once he relocates to <a data-e=\"firelink-shrine\">Firelink Shrine<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Pyromancy_Flame_(Dark_Souls_III)"},{"id":"quakestone-hammer","kind":"weapon","name":"Quakestone Hammer","page":"Quakestone Hammer","img":"assets/img/Quakestone_Hammer.webp","wtype":"Great Hammer","group":"melee","paired":false,"atk":{"phys":170,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":40,"dex":0,"int":0,"fth":0},"scale":{"str":"C","dex":"-","int":"-","fth":"-"},"defs":{"phys":55,"mag":40,"fire":35,"ltn":35,"dark":40},"stability":40,"weight":15,"durability":150,"skill":"Quake","dmg_type":"Strike","cast":null,"fp":"12(-/10)","buy":null,"desc":"A Stonehammer wielded by the Millwood Knights, with a head of naturally-formed stone.\nThe Knights of Millwood would fight hand-in-hand with the earth itself, and this weapon, among the oldest in Millwood, is symbolic of that relationship.\nSkill: Quake\nBurrow hammer head into the ground with a great slam, and use strong attack to upheave earth, creating a shockwave that rumbles like a mighty warcry.","boss_weapon":false,"avail":"<p>In the Snowy Mountain Pass area, before the final stretch leading to the basement of Ariandel Chapel. There is a fork that leads to the left, and eventually to a Millwood Knight wielding a <a data-e=\"millwood-greatbow\">Millwood Greatbow<\/a>. The Quakestone Hammer is on a corpse behind him.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Quakestone_Hammer"},{"id":"rapier","kind":"weapon","name":"Rapier","page":"Rapier (Dark Souls III)","img":"assets/img/Rapier__Dark_Souls_III.webp","wtype":"Thrusting Sword","group":"melee","paired":false,"atk":{"phys":95,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":7,"dex":12,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":35,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":2,"durability":60,"skill":"Stance","dmg_type":"Thrust","cast":null,"fp":"-(15/15)","buy":null,"desc":"A lightweight thrusting sword used in noble duels employing refined techniques.\nThe primary attack of a thrusting sword is a series of stabs that render foes vulnerable for a devastating final thrust. Can also attack with shield up.\nSkill: Stance\nFrom stance, use normal attack to back step and execute a surprise attack, or strong attack for consecutive thrusting.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a>, on a corpse lying to the left after exiting the small courtyard with a fountain patrolled by a Winged Knight.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Rapier_(Dark_Souls_III)"},{"id":"red-hilted-halberd","kind":"weapon","name":"Red Hilted Halberd","page":"Red Hilted Halberd","img":"assets/img/Red_Hilted_Halberd.webp","wtype":"Halberd","group":"melee","paired":false,"atk":{"phys":130,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":14,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":8,"durability":80,"skill":"Perseverance","dmg_type":"Standard/Thrust","cast":null,"fp":"11(-/-)","buy":null,"desc":"Long-hilted weapon mixing spear and axe. The red-hilted halberd is associated with clerics.\nCan be thrust like a spear or swept sideways like an axe, making it a versatile weapon effective against multiple foes.\nSkill: Perseverance\nAssume an unfaltering stance of prayer to temporarily boost poise. Damage reduced while activated.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>'s sewers. The <a data-e=\"grave-key\">Grave Key<\/a> is required to unlock the gate in the sewage system that gives access to this area. It is found at the center of the room where the player is attacked by Skeletons for the first time.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Red_Hilted_Halberd"},{"id":"red-and-white-shield","kind":"weapon","name":"Red and White Shield","page":"Red and White Round Shield (Dark Souls III)","img":"assets/img/Red_and_White_Round_Shield__Dark_Souls_III.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":69,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":0,"int":0,"fth":0},"scale":{"str":"E","dex":"-","int":"-","fth":"-"},"defs":{"phys":52,"mag":58,"fire":46,"ltn":36,"dark":32},"stability":39,"weight":1.5,"durability":55,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Standard round wooden shield. It features a striking red and white design.\nWooden shields are light, manageable, and offer relatively high magic absorption.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>. After using the <a data-e=\"grave-key\">Grave Key<\/a> to gain access to the small catacombs area guarded by the Giant Hound Rat, navigate the tunnels and exit out into the ravine, heading towards the room containing the ladder that leads to <a data-e=\"irina-of-carim\">Irina of Carim<\/a>. Before entering, look up and use a projectile weapon like a bow to shoot down the lootable corpse. A <a data-e=\"blessed-gem\">Blessed<\/a> infused Red and White Round Shield that has been upgraded to +1 can be obtained.<\/p><p>The area can also be accessed by casting <a data-e=\"spook\">Spook<\/a> from the foot of the bridge spanning the chasm and falling down into the pit, without having to go through the catacombs. The <a data-e=\"silvercat-ring\">Silvercat Ring<\/a> will also work to prevent fall damage.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Red_and_White_Round_Shield_(Dark_Souls_III)"},{"id":"reinforced-club","kind":"weapon","name":"Reinforced Club","page":"Reinforced Club (Dark Souls III)","img":"assets/img/Reinforced_Club__Dark_Souls_III.webp","wtype":"Hammer","group":"melee","paired":false,"atk":{"phys":110,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":12,"dex":0,"int":0,"fth":0},"scale":{"str":"C","dex":"-","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":30,"ltn":30,"dark":30},"stability":30,"weight":4,"durability":45,"skill":"Warcry","dmg_type":"Strike","cast":null,"fp":"20(-/-)","buy":null,"desc":"A club made more deadly by the attachment of numerous nails to its heads.\nThe nails allow this strike weapon to be lacerating, but the damage caused by their insertion has reduced its durability, making the weapon fragile.\nSkill: Warcry\nLet out a spirited war cry that temporarily boosts attack, and enables a special consecutive strong attack","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, on one of the corpses lying on the graveyard beyond the Dilapidated Bridge, where the <a data-e=\"giant-archer-of-the-undead-settlement\">Giant Archer<\/a>'s arrows rain down.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Reinforced_Club_(Dark_Souls_III)"},{"id":"repeating-crossbow","kind":"weapon","name":"Repeating Crossbow","page":"Repeating Crossbow","img":"assets/img/Repeating_Crossbow.webp","wtype":"Crossbow","group":"ranged","paired":false,"atk":{"phys":83,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":16,"dex":20,"int":null,"fth":null},"scale":{"str":"-","dex":"-","int":"-","fth":"-"},"defs":{"phys":null,"mag":null,"fire":null,"ltn":null,"dark":null},"stability":null,"weight":7.5,"durability":20,"skill":"Repeat Fire","dmg_type":"-","cast":0,"fp":"-(13/13)","buy":5000,"desc":"This crossbow, customized for repeat-firing to face mobs alone, was wielded by Slave Knight Gael.\nUsed in the battles of an endless journey, this crossbow is covered with twists and dinks, rusted with blood, and made extremely brittle from overuse.\nSkill: Repeat Fire\nAssume stance to activate repeat firing mechanism, and repeat fire with normal and strong attacks.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-slave-knight-gael\">Soul of Slave Knight Gael<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> for 5,000 souls.<\/p>","notes":"<ul><li>Does not need a full ten bolts to use Repeat Fire. As long as at least one bolt is in the player's possession, it can be used.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Repeating_Crossbow"},{"id":"ricards-rapier","kind":"weapon","name":"Ricard's Rapier","page":"Ricard's Rapier (Dark Souls III)","img":"assets/img/Ricard_s_Rapier__Dark_Souls_III.webp","wtype":"Thrusting Sword","group":"melee","paired":false,"atk":{"phys":97,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":20,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":35,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":2.5,"durability":70,"skill":"Ricard's Lunge and Press","dmg_type":"Thrust","cast":null,"fp":"12(-/8)","buy":null,"desc":"A strikingly decorative rapier of an Undead prince spoken of in ancient stories.\nAlthough many of the tales surrounding the prince are questionable, this thrusting weapon suggests that the stories of his graceful technique were in fact true.\nSkill: Ricard's Lunge and Press\nAssume a quick stance, lunge forward, and execute a stunning chain attack. Sustain offensive with strong attack.","boss_weapon":false,"avail":"<p>Dropped by the Rapier Champion the first time he is summoned and defeated by the player in <a data-e=\"archdragon-peak\">Archdragon Peak<\/a>, before reaching the Great Belfry.<\/p>","notes":"<ul><li>Can be buffed and infused.<\/li><li>This can benefit from the <a data-e=\"sharp-gem\">Sharp Gem<\/a> infusion as this is a Dexterity-based weapon.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Ricard's_Rapier_(Dark_Souls_III)"},{"id":"ringed-knight-paired-greatswords","kind":"weapon","name":"Ringed Knight Paired Greatswords","page":"Ringed Knight Paired Greatswords","img":"assets/img/Ringed_Knight_Paired_Greatswords.webp","wtype":"Ultra Greatsword","group":"melee","paired":true,"atk":{"phys":185,"mag":0,"fire":11,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":40,"dex":15,"int":null,"fth":null},"scale":{"str":"C","dex":"E","int":"E","fth":"E"},"defs":{"phys":50,"mag":40,"fire":35,"ltn":35,"dark":40},"stability":40,"weight":22.5,"durability":90,"skill":"Ember","dmg_type":"Standard/Thrust","cast":0,"fp":"15(12/12)","buy":null,"desc":"Paired black greatswords wielded by the Ringed Knights.\nThe arms of early men were forged in the Abyss, and betray a smidgen of life. For this the gods cast a seal of fire upon such weapons, and those who possessed them.\nSkill: Ember\nCross the twin timeworn greatswords to reignite a short-lived flame. A lightning-quick upward heave slices the very air, and transitions into normal or strong attacks.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"the-ringed-city\">The Ringed City<\/a>. Guaranteed drop from the paired greatswords-wielding Ringed Knight in front of the Church of Filianore when killing him for the first time.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Ringed_Knight_Paired_Greatswords"},{"id":"ringed-knight-spear","kind":"weapon","name":"Ringed Knight Spear","page":"Ringed Knight Spear","img":"assets/img/Ringed_Knight_Spear.webp","wtype":"Pike","group":"melee","paired":false,"atk":{"phys":126,"mag":0,"fire":12,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":15,"dex":17,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"E","fth":"E"},"defs":{"phys":45,"mag":30,"fire":20,"ltn":20,"dark":30},"stability":25,"weight":9,"durability":90,"skill":"Ember","dmg_type":"Thrust","cast":null,"fp":"12(-/8)","buy":null,"desc":"Black spear wielded by the Ringed Knights. The arms of early men were forged in the Abyss, and betray a smidgen of life.\nFor this reason the gods cast a seal of fire upon these spears, and those who possessed them.\nSkill: Ember\nThrust the timeworn spear and watch it restore its ancient brilliance and reignite a short-lived flame, whose dull aftermath will carry on.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"the-ringed-city\">the Ringed City<\/a>. On the great stairway leading from the Inner Wall to the Streets, there is a small side path close to the bottom of the stairs where the second trio of Harald Legion Knights is encountered. After traversing the hallway filled with Curse-inflicting Undead Clerics, the spear can be found on a corpse to the right, guarded by a spear-wielding Ringed Knight.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Ringed_Knight_Spear"},{"id":"ringed-knight-straight-sword","kind":"weapon","name":"Ringed Knight Straight Sword","page":"Ringed Knight Straight Sword","img":"assets/img/Ringed_Knight_Straight_Sword.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":120,"mag":0,"fire":11,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":17,"dex":15,"int":null,"fth":null},"scale":{"str":"C","dex":"D","int":"E","fth":"E"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":4.5,"durability":70,"skill":"Ember","dmg_type":"Standard/Thrust","cast":0,"fp":"-(7/10)","buy":null,"desc":"Straight sword wielded by the Ringed Knights.\nThe arms of early men were forged in the Abyss, and betray a smidgen of life.\nFor this reason the gods cast a seal of fire upon these swords, and those who possessed them.\nSkill: Ember\nStand ready with the timeworn blade as it restores its ancient brilliance and reignites a short-lived flame. From this stance, transition to normal or strong attack.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"the-ringed-city\">The Ringed City<\/a>. From the <a data-e=\"the-ringed-city\">Ringed City Streets<\/a> bonfire, go towards the Judicator Giant, turning right before reaching the sunken church guarded by Ringed Knights. At the top of a hill to the right, there will be a sunken building with a non-aggressive White-faced Locust atop, the sword can be found near him.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Ringed_Knight_Straight_Sword"},{"id":"rose-of-ariandel","kind":"weapon","name":"Rose of Ariandel","page":"Rose of Ariandel","img":"assets/img/Rose_of_Ariandel.webp","wtype":"Whip","group":"melee","paired":false,"atk":{"phys":79,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":34,"psn":0,"fst":0},"req":{"str":10,"dex":12,"int":0,"fth":17},"scale":{"str":"C","dex":"E","int":"-","fth":"B"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":10,"dark":15},"stability":10,"weight":3.5,"durability":50,"skill":"Awakening","dmg_type":"Standard","cast":119,"fp":"25(-/-)","buy":3000,"desc":"A flail used by the bulbous Father of the Painted World to shred his own skin, producing blood to appease the flame.\nBoth a weapon and a miracle catalyst.\nAriandel, being the restorer of the Painted World, knew that it was painted with blood, and only blood could protect the secret.\nSkill: Awakening\nViolently flail oneself to trigger an awakening that temporarily boosts the strength of miracles, just as the good Father used the rose himself.","boss_weapon":true,"avail":"<p>Transpose the <a data-e=\"soul-of-sister-friede\">Soul of Sister Friede<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> for 3,000 souls.<\/p>","notes":"<ul><li>There are tiny, clawed hands on the end of each whip, each one resembling a bird's foot.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Rose_of_Ariandel"},{"id":"rotten-ghru-curved-sword","kind":"weapon","name":"Rotten Ghru Curved Sword","page":"Rotten Ghru Curved Sword","img":"assets/img/Rotten_Ghru_Curved_Sword.webp","wtype":"Curved Sword","group":"melee","paired":false,"atk":{"phys":103,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":36,"fst":0},"req":{"str":10,"dex":13,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":40,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":2,"durability":55,"skill":"Spin Slash","dmg_type":"Slash","cast":null,"fp":"6(-/12)","buy":null,"desc":"A crude, half-rotten curved sword.\nChoice weapon of the blunt-horned Ghrus, descendants of the acolytes of Farron Keep.\nThe rancid blade is drenched in rotten waste, making it acutely poisonous.\nSkill: Spin Slash\nSlice into foes with a large spinning motion, and follow with strong attack for a spinning vertical-slash.","boss_weapon":false,"avail":"<ul><li><a data-e=\"farron-keep\">Farron Keep<\/a><ul><li>Dropped by Ghrus.<\/li><\/ul><\/li><li><a data-e=\"smouldering-lake\">Smouldering Lake<\/a><ul><li>Dropped by Smouldering Ghrus.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Rotten_Ghru_Curved_Sword"},{"id":"rotten-ghru-dagger","kind":"weapon","name":"Rotten Ghru Dagger","page":"Rotten Ghru Dagger","img":"assets/img/Rotten_Ghru_Dagger.webp","wtype":"Dagger","group":"melee","paired":false,"atk":{"phys":64,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":36,"fst":0},"req":{"str":10,"dex":8,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":35,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":2,"durability":45,"skill":"Quickstep","dmg_type":"Slash/Thrust","cast":null,"fp":"5(-/-)","buy":null,"desc":"A crude, half-rotten dagger.\nChoice weapon of the blunt-horned Ghrus, descendants of the acolytes of Farron Keep.\nThe rancid blade is drenched in rotten waste, making it acutely poisonous.\nSkill: Quickstep\nInstantly step behind or around the side of foes. Especially effective when locked on to target.","boss_weapon":false,"avail":"<p>Dropped by dagger-wielding Ghrus in the <a data-e=\"farron-keep\">Farron Keep<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Rotten_Ghru_Dagger"},{"id":"rotten-ghru-spear","kind":"weapon","name":"Rotten Ghru Spear","page":"Rotten Ghru Spear","img":"assets/img/Rotten_Ghru_Spear.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":104,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":36,"fst":0},"req":{"str":10,"dex":12,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":5.5,"durability":50,"skill":"Charge","dmg_type":"Thrust","cast":null,"fp":"13(-/9)","buy":null,"desc":"A crude, half-rotten curved spear.\nChoice weapon of the blunt-horned Ghrus, descendants of the acolytes of Farron Keep.\nThe rancid tip is drenched in rotten waste, making it acutely poisonous.\nSkill: Charge\nHold spear at waist and charge at foe. Use strong attack while charging to extend the length of the charge.","boss_weapon":false,"avail":"<ul><li><a data-e=\"farron-keep\">Farron Keep<\/a><ul><li>Dropped by spear-wielding Ghrus.<\/li><\/ul><\/li><li><a data-e=\"smouldering-lake\">Smouldering Lake<\/a><ul><li>Dropped by spear-wielding Smouldering Ghrus.<\/li><\/ul><\/li><\/ul>","notes":"<p>This weapon does well on a low-level quality build when infused with a Refined Gem.<\/p><p>This weapon shares the same moveset as the spear, meaning it does well when paired with the Leo Ring.<\/p>","url":"https://darksouls.fandom.com/wiki/Rotten_Ghru_Spear"},{"id":"round-shield","kind":"weapon","name":"Round Shield","page":"Round Shield","img":"assets/img/Round_Shield.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":79,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":86,"mag":68,"fire":50,"ltn":45,"dark":41},"stability":51,"weight":3.5,"durability":80,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":1000,"desc":"Standard round wooden shield.\nWooden shields are light, manageable, and offer relatively high magic absorption.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Starting equipment of the Warrior class.<\/li><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 1,000 souls.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Round_Shield"},{"id":"sacred-bloom-shield","kind":"weapon","name":"Sacred Bloom Shield","page":"Sacred Bloom Shield","img":"assets/img/Sacred_Bloom_Shield.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":82,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":54,"mag":81,"fire":49,"ltn":44,"dark":47},"stability":38,"weight":1.5,"durability":85,"skill":"Spell Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"A treasured antique of the Way of White, known to some as the Sorcerer's Bane.\nThe large blossom design that graces the shield is said to be a sacred flame, and the shield is blessed with high magic protection.\nSkill: Spell Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand. Also deflects spells.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"lothric-castle\">Lothric Castle<\/a>, on a ledge near the <a data-e=\"winged-knight-set\">Winged Knight Set<\/a>. The area lies behind an illusory wall located behind the <a data-e=\"winged-knight-twinaxess\">twinaxe<\/a>-wielding Winged Knight that awaits up the ladder of a small tower shortly after the initial <a data-e=\"lothric-castle\">Lothric Castle<\/a> bonfire.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Sacred_Bloom_Shield"},{"id":"sacred-chime-of-filianore","kind":"weapon","name":"Sacred Chime of Filianore","page":"Sacred Chime of Filianore","img":"assets/img/Sacred_Chime_of_Filianore.webp","wtype":"Sacred Chime","group":"catalyst","paired":false,"atk":{"phys":74,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":4,"dex":0,"int":0,"fth":18},"scale":{"str":"E","dex":"-","int":"-","fth":"C"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":10,"dark":15},"stability":10,"weight":0.5,"durability":50,"skill":"Pray for Favor","dmg_type":"Strike","cast":100,"fp":"18(-/-)","buy":null,"desc":"A sacred chime blessed by Princess Filianore, matriarch of the church.\nFilianore's favor knows no boundaries, and this sacred chime expand the range of vicinity-affecting miracles that heal, cure, or provide other enhancements.\nSkill: Pray for Favor\nWorks with chime equipped in left or right hand. Heal HP very slowly for a duration of time. Affect caster and those in vicinity.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"the-ringed-city\">Ringed City<\/a>. Gifted upon accepting <a data-e=\"shira-knight-of-filianore\">Shira, Knight of Filianore<\/a>'s request to slay <a data-e=\"darkeater-midir\">Darkeater Midir<\/a>. This can only be done before interacting with <a data-e=\"filianore\">Filianore<\/a> in the area after Halflight, Spear of the Church.<\/p><p>If missed at this location, it will be dropped by Shira after defeating her at Pygmy's Throne.<\/p>","notes":"<ul><li>This weapon has a Strength requirement, though this essentially has no effect, as there are no starting classes that do not meet it.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Sacred_Chime_of_Filianore"},{"id":"sages-crystal-staff","kind":"weapon","name":"Sage's Crystal Staff","page":"Sage's Crystal Staff","img":"assets/img/Sage_s_Crystal_Staff.webp","wtype":"Staff","group":"catalyst","paired":false,"atk":{"phys":84,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":7,"dex":0,"int":24,"fth":0},"scale":{"str":"E","dex":"-","int":"B","fth":"-"},"defs":{"phys":25,"mag":25,"fire":10,"ltn":10,"dark":15},"stability":10,"weight":2.5,"durability":50,"skill":"Steady Chant","dmg_type":"Strike","cast":112,"fp":"30(-/-)","buy":null,"desc":"Crystal catalyst presented as a gift by the Crystal Sages to their favorite pupil, Kriemhild.\nCrystal spheres devour the will of the user, and this staff increases the potency of sorceries at the cost of increased FP consumption for Skills.\nSkill: Steady Chant\nBoosts the strength of sorceries for a very short period. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Dropped by Daughter of Crystal Kriemhild in the big courtyard at the highest floor of the <a data-e=\"grand-archives\">Grand Archives<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Sage's_Crystal_Staff"},{"id":"saint-bident","kind":"weapon","name":"Saint Bident","page":"Saint Bident","img":"assets/img/Saint_Bident.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":98,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":12,"int":0,"fth":16},"scale":{"str":"D","dex":"E","int":"-","fth":"C"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":8.5,"durability":70,"skill":"Charge","dmg_type":"Thrust","cast":null,"fp":"13(-/9)","buy":null,"desc":"A silver bident decorated by a holy symbol, formerly wielded by Saint Klimt. He discarded this weapon, that draws upon one's faith, on the day that he put his own faith behind him.\nSkill: Charge\nHold spear at waist and charge at foe. Use strong attack while charging to extend the length of the charge.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>, on a corpse near the Giant Slave located on the opposite end from the boss room.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Saint_Bident"},{"id":"saints-talisman","kind":"weapon","name":"Saint's Talisman","page":"Saint's Talisman","img":"assets/img/Saint_s_Talisman.webp","wtype":"Talisman","group":"catalyst","paired":false,"atk":{"phys":53,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":4,"dex":0,"int":0,"fth":16},"scale":{"str":"D","dex":"-","int":"-","fth":"A"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":15,"dark":15},"stability":10,"weight":0.5,"durability":65,"skill":"Unfaltering Prayer","dmg_type":"Strike","cast":107,"fp":"8(-/-)","buy":null,"desc":"Medium for casting miracles of the Gods.\nIvory talismans are given only to women clerics, and faith greatly affects their effectiveness.\nThere is a certain frailty to this talisman, which undermines the steadfastness granted by its Skill.\nSkill: Unfaltering Prayer\nTemporarily increases poise while casting miracles, preventing enemy attacks from interrupting prayer. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>. After obtaining the <a data-e=\"grave-key\">Grave Key<\/a> and navigating the sewers below the settlement, it can be found on a corpse in the room just before the ladder leading up to <a data-e=\"irina-of-carim\">Irina of Carim<\/a>'s cell, guarded by numerous Hound Rats.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Saint's_Talisman"},{"id":"saint-tree-bellvine","kind":"weapon","name":"Saint-tree Bellvine","page":"Saint-tree Bellvine","img":"assets/img/Saint_tree_Bellvine.webp","wtype":"Sacred Chime","group":"catalyst","paired":false,"atk":{"phys":52,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":3,"dex":0,"int":0,"fth":18},"scale":{"str":"E","dex":"-","int":"-","fth":"C"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":15,"dark":15},"stability":10,"weight":0.5,"durability":45,"skill":"Gentle Prayer","dmg_type":"Strike","cast":100,"fp":"13(-/-)","buy":null,"desc":"Sacred chime for casting miracles of the Gods. A bellvine cut from a small saint-tree that has been meticulously tended to.\nSaint-tree bellvines are customary in the far north, and allow for faster casting than ordinary sacred chimes.\nSkill: Gentle Prayer\nRecovers HP for a period of time, albeit extremely slowly. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>. From the <a data-e=\"cathedral-of-the-deep\">Cleansing Chapel<\/a> bonfire, exit the cathedral and drop into the nearby riverbed. The chime can be found in the middle of the open path to the left, guarded by three Corpse Grubs.<\/p>","notes":"<ul><li>Can be traded with Pickle Pee in exchange for the <a data-e=\"hello-carving\">Help me! Carving<\/a> (only once per character).<\/li><\/ul><p><br><br><\/p>","url":"https://darksouls.fandom.com/wiki/Saint-tree_Bellvine"},{"id":"scholars-candlestick","kind":"weapon","name":"Scholar's Candlestick","page":"Scholar's Candlestick","img":"assets/img/Scholar_s_Candlestick.webp","wtype":"Dagger","group":"melee","paired":false,"atk":{"phys":68,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":7,"dex":0,"int":0,"fth":16},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":35,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":15,"weight":1.5,"durability":40,"skill":"Guiding Light","dmg_type":"Slash/Thrust","cast":null,"fp":"5(-/-)","buy":3500,"desc":"A candlestick covered in ivory scales once used by the Scholars of the Great Archives.\nThis served as their guiding light, as well as a tool of self-restrain. Even today, wielders of this weapon benefit from the resulting sorcery-strengthening properties.\nWeapon Skill: Guiding Light\nThe candle provides a temporary source of light which reveals additional guidance.","boss_weapon":false,"avail":"<ul><li><a data-e=\"firelink-shrine\">Firelink Shrine<\/a><ul><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 3,500 souls once he returns from pillaging <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/li><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for the same price once she is given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>, provided that he has at least survived pillaging the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<\/li><\/ul><\/li><li><a data-e=\"grand-archives\">Grand Archives<\/a><ul><li>Dropped by Grand Archives Scholars.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Scholar's_Candlestick"},{"id":"scimitar","kind":"weapon","name":"Scimitar","page":"Scimitar (Dark Souls III)","img":"assets/img/Scimitar__Dark_Souls_III.webp","wtype":"Curved Sword","group":"melee","paired":false,"atk":{"phys":90,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":7,"dex":13,"int":0,"fth":0},"scale":{"str":"E","dex":"B","int":"-","fth":"-"},"defs":{"phys":40,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":2.5,"durability":60,"skill":"Spin Slash","dmg_type":"Slash","cast":null,"fp":"4(-/12)","buy":600,"desc":"Small curved sword that excels in swift movements and consecutive attacks.\nThe scimitar's flesh-rending slash attacks are greatly compromised against armor and tough scale-covered hides.\nSkill: Spin Slash\nSlice into foes with a large spinning motion, and follow with strong attack for a spinning vertical-slash.","boss_weapon":false,"avail":"<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 600 souls.<\/li><li>Dropped by Skeletons who wield them in the <a data-e=\"catacombs-of-carthus\">Catacombs of Carthus<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Scimitar_(Dark_Souls_III)"},{"id":"sellsword-twinblades","kind":"weapon","name":"Sellsword Twinblades","page":"Sellsword Twinblades","img":"assets/img/Sellsword_Twinblades.webp","wtype":"Curved Sword","group":"melee","paired":true,"atk":{"phys":99,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":16,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":40,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":5.5,"durability":55,"skill":"Spin Slash","dmg_type":"Slash","cast":null,"fp":"4(-/12)","buy":null,"desc":"Paired scimitars used by certain sellswords. The scimitars' sharp blades make for effective slashing attacks, but fare poorly against metal armor and tough scale-covered hides.\nWith a scimitar in each hand, the wielder can vary their onslaught with unique left-handed attacks when in the proper stance.\nSkill: Spin Slash\nSlice into foes with a large spinning motion, and continue spinning to transition into a strong attack.","boss_weapon":false,"avail":"<ul><li>Starting equipment for the Mercenary class.<\/li><li>Found behind the Black Knight at the far end of the swamp in <a data-e=\"road-of-sacrifices\">Crucifixion Woods<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Sellsword_Twinblades"},{"id":"shield-of-want","kind":"weapon","name":"Shield of Want","page":"Shield of Want","img":"assets/img/Shield_of_Want.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":104,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":61,"fire":63,"ltn":43,"dark":61},"stability":58,"weight":5.5,"durability":110,"skill":"Weapon Skill","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Shield of an ancient king who was cursed by an all-consuming thirst. In the end, he was no king.\nThe residue of the king's lust still smolders within this shield, increasing the number of souls absorbed when enemies are defeated.\nSkill: Weapon Skill\nEquipping this shield in the left hand allows one to perform the Skill of the right hand weapon.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>, guarded by the Carthus Sand Worm.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Shield_of_Want"},{"id":"short-bow","kind":"weapon","name":"Short Bow","page":"Short Bow (Dark Souls III)","img":"assets/img/Short_Bow__Dark_Souls_III.webp","wtype":"Bow","group":"ranged","paired":false,"atk":{"phys":77,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":7,"dex":12,"int":0,"fth":0},"scale":{"str":"E","dex":"D","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":2,"durability":40,"skill":"Rapid Fire","dmg_type":"None","cast":null,"fp":"-(4/4)","buy":1000,"desc":"Standard small bow. Its size allows for quick shots.\nArrows must be equipped in order to use bows. Up to two kinds of arrow can be equipped at a time, and these can be switched between as necessary.\nSkill: Rapid Fire\nSwiftly nocks arrows with finesse after drawing the bow, allowing for consecutive shots.","boss_weapon":false,"avail":"<ul><li>Starting equipment of the Thief class.<\/li><li><a data-e=\"firelink-shrine\">Firelink Shrine<\/a><ul><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 1,000 souls once he returns from his first scavenge run in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<\/li><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for the same price once she is given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Short_Bow_(Dark_Souls_III)"},{"id":"shortsword","kind":"weapon","name":"Shortsword","page":"Shortsword (Dark Souls III)","img":"assets/img/Shortsword__Dark_Souls_III.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":99,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":10,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":2,"durability":65,"skill":"Stance","dmg_type":"Standard/Thrust","cast":null,"fp":"-(17/20)","buy":600,"desc":"Small straight sword excelling in thrusting attacks.\nThe shortsword is a light and easily wielded straight sword, due to its minimal attribute requirements.\nSkill: Stance\nWhile in stance, use normal attack to break a foe's guard from below, and strong attack to slash upwards with a forward lunge.","boss_weapon":false,"avail":"<p>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 600 souls.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Shortsword_(Dark_Souls_III)"},{"id":"shotel","kind":"weapon","name":"Shotel","page":"Shotel (Dark Souls III)","img":"assets/img/Shotel__Dark_Souls_III.webp","wtype":"Curved Sword","group":"melee","paired":false,"atk":{"phys":104,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":9,"dex":14,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":40,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":2.5,"durability":55,"skill":"Spin Slash","dmg_type":"Slash","cast":null,"fp":"5(-/12)","buy":4000,"desc":"Broadly curved sword known as the favored weapon of the tragic Embraced Knight.\nShaped to sneak around the defenses of shields, this sword requires ample dexterity to wield effectively.\nSkill: Spin Slash\nSlice into foes with a large spinning motion, and follow with strong attack for a spinning vertical-slash.","boss_weapon":false,"avail":"<p>Two are sold by <a data-e=\"unbreakable-patches\">Unbreakable Patches<\/a> for 4,000 souls.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Shotel_(Dark_Souls_III)"},{"id":"silver-eagle-kite-shield","kind":"weapon","name":"Silver Eagle Kite Shield","page":"Silver Eagle Kite Shield (Dark Souls III)","img":"assets/img/Silver_Eagle_Kite_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":88,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":11,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":44,"fire":45,"ltn":33,"dark":43},"stability":45,"weight":5,"durability":60,"skill":"Weapon Skill","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Orthodox metal shield engraved with a crest depicting a silver eagle.\nMedium shields are the most average of shields, providing a practical balance of damage absorption, stability and weight.\nSkill: Weapon Skill\nEquipping this shield in the left hand allows one to perform the Skill of the right hand weapon.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a>. Make way to the big room with several Large Hollow Soldiers and Starved Hounds, near the end of the level. Upon entering, follow the catwalk on the right and the shield can be looted from a chest located in a nearby corner.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Silver_Eagle_Kite_Shield_(Dark_Souls_III)"},{"id":"silver-knight-shield","kind":"weapon","name":"Silver Knight Shield","page":"Silver Knight Shield (Dark Souls III)","img":"assets/img/Silver_Knight_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":98,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":16,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":60,"fire":54,"ltn":48,"dark":52},"stability":55,"weight":6.5,"durability":100,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Heavy shield carried by the Silver Knights who served the old royal family. A flowing canal is chiseled deeply into its face.\nThe Silver Knights stayed behind to protect the humble manor and ruined cathedral. Though their goddess has long since left, her blessing upon her knights' shields remains.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Dropped by Silver Knights.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Silver_Knight_Shield_(Dark_Souls_III)"},{"id":"small-leather-shield","kind":"weapon","name":"Small Leather Shield","page":"Small Leather Shield (Dark Souls III)","img":"assets/img/Small_Leather_Shield__Dark_Souls_III.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":70,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":7,"dex":0,"int":0,"fth":0},"scale":{"str":"E","dex":"-","int":"-","fth":"-"},"defs":{"phys":42,"mag":42,"fire":50,"ltn":38,"dark":35},"stability":35,"weight":2,"durability":55,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"A small, leather-covered round shield.\nIt features a large central protrusion designed for parrying attacks.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li><a data-e=\"undead-settlement\">Undead Settlement<\/a><ul><li>From the <a data-e=\"undead-settlement\">Undead Settlement<\/a> bonfire, enter the first house and immediately turn right. The shield can be looted from one of the hanging corpses.<\/li><\/ul><\/li><li><a data-e=\"archdragon-peak\">Archdragon Peak<\/a><ul><li>Dropped by the <a data-e=\"man-serpent-hatchet\">hatchet<\/a>-wielding Man Serpents that carry them.<\/li><\/ul><\/li><\/ul>","notes":"<ul><li>The parry type is Special (Long).<\/li><li>In Dark Souls 1, this shield originally used the parry type: <a data-e=\"small-leather-shield\">Fast<\/a><\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Small_Leather_Shield_(Dark_Souls_III)"},{"id":"smoughs-great-hammer","kind":"weapon","name":"Smough's Great Hammer","page":"Smough's Great Hammer","img":"assets/img/Smough_s_Great_Hammer.webp","wtype":"Great Hammer","group":"melee","paired":false,"atk":{"phys":205,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":45,"dex":0,"int":0,"fth":0},"scale":{"str":"C","dex":"-","int":"-","fth":"-"},"defs":{"phys":70,"mag":50,"fire":45,"ltn":45,"dark":50},"stability":45,"weight":24,"durability":205,"skill":"Perseverance","dmg_type":"Strike","cast":null,"fp":"12(-/-)","buy":null,"desc":"Twisted great Hammer associated with Smough, the last knight to remain at his post, guarding the ruined cathedral.\nRestore HP while attacking, a carryover from Smough's past as an executioner.\nSkill: Perseverance\nAnchor weapon in earth to temporarily boost poise. Damage reduced while activated.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>, inside the middle chest on the upper gallery floor of the Distant Manor. The area is located shortly after exiting the drainage with several Sewer Centipedes and is guarded by three Silver Knights.<\/p>","notes":"<ul><li>Restores 2 HP with each successful hit.<\/li><li>Restores 4 HP with each successful two-handed strong hit.<\/li><\/ul><p><br><br><\/p>","url":"https://darksouls.fandom.com/wiki/Smough's_Great_Hammer"},{"id":"sniper-crossbow","kind":"weapon","name":"Sniper Crossbow","page":"Sniper Crossbow (Dark Souls III)","img":"assets/img/Sniper_Crossbow__Dark_Souls_III.webp","wtype":"Crossbow","group":"ranged","paired":false,"atk":{"phys":70,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":16,"int":0,"fth":0},"scale":{"str":"-","dex":"-","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":7.5,"durability":55,"skill":"Tackle","dmg_type":"None","cast":null,"fp":"7(-/-)","buy":null,"desc":"Long-range heavy crossbow used by Carim snipers.\nIts lengthy base makes aiming difficult, and accurate usage requires a trained, dexterous hand.\nSkill: Tackle\nLunge into a shoulder tackle, pushing back enemies to create distance.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"lothric-castle\">Lothric Castle<\/a>, on a corpse on a small tower guarded by a Hollow Soldier that throws <a data-e=\"undead-hunter-charm\">Undead Hunter Charms<\/a>, before reaching the Dragon Barracks bonfire. To reach it, the player must drop into the moat before the Lothric Wyverns and follow the path to the right, defeating several Hollow Assassins and a Winged Knight in order to reach it.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Sniper_Crossbow_(Dark_Souls_III)"},{"id":"soldering-iron","kind":"weapon","name":"Soldering Iron","page":"Soldering Iron","img":"assets/img/Soldering_Iron.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":39,"mag":0,"fire":96,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":12,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":5,"durability":25,"skill":"Charge","dmg_type":"Standard","cast":null,"fp":"13(-/9)","buy":null,"desc":"Branding iron used by the jailers prowling Irithyll Dungeon.\nPress its searing tip against foes to inflict fire damage, and temporarily block Estus healing.\nSkill: Charge\nHold iron at waist and charge at foe. Use strong attack while charging to extend the length of the charge.","boss_weapon":false,"avail":"<p>Dropped by Jailers in <a data-e=\"irithyll-dungeon\">Irithyll Dungeon<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Soldering_Iron"},{"id":"sorcerers-staff","kind":"weapon","name":"Sorcerer's Staff","page":"Sorcerer's Staff (Dark Souls III)","img":"assets/img/Sorcerer_s_Staff__Dark_Souls_III.webp","wtype":"Staff","group":"catalyst","paired":false,"atk":{"phys":60,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":6,"dex":0,"int":10,"fth":0},"scale":{"str":"E","dex":"-","int":"B","fth":"-"},"defs":{"phys":25,"mag":20,"fire":10,"ltn":10,"dark":15},"stability":10,"weight":2,"durability":50,"skill":"Steady Chant","dmg_type":"Strike","cast":100,"fp":"7(-/-)","buy":500,"desc":"Staff used to cast sorceries. A common catalyst given to sorcerers of the Vinheim Dragon School.\nEquip a catalyst to use sorceries. Sorceries must be attuned at a bonfire before use.\nSkill: Steady Chant\nBoost the strength of sorceries for a very short period. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Starting equipment of the Sorcerer and Assassin classes.<\/li><li><a data-e=\"firelink-shrine\">Firelink Shrine<\/a><ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 500 souls.<\/li><\/ul><\/li><li><a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a><ul><li>Dropped by Sage's Devouts.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Sorcerer's_Staff_(Dark_Souls_III)"},{"id":"spear","kind":"weapon","name":"Spear","page":"Spear (Dark Souls III)","img":"assets/img/Spear__Dark_Souls_III.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":104,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":11,"dex":10,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":4.5,"durability":65,"skill":"Shield Splitter","dmg_type":"Thrust","cast":null,"fp":"16(-/-)","buy":600,"desc":"Common short spear that allows attacking with shield up.\nSpear attacks are centered on thrusting, but can inflict high damage when timed with the end of an enemy's swing.\nSkill: Shield Splitter\nTake a large step forward and make a single focused thrust to puncture enemy shields and inflict damage.","boss_weapon":false,"avail":"<ul><li>Starting equipment of the Herald class.<\/li><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 600 souls.<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 600 souls, once she has been given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>.<\/li><\/ul><\/li><li>Dropped by spear-wielding Hollow Soldiers.<\/li><li>Dropped by spear-wielding Devouts of the Deep.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Spear_(Dark_Souls_III)"},{"id":"spider-shield","kind":"weapon","name":"Spider Shield","page":"Spider Shield (Dark Souls III)","img":"assets/img/Spider_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":88,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":80,"mag":52,"fire":47,"ltn":29,"dark":46},"stability":56,"weight":3.5,"durability":75,"skill":"Weapon Skill","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"A shield bearing a large etching of a spider.\nShields of this style are commonly used by savage mountain bandits, and offer high resistance to poison.\nSkill: Weapon Skill\nEquipping this shield in the left hand allows one to perform the Skill of the right hand weapon.","boss_weapon":false,"avail":"<p>Dropped by the Brigand near the first bonfire in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>.<\/p>","notes":"<ul><li>Increases Poison resistance by 50 when wielded.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Spider_Shield_(Dark_Souls_III)"},{"id":"spiked-mace","kind":"weapon","name":"Spiked Mace","page":"Spiked Mace","img":"assets/img/Spiked_Mace.webp","wtype":"Great Hammer","group":"melee","paired":false,"atk":{"phys":149,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":43,"psn":0,"fst":0},"req":{"str":21,"dex":13,"int":0,"fth":0},"scale":{"str":"C","dex":"-","int":"-","fth":"-"},"defs":{"phys":55,"mag":40,"fire":35,"ltn":35,"dark":40},"stability":40,"weight":16,"durability":140,"skill":"Spin Bash","dmg_type":"Strike","cast":null,"fp":"13(-/10)","buy":null,"desc":"Choice weapon of the evangelists of the Cathedral of the Deep, mentors of the dwellers of the Undead Settlement.\nIts long, sharp spikes cause great pain and bleeding.\nSkill: Spin Bash\nBash foes with a large spinning motion, utilizing momentum to transition into a overhand strong attack smash.","boss_weapon":false,"avail":"<p>Dropped by Evangelists in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a> and <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Spiked_Mace"},{"id":"spiked-shield","kind":"weapon","name":"Spiked Shield","page":"Spiked Shield (Dark Souls III)","img":"assets/img/Spiked_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":86,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":12,"dex":12,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":91,"mag":49,"fire":51,"ltn":32,"dark":56},"stability":48,"weight":3.5,"durability":75,"skill":"Shield Strike","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Shield of Longfinger Kirk, the notorious Knight of Thorns. The surface bristles with thorns.\nIts vicious design makes it an effective weapon, and its thorns can inflict heavy bleeding on those unfortunate enough to be struck.\nSkill: Shield Strike\nUse shield to attack enemies. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Dropped by Longfinger Kirk in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>.<\/p>","notes":"<ul><li>Unlike shields with the Shield Bash skill, shield strike does not provide any blocking frames, making this shield less useful for trading blows.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Spiked_Shield_(Dark_Souls_III)"},{"id":"spirit-tree-crest-shield","kind":"weapon","name":"Spirit Tree Crest Shield","page":"Spirit Tree Crest Shield","img":"assets/img/Spirit_Tree_Crest_Shield.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":95,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":67,"fire":56,"ltn":83,"dark":53},"stability":49,"weight":5,"durability":90,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"A knight's shield engraved with a crest depicting a spirit tree.\nOne of the enchanted blue shields. The Spirit Tree Crest Shield greatly reduces lightning damage.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"lothric-castle\">Lothric Castle<\/a>, in one of the chests in the room where the Boreal Outrider Knight dwells.<\/p>","notes":"<ul><li>The spirit tree crest is quite similar to the crest of the Ethereal Oak on the cape of the Millwood Knight Armor set.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Spirit_Tree_Crest_Shield"},{"id":"splitleaf-greatsword","kind":"weapon","name":"Splitleaf Greatsword","page":"Splitleaf Greatsword","img":"assets/img/Splitleaf_Greatsword.webp","wtype":"Halberd","group":"melee","paired":false,"atk":{"phys":132,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":null,"fst":0},"req":{"str":26,"dex":16,"int":null,"fth":null},"scale":{"str":"C","dex":"E","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":13.5,"durability":90,"skill":"Wind Wheel","dmg_type":"Standard","cast":0,"fp":"-(17/20)","buy":11000,"desc":"A long-handled greatsword that made its way from a distant land. Crafted entirely with bronze, making it exceedingly heavy.\nSplitleaf refers to the shape of the great blade, and its resemblance to the veins of a leaf.\nSkill: Wind Wheel\nSpin weapon vigorously above head and sweep foes, and transition with normal or strong attack for continued spin attacks, which whip up wind and gain momentum, strengthening subsequent attacks.","boss_weapon":false,"avail":"<ul><li>Sold by the <a data-e=\"stone-humped-hag\">Stone-humped Hag<\/a> for 11,000 souls.<\/li><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for the same price if she is given the <a data-e=\"old-womans-ashes\">Old Woman's Ashes<\/a> and it was not previously purchased from the Stone-humped Hag.<\/li><\/ul>","notes":"<ul><li>This weapon gains S Strength scaling upon max reinforcement and <a data-e=\"heavy-gem\">Heavy<\/a> infusion.<\/li><li><a data-e=\"amnesiac-lapp\">Amnesiac Lapp<\/a> wields this weapon.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Splitleaf_Greatsword"},{"id":"spotted-whip","kind":"weapon","name":"Spotted Whip","page":"Spotted Whip (Dark Souls III)","img":"assets/img/Spotted_Whip__Dark_Souls_III.webp","wtype":"Whip","group":"melee","paired":false,"atk":{"phys":102,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":36,"fst":0},"req":{"str":9,"dex":20,"int":0,"fth":0},"scale":{"str":"-","dex":"D","int":"-","fth":"-"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":10,"dark":15},"stability":10,"weight":2.5,"durability":50,"skill":"Impact","dmg_type":"Slash","cast":null,"fp":"14(-/-)","buy":null,"desc":"Whip mottled with venomous-looking spots.\nFavored by some female pyromancers of the Great Swamp.\nAs its noxious appearance would suggest, damage from this whip poisons its victims, slowly but surely guiding them to their deaths.\nSkill: Impact\nStrike from the left to evade shields and deal a stinging blow that temporarily slows stamina recovery. The shackles of bondage lie deep in the hearts of all humankind.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, on the same cage where <a data-e=\"cornyx-of-the-great-swamp\">Cornyx<\/a> was first found. The whip, along with <a data-e=\"cornyxs-set\">Cornyx's Set<\/a>, will only appear after defeating the <a data-e=\"old-demon-king\">Old Demon King<\/a> with the aid of the Great Swamp Cuculus in the <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Spotted_Whip_(Dark_Souls_III)"},{"id":"stone-greatshield","kind":"weapon","name":"Stone Greatshield","page":"Stone Greatshield (Dark Souls III)","img":"assets/img/Stone_Greatshield__Dark_Souls_III.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":115,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":38,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":75,"fire":71,"ltn":71,"dark":75},"stability":67,"weight":18,"durability":170,"skill":"Shield Bash","dmg_type":"Standard","cast":null,"fp":"16(-/-)","buy":null,"desc":"A mossy stone disc. Though terribly heavy, it can serve as a shield.\nThe disc is a relic of ancient magic, and one can practically feel the power flowing through it.\nSkill: Shield Bash\nWithout lowering your guard, strike the enemy with the shield to knock them back or stagger them. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Dropped by Elder Ghrus in <a data-e=\"farron-keep\">Farron Keep<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Stone_Greatshield_(Dark_Souls_III)"},{"id":"stone-parma","kind":"weapon","name":"Stone Parma","page":"Stone Parma (Dark Souls III)","img":"assets/img/Stone_Parma__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":94,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":17,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":58,"fire":52,"ltn":53,"dark":57},"stability":57,"weight":7,"durability":70,"skill":"Weapon Skill","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"A round, stone shield, once carried by an old knight who turned to stone himself.\nIt has powerful defensive properties for its size, but is extremely heavy.\nSkill: Weapon Skill\nEquipping this shield in the left hand allows one to perform the Skill of the right hand weapon.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"farron-keep\">Farron Keep<\/a>. From the first bonfire, follow the general path on the left. The loot containing the shield is visible on the distance, right under a lone Rotten Slug lying beside a tree.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Stone_Parma_(Dark_Souls_III)"},{"id":"storm-curved-sword","kind":"weapon","name":"Storm Curved Sword","page":"Storm Curved Sword","img":"assets/img/Storm_Curved_Sword.webp","wtype":"Curved Sword","group":"melee","paired":false,"atk":{"phys":110,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":14,"dex":20,"int":null,"fth":null},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":50,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":35,"weight":5,"durability":85,"skill":"Tornado","dmg_type":"Slash","cast":null,"fp":"7(-/15)","buy":5000,"desc":"Curved sword imbued with the strength of the Stormdrake.\nThe Nameless King, ally of the ancient dragons, fought beside the Stormdrake in countless battles. When the great beast fell, the king claimed his soul, as was the custom in the age of the gods.\nSkill: Tornado\nImbue blade with the wrath of storm in a spinning motion, and follow with a strong attack to bear that wrath upon foes.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-the-nameless-king\">Soul of the Nameless King<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a> at a cost of 5,000 souls.<\/p>","notes":"","from_soul":[{"soul":"soul-of-the-nameless-king","cost":"5,000 souls"}],"url":"https://darksouls.fandom.com/wiki/Storm_Curved_Sword"},{"id":"storm-ruler","kind":"weapon","name":"Storm Ruler","page":"Storm Ruler","img":"assets/img/Storm_Ruler.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":154,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":0,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":50,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":35,"weight":8,"durability":10,"skill":"Storm King","dmg_type":"Standard","cast":null,"fp":"-(20/20)","buy":null,"desc":"Greatsword with a broken blade, also known as the Giantslayer for the residual strength of storm that brings giants to their knees.\nYhorm the Giant once held two of these, but gave one to the humans who doubted him, and left the other to a dear friend before facing his fate as a Lord of Cinder.\nSkill: Storm King\nAssume stance to imbue sword with storm. Most effective when facing giants.","boss_weapon":false,"avail":"<ul><li>Found beside <a data-e=\"yhorm-the-giant\">Yhorm the Giant<\/a>'s throne in the <a data-e=\"profaned-capital\">Profaned Capital<\/a>.<\/li><li>Dropped by <a data-e=\"siegward-of-catarina\">Siegward of Catarina<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Storm_Ruler"},{"id":"storytellers-staff","kind":"weapon","name":"Storyteller's Staff","page":"Storyteller's Staff","img":"assets/img/Storyteller_s_Staff.webp","wtype":"Staff","group":"catalyst","paired":false,"atk":{"phys":60,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":6,"dex":0,"int":12,"fth":0},"scale":{"str":"E","dex":"-","int":"B","fth":"-"},"defs":{"phys":25,"mag":25,"fire":10,"ltn":10,"dark":15},"stability":10,"weight":2.5,"durability":45,"skill":"Poison Spores","dmg_type":"Strike","cast":100,"fp":"20(-/-)","buy":null,"desc":"Staff of a heretic storyteller who shares tales of the Painted World to forlorn souls.\nThe storytellers, too, are wretched beings with no place to go. Their bodies, souls, and even their staves are all tainted through and through.\nSkill: Poison Spores\nExpel noxious spores from the formless, parasitical things that inhabit the staff.","boss_weapon":false,"avail":"<p>Dropped by Corvian Storytellers.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Storyteller's_Staff"},{"id":"sunless-talisman","kind":"weapon","name":"Sunless Talisman","page":"Sunless Talisman","img":"assets/img/Sunless_Talisman.webp","wtype":"Talisman","group":"catalyst","paired":false,"atk":{"phys":74,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":4,"dex":0,"int":0,"fth":24},"scale":{"str":"E","dex":"-","int":"C","fth":"B"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":15,"dark":15},"stability":10,"weight":0.5,"durability":50,"skill":"Unfaltering Prayer","dmg_type":"Standard","cast":112,"fp":"8(-/-)","buy":null,"desc":"Talisman given to the knights of the Sunless Realms, who serve the nameless moon.\nScales with intelligence, which is rare for a miracle catalyst, but makes it compatible with Dark. In the Sunless Realms, this fact is related first as an initial warning.\nSkill: Unfaltering Prayer\nTemporarily increases poise while casting miracles, preventing enemy attacks from interrupting prayer. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Dropped by <a data-e=\"sirris-of-the-sunless-realms\">Sirris of the Sunless Realms<\/a>.<\/li><li>Found on Sirris's corpse in the <a data-e=\"cemetery-of-ash\">Cemetery of Ash<\/a> if her questline is fully completed after defeating the Twin Princes. The corpse can be found in front of a grave along the cliffs on the right, in the same spot where the <a data-e=\"sunset-shield\">Sunset Shield<\/a> was found.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Sunless_Talisman"},{"id":"sunlight-shield","kind":"weapon","name":"Sunlight Shield","page":"Sunlight Shield (Dark Souls III)","img":"assets/img/Sunlight_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":82,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":54,"fire":49,"ltn":44,"dark":47},"stability":49,"weight":5.5,"durability":80,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"A large, circular shield made of metal and decorated with a holy symbol depicting the sun.\nThis shield was used by the old Knight of Sunlight, and the illustration is his own. Regardless, it has no particular divine powers.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Obtained by trading a <a data-e=\"mendicants-staff\">Mendicant's Staff<\/a> with the <a data-e=\"nestling\">Nestling<\/a>. The Mendicant's Staff must not be reinforced for the trade to work.<\/p>","notes":"<ul><li>This trade can only be performed once per playthrough.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Sunlight_Shield_(Dark_Souls_III)"},{"id":"sunlight-straight-sword","kind":"weapon","name":"Sunlight Straight Sword","page":"Sunlight Straight Sword (Dark Souls III)","img":"assets/img/Sunlight_Straight_Sword__Dark_Souls_III.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":112,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":12,"int":0,"fth":16},"scale":{"str":"D","dex":"D","int":"-","fth":"C"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":3,"durability":70,"skill":"Oath of Sunlight","dmg_type":"Standard/Thrust","cast":null,"fp":"40(-/-)","buy":null,"desc":"Straight sword imbued with the strength of lightning.\nThis featureless long sword contains the very power of the sun. Perhaps is a relic of one-sided adoration.\nSkill: Oath of Sunlight\nRaise the sword aloft when praising the sun to boost attack and damage absorption for self and allies in vicinity. The warriors of sunlight are co-operators from an ancient age.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"lothric-castle\">Lothric Castle<\/a>, dropped by a Mimic in a room adjacent to the white wyvern.<\/p>","notes":"<ul><li>Prior to Patch 1.13, the Sunlight Straight Sword originally scaled only with Strength and Dexterity.<\/li><li>Although the weapon description claims that it inflicts lightning damage, it actually doesn't have any elemental attack.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Sunlight_Straight_Sword_(Dark_Souls_III)"},{"id":"sunlight-talisman","kind":"weapon","name":"Sunlight Talisman","page":"Sunlight Talisman (Dark Souls III)","img":"assets/img/Sunlight_Talisman__Dark_Souls_III.webp","wtype":"Talisman","group":"catalyst","paired":false,"atk":{"phys":53,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":4,"dex":0,"int":0,"fth":14},"scale":{"str":"D","dex":"-","int":"-","fth":"B"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":15,"dark":15},"stability":10,"weight":0.5,"durability":65,"skill":"Unfaltering Prayer","dmg_type":"Strike","cast":100,"fp":"9(-/-)","buy":null,"desc":"The Knight of Sunlight's personal talisman for casting miracles of the Gods.\nThe talisman bears the Knight's own holy illustration, an emblem of his unwavering faith. Use of the talisman's Skill fills the user with similar steadfastness.\nSkill: Unfaltering Prayer\nTemporarily increases poise while casting miracles, preventing enemy attacks from interrupting prayer. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"farron-keep\">Farron Keep<\/a>, on a medium-sized mound of land in the poisonous swamp, to the left of the ladder that leads to the <a data-e=\"old-wolf-of-farron\">Old Wolf of Farron<\/a> altar.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Sunlight_Talisman_(Dark_Souls_III)"},{"id":"sunset-shield","kind":"weapon","name":"Sunset Shield","page":"Sunset Shield","img":"assets/img/Sunset_Shield.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":82,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":60,"fire":55,"ltn":55,"dark":26},"stability":49,"weight":5,"durability":80,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Shield of the Holy Knights of the Sunless Realms.\nEngraved with a brilliant flame crest that burns brightly within the order's customary sunset colors. This design symbolizes those who both harbor and oppose the power of flame.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"cemetery-of-ash\">Cemetery of Ash<\/a>, on a gravestone located near the cliff on the right side of the area between the <a data-e=\"cemetery-of-ash\">Iudex Gundyr<\/a> bonfire and <a data-e=\"firelink-shrine\">Firelink Shrine<\/a>.<\/p><p>The shield will only appear after defeating <a data-e=\"holy-knight-hodrick\">Holy Knight Hodrick<\/a> together with <a data-e=\"sirris-of-the-sunless-realms\">Sirris of the Sunless Realms<\/a> in the <a data-e=\"undead-settlement\">Pit of Hollows<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Sunset_Shield"},{"id":"tailbone-short-sword","kind":"weapon","name":"Tailbone Short Sword","page":"Tailbone Short Sword","img":"assets/img/Tailbone_Short_Sword.webp","wtype":"Dagger","group":"melee","paired":false,"atk":{"phys":106,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":14,"int":0,"fth":0},"scale":{"str":"E","dex":"E","int":"-","fth":"-"},"defs":{"phys":35,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":20,"weight":2,"durability":50,"skill":"Unleash Dragon","dmg_type":"Slash/Thrust","cast":null,"fp":"25(-/-)","buy":null,"desc":"Twisted dagger cherished by the wretched prisoners of Irithyll Dungeon.\nCrafted from a feeble tailbone, and seen as a sign of the dragons. Their screams are oft heard inside the dungeon, as they naively mutilate their unworthy flesh.\nSkill: Unleash Dragon\nThrust the dagger to unleash the strength of dragons, similar to an ancient dragon weapon, only with its power tragically faded.","boss_weapon":false,"avail":"<p>Dropped by dagger-wielding Wretches in the <a data-e=\"irithyll-dungeon\">Irithyll Dungeon<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Tailbone_Short_Sword"},{"id":"tailbone-spear","kind":"weapon","name":"Tailbone Spear","page":"Tailbone Spear","img":"assets/img/Tailbone_Spear.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":118,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":13,"dex":15,"int":0,"fth":0},"scale":{"str":"E","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":4.5,"durability":60,"skill":"Unleash Dragon","dmg_type":"Thrust","cast":null,"fp":"25(-/-)","buy":null,"desc":"Twisted spear favored by the wretched, failed prisoners of Irithyll Dungeon.\nCrafted from a feeble tailbone, and seen as a sign of the dragons. Their screams are oft heard inside the dungeon, as they naively mutilate their unworthy flesh.\nSkill: Unleash Dragon\nThrust the spear to unleash the strength of dragons, similar to an ancient dragon weapon, only with its power tragically faded.","boss_weapon":false,"avail":"<p>Dropped by Wretches who wield them in <a data-e=\"irithyll-dungeon\">Irithyll Dungeon<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Tailbone_Spear"},{"id":"talisman","kind":"weapon","name":"Talisman","page":"Talisman (Dark Souls III)","img":"assets/img/Talisman__Dark_Souls_III.webp","wtype":"Talisman","group":"catalyst","paired":false,"atk":{"phys":52,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":4,"dex":0,"int":0,"fth":10},"scale":{"str":"E","dex":"-","int":"-","fth":"B"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":15,"dark":15},"stability":10,"weight":0.5,"durability":50,"skill":"Unfaltering Prayer","dmg_type":"Strike","cast":100,"fp":"8(-/-)","buy":500,"desc":"Talisman for casting miracle of the Gods. Once a very common item among the ranks of the old Way of White.\nEquip a talisman or a sacred chime to cast miracles. Miracles must be attuned at a bonfire before use.\nSkill: Unfaltering Prayer\nTemporarily increase poise while casting miracles, preventing enemy attacks from interrupting prayer. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Starting equipment of the Herald class.<\/li><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 500 souls.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Talisman_(Dark_Souls_III)"},{"id":"target-shield","kind":"weapon","name":"Target Shield","page":"Target Shield (Dark Souls III)","img":"assets/img/Target_Shield__Dark_Souls_III.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":69,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":11,"int":0,"fth":0},"scale":{"str":"E","dex":"-","int":"-","fth":"-"},"defs":{"phys":61,"mag":36,"fire":31,"ltn":12,"dark":29},"stability":36,"weight":2,"durability":40,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":2500,"desc":"A small, round metal shield.\nThe four distinctive protrusions are designed to brush attacks aside, making it ideal for parrying.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit. Works while equipped in either hand.","boss_weapon":false,"avail":"<ul><li>Starting equipment for the Assassin class.<\/li><li>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat of the Undead Settlement<\/a> for 2,500 souls once he returns from his first pillaging run in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<ul><li>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for the same price once she is given <a data-e=\"greirats-ashes\">Greirat's Ashes<\/a>.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Target_Shield_(Dark_Souls_III)"},{"id":"thrall-axe","kind":"weapon","name":"Thrall Axe","page":"Thrall Axe","img":"assets/img/Thrall_Axe.webp","wtype":"Axe","group":"melee","paired":false,"atk":{"phys":104,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":8,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":1.5,"durability":55,"skill":"Quickstep","dmg_type":"Standard","cast":null,"fp":"5(-/-)","buy":null,"desc":"Small hand axe used by Lothric slaves.\nA cunning weapon for a cunning lot, this axe is quick and deadly.\nSkill: Quickstep\nInstantly step behind or around the side of foes. Especially effective when locked on to target.","boss_weapon":false,"avail":"<p>Dropped by Thralls in the <a data-e=\"undead-settlement\">Undead Settlement<\/a> and the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a>.<\/p>","notes":"<ul><li>The Quickstep skill will still function as intended even if the player's FP bar is empty, but a portion of the invincibility frames are lost (further testing required whether all invincibility frames are lost).<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Thrall_Axe"},{"id":"torch","kind":"weapon","name":"Torch","page":"Torch (Dark Souls III)","img":"assets/img/Torch__Dark_Souls_III.webp","wtype":"Torch","group":"melee","paired":false,"atk":{"phys":35,"mag":0,"fire":80,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":5,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":30,"mag":20,"fire":15,"ltn":15,"dark":20},"stability":17,"weight":1,"durability":45,"skill":"None","dmg_type":"Strike","cast":null,"fp":null,"buy":300,"desc":"A simple, makeshift torch made from an oily rag wrapped around the end of a stick.\nTorches such as these are the easiest way to illuminate one's surroundings, but their use comes at the cost of occupying a hand that would otherwise be free.\nCan be used as a rudimentary weapon to inflict fire damage. It possesses no Skill, being an ordinary, basic tool.","boss_weapon":false,"avail":"<p>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 300 souls.<\/p>","notes":"<ul><li>In <a data-e=\"blacksmith-andre\">Andre<\/a>'s Reinforce Weapon menu, the Torch is categorized as a shield.<\/li><\/ul><p><br><br><\/p>","url":"https://darksouls.fandom.com/wiki/Torch_(Dark_Souls_III)"},{"id":"twin-dragon-greatshield","kind":"weapon","name":"Twin Dragon Greatshield","page":"Twin Dragon Greatshield (Dark Souls III)","img":"assets/img/Twin_Dragon_Greatshield__Dark_Souls_III.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":106,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":16,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":84,"mag":59,"fire":63,"ltn":66,"dark":59},"stability":63,"weight":7,"durability":105,"skill":"Shield Bash","dmg_type":"Strike","cast":null,"fp":"16(-/-)","buy":null,"desc":"The lightest of all greatshields, made from wood and decorated with a two-headed dragon.\nGreatshields are the largest type of shield, and offer both high stability and damage absorption, making it easy to deflect enemy attacks.\nSkill: Shield Bash\nWithout lowering your guard, strike the enemy with the shield to knock them back or stagger them. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a>, on a corpse near to the <a data-e=\"road-of-sacrifices\">Halfway Fortress<\/a> bonfire.<\/p>","notes":"<ul><li>If the Twin Dragon Greatshield is not retrieved prior to the coming of the Eclipse, the item and the corpse holding it will disappear for the rest of the playthrough.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Twin_Dragon_Greatshield_(Dark_Souls_III)"},{"id":"twin-princes-greatsword","kind":"weapon","name":"Twin Princes' Greatsword","page":"Twin Princes' Greatsword","img":"assets/img/Twin_Princes__Greatsword.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":126,"mag":0,"fire":83,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":22,"dex":14,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"D","fth":"D"},"defs":{"phys":55,"mag":35,"fire":30,"ltn":30,"dark":35},"stability":40,"weight":9.5,"durability":95,"skill":"Sacred Light and Flame","dmg_type":"Standard","cast":null,"fp":"-(22/22)","buy":null,"desc":"Sword forged from the reunion of the inseparable swords born from the souls of Lothric and Lorian, the twin princes.\nTheir union is rooted in a curse, and perpetuated by grief.\nSkill: Sacred Light and Flame\nWhile in stance, use normal attack to cast Sacred Lothric Light, and strong attack to cast Flame of Lorian.","boss_weapon":true,"avail":"<p>Transpose <a data-e=\"lorians-greatsword\">Lorian's Greatsword<\/a> and <a data-e=\"lothrics-holy-sword\">Lothric's Holy Sword<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>. Possessing both weapons in one's inventory, speak to Ludleth of Courland when he is in possession of the <a data-e=\"transposing-kiln\">Transposing Kiln<\/a> to unlock additional dialogue. The two weapons can then be joined to create the Twin Princes' Greatsword, sacrificing both in the process.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Twin_Princes'_Greatsword"},{"id":"uchigatana","kind":"weapon","name":"Uchigatana","page":"Uchigatana (Dark Souls III)","img":"assets/img/Uchigatana__Dark_Souls_III.webp","wtype":"Katana","group":"melee","paired":false,"atk":{"phys":115,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":11,"dex":16,"int":0,"fth":0},"scale":{"str":"E","dex":"C","int":"-","fth":"-"},"defs":{"phys":45,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":30,"weight":5.5,"durability":35,"skill":"Hold","dmg_type":"Slash/Thrust","cast":null,"fp":"-(17/5)","buy":null,"desc":"A unique katana characterized by the fine craftsmanship of an eastern land where it was forged.\nThe finely-sharpened blade cuts flesh like butter and causes bleeding, but breaks easily as a result.\nSkill: Hold\nAssume a holding stance to rapidly execute a lunging slash with normal attack, or a deflecting parry with strong attack.","boss_weapon":false,"avail":"<p>Guaranteed drop from the Sword Master in the <a data-e=\"cemetery-of-ash\">Cemetery of Ash<\/a>. He can be found by taking the left path, just before the main entrance to <a data-e=\"firelink-shrine\">Firelink Shrine<\/a>.<\/p><p>Even though he is found early in the game, he is quite strong and has a fair amount of health. An easy way to kill him is to knock him off a ledge. If that's the case, resting at the nearby bonfire will make his weapon appear at his spawning spot, at the top of the stairs.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Uchigatana_(Dark_Souls_III)"},{"id":"valorheart","kind":"weapon","name":"Valorheart","page":"Valorheart","img":"assets/img/Valorheart.webp","wtype":"Straight Sword","group":"melee","paired":false,"atk":{"phys":120,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":12,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":60,"mag":40,"fire":35,"ltn":30,"dark":35},"stability":50,"weight":5.5,"durability":70,"skill":"Lion Stance","dmg_type":"Standard/Strike/Thrust","cast":null,"fp":"-(17/20)","buy":null,"desc":"Weapon once wielded by the Champion of the Undead Match. A special paired set consisting of a broad sword and a lion shield.\nThe champion fought on, without rest, until he lost his mind. In the end, only his page and a lone wolf stayed at his side.\nSkill: Lion Stance\nWhile in stance, use normal attack to thrust forward with shield up, and strong attack to execute a shield bash with a lion's roar.","boss_weapon":false,"avail":"<p>Obtained after defeating the <a data-e=\"champions-gravetender-and-gravetender-greatwolf\">Champion's Gravetender and Gravetender Greatwolf<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Valorheart"},{"id":"vordts-great-hammer","kind":"weapon","name":"Vordt's Great Hammer","page":"Vordt's Great Hammer","img":"assets/img/Vordt_s_Great_Hammer.webp","wtype":"Great Hammer","group":"melee","paired":false,"atk":{"phys":176,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":110},"req":{"str":30,"dex":0,"int":0,"fth":0},"scale":{"str":"C","dex":"-","int":"-","fth":"-"},"defs":{"phys":55,"mag":45,"fire":35,"ltn":35,"dark":45},"stability":45,"weight":17,"durability":170,"skill":"Perseverance","dmg_type":"Strike","cast":null,"fp":"12(-/-)","buy":null,"desc":"Great Hammer wielded by Vordt, the outrider knight of the Boreal Valley. Weapon is imbued with frost, and causes frostbite.\nFrost accumulated in the body causes frostbite, which saps one's health, lowers absorption, and slows stamina recovery.\nSkill: Perseverance\nAnchor weapon in earth to temporarily boost poise. Damage reduced while activated.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-boreal-valley-vordt\">Soul of Boreal Valley Vordt<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"<ul><li>Vordt's Great Hammer is one of the few available weapons that can inflict the Frost status effect.<\/li><li>At 110 Frost build-up, Vordt's Great Hammer causes the most build-up per swing of any weapon with innate build-up.<\/li><li>At 99 Strength, Vordt's Great Hammer +5 achieves 593 attack damage.<\/li><\/ul>","from_soul":[{"soul":"soul-of-boreal-valley-vordt","cost":null}],"url":"https://darksouls.fandom.com/wiki/Vordt's_Great_Hammer"},{"id":"warden-twinblades","kind":"weapon","name":"Warden Twinblades","page":"Warden Twinblades","img":"assets/img/Warden_Twinblades.webp","wtype":"Curved Sword","group":"melee","paired":true,"atk":{"phys":93,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":10,"dex":18,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":40,"mag":35,"fire":25,"ltn":25,"dark":35},"stability":30,"weight":6.5,"durability":70,"skill":"Spin Slash","dmg_type":"Slash","cast":null,"fp":"7(-/9)","buy":null,"desc":"Paired weapon wielded by the grave wardens of the Cathedral of the Deep.\nThe grave wardens of the cathedral, who put down reincarnating copses, wield weapons that cause profuse bleeding, for the loss of blood and bodily fluids is said to slow reanimation.\nSkill: Spin Slash\nSlice into foes with a large spinning motion, and continue spinning to transition into strong attack.","boss_weapon":false,"avail":"<p>Dropped by Grave Wardens in the <a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a> and the <a data-e=\"untended-graves\">Untended Graves<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Warden_Twinblades"},{"id":"wargod-wooden-shield","kind":"weapon","name":"Wargod Wooden Shield","page":"Wargod Wooden Shield","img":"assets/img/Wargod_Wooden_Shield.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":88,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":84,"mag":47,"fire":69,"ltn":64,"dark":67},"stability":57,"weight":4,"durability":70,"skill":"Weapon Skill","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Wooden shield reinforced with metal. The largest of the wooden medium shields.\nThe bizarre pattern featured on the shield is the mark of a mad god, revered as a god of war in remote regions.\nSkill: Weapon Skill\nEquipping this shield in the left hand allows one to perform the Skill of the right hand weapon.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, on a corpse near the Pit of Hollows bonfire.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Wargod_Wooden_Shield"},{"id":"warpick","kind":"weapon","name":"Warpick","page":"Warpick (Dark Souls III)","img":"assets/img/Warpick__Dark_Souls_III.webp","wtype":"Hammer","group":"melee","paired":false,"atk":{"phys":113,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":10,"int":0,"fth":0},"scale":{"str":"C","dex":"E","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":30,"weight":4.5,"durability":70,"skill":"Galvanize","dmg_type":"Thrust","cast":null,"fp":"9(-/-)","buy":1500,"desc":"A war hammer with a hard pronged head. Was originally a pickaxe, but was refitted for battle.\nThis simple but deadly weapon hits heavily with thrust damage, easily puncturing metal armor.\nSkill: Galvanize\nTemporarily boost stamina recovery speed by sheer force of will, or perhaps as a channeling of the original owner's industrious efforts.","boss_weapon":false,"avail":"<p>Sold by Greirat for 1,500 souls once he returns from his first scavenge expedition in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Warpick_(Dark_Souls_III)"},{"id":"warriors-round-shield","kind":"weapon","name":"Warrior's Round Shield","page":"Warrior's Round Shield (Dark Souls III)","img":"assets/img/Warrior_s_Round_Shield__Dark_Souls_III.webp","wtype":"Small Shield","group":"shield","paired":false,"atk":{"phys":74,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":10,"dex":0,"int":0,"fth":0},"scale":{"str":"E","dex":"-","int":"-","fth":"-"},"defs":{"phys":62,"mag":68,"fire":45,"ltn":46,"dark":36},"stability":41,"weight":1.5,"durability":55,"skill":"Weapon Skill","dmg_type":"Strike","cast":null,"fp":null,"buy":600,"desc":"Standard round wooden shield. It bears a double-bladed axe, the mark of a warrior.\nWooden shields are light, manageable, and offer relatively high magic absorption.\nSkill: Weapon Skill\nEquipping this shield in the left hand allows one to perform the Skill of the right hand weapon.","boss_weapon":false,"avail":"<p>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 600 souls.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Warrior's_Round_Shield_(Dark_Souls_III)"},{"id":"washing-pole","kind":"weapon","name":"Washing Pole","page":"Washing Pole (Dark Souls III)","img":"assets/img/Washing_Pole__Dark_Souls_III.webp","wtype":"Katana","group":"melee","paired":false,"atk":{"phys":121,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":30,"psn":0,"fst":0},"req":{"str":18,"dex":20,"int":0,"fth":0},"scale":{"str":"E","dex":"D","int":"-","fth":"-"},"defs":{"phys":55,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":35,"weight":8.5,"durability":20,"skill":"Hold","dmg_type":"Slash/Thrust","cast":null,"fp":"-(22/8)","buy":7500,"desc":"A stunning, unusually long katana forged in an eastern land.\nThe extreme length of this blade provides immense range, but also renders the blade extremely fragile.\nSkill: Hold\nAssume a holding stance to rapidly execute a lunging slash with normal attack, or a deflecting parry with strong attack.","boss_weapon":false,"avail":"<p>Sold by the <a data-e=\"shrine-handmaid\">Shrine Handmaid<\/a> for 7,500 souls once she has been given the <a data-e=\"easterners-ashes\">Easterner's Ashes<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Washing_Pole_(Dark_Souls_III)"},{"id":"whip","kind":"weapon","name":"Whip","page":"Whip (Dark Souls III)","img":"assets/img/Whip__Dark_Souls_III.webp","wtype":"Whip","group":"melee","paired":false,"atk":{"phys":90,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":6,"dex":14,"int":0,"fth":0},"scale":{"str":"-","dex":"C","int":"-","fth":"-"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":10,"dark":15},"stability":10,"weight":2,"durability":50,"skill":"Impact","dmg_type":"Slash","cast":null,"fp":"14(-/-)","buy":null,"desc":"A leather whip that was never intended for use in combat.\nOf little use against armor and tough scales, but quite formidable against enemies with exposed skin.\nSkill: Impact\nStrike from the left to evade shields and deal a stinging blow that temporarily slows stamina recovery. The shackles of bondage lie deep in the hearts of all humankind.","boss_weapon":false,"avail":"<p>Found in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>, on a corpse located behind a door near to the second bonfire.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Whip_(Dark_Souls_III)"},{"id":"white-birch-bow","kind":"weapon","name":"White Birch Bow","page":"White Birch Bow","img":"assets/img/White_Birch_Bow.webp","wtype":"Bow","group":"ranged","paired":false,"atk":{"phys":82,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":20,"int":0,"fth":0},"scale":{"str":"E","dex":"D","int":"-","fth":"-"},"defs":{"phys":0,"mag":0,"fire":0,"ltn":0,"dark":0},"stability":0,"weight":2.5,"durability":50,"skill":"Unseen Arrow","dmg_type":"None","cast":null,"fp":"-(6/6)","buy":null,"desc":"A short bow crafted with white birch. Endowed with light-manipulating magic.\nThe bow is a relic from an ancient land of sorceries that was swallowed by the Abyss, most known for its folktale of the heroic Abysswalker.\nSkill: Unseen Arrow\nArrows shot by large pulls of the bow are enchanted with a golden spell that turns them nearly invisible.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"the-ringed-city\">The Ringed City<\/a>, in the swamp before the Ringed City Streets bonfire.<\/p><p>From the bonfire, cross the swamp, then move to the left, onto the hill guarded by numerous Hobbled Clerics. The bow can be found on a corpse in the area.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/White_Birch_Bow"},{"id":"white-hair-talisman","kind":"weapon","name":"White Hair Talisman","page":"White Hair Talisman","img":"assets/img/White_Hair_Talisman.webp","wtype":"Talisman","group":"catalyst","paired":false,"atk":{"phys":73,"mag":0,"fire":79,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":4,"dex":0,"int":16,"fth":20},"scale":{"str":"E","dex":"-","int":"D","fth":"D"},"defs":{"phys":25,"mag":15,"fire":15,"ltn":15,"dark":15},"stability":10,"weight":0.5,"durability":45,"skill":"Combustion","dmg_type":"Strike","cast":102,"fp":"11(-/-)","buy":null,"desc":"Talisman made from a lock of white hair.\nThis lock of hair belonged to a deformed member of the chaos witches, mothers of the art of pyromancy. Fashioned into a talisman, it enables the wielder to cast both miracles and pyromancies.\nSkill: Combustion\nCreates a powerful flame in the wielder's hand. One of the most basic pyromancies, and for this reason, the flame created is fierce. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found on a corpse at the back of a lava pit, behind an illusory wall in the <a data-e=\"smouldering-lake\">Smouldering Lake<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/White_Hair_Talisman"},{"id":"winged-knight-halberd","kind":"weapon","name":"Winged Knight Halberd","page":"Winged Knight Halberd","img":"assets/img/Winged_Knight_Halberd.webp","wtype":"Halberd","group":"melee","paired":false,"atk":{"phys":145,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":26,"dex":16,"int":0,"fth":0},"scale":{"str":"D","dex":"E","int":"-","fth":"-"},"defs":{"phys":50,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":25,"weight":14,"durability":145,"skill":"Chain Spin","dmg_type":"Standard","cast":null,"fp":"10(-/12)","buy":null,"desc":"Halberd wielded by the Winged Knights, who swore themselves to the Angels.\nThe thick, heavy, bloodstained blade can only be swung by one with inhuman strength.\nSkill: Chain Spin\nSweep foes in a large spinning motion and use strong attack to continue the motion until stamina is exhausted.","boss_weapon":false,"avail":"<ul><li>Dropped by the Winged Knights who wield them in the <a data-e=\"high-wall-of-lothric\">High Wall of Lothric<\/a> and <a data-e=\"lothric-castle\">Lothric Castle<\/a>.<\/li><li>Dropped by the two Gertrude's Knights who wield them in the <a data-e=\"grand-archives\">Grand Archives<\/a>.<\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Winged_Knight_Halberd"},{"id":"winged-knight-twinaxess","kind":"weapon","name":"Winged Knight Twinaxess","page":"Winged Knight Twinaxes","img":"assets/img/Winged_Knight_Twinaxes.webp","wtype":"Axe","group":"melee","paired":true,"atk":{"phys":122,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":20,"dex":12,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":45,"mag":30,"fire":25,"ltn":25,"dark":30},"stability":35,"weight":8.5,"durability":80,"skill":"Chain Spin","dmg_type":"Standard","cast":null,"fp":"8(-/10)","buy":null,"desc":"Paired beheading axes wielded by the Winged Knights, who swore themselves to the Angels.\nThese axes, more befitting of an executioner than a knight, are indented to fit the human body.\nSkill: Chain Spin\nSweep foes in a large spinning motion and use strong attack to continue the motion until stamina is exhausted.","boss_weapon":false,"avail":"<ul><li><a data-e=\"lothric-castle\">Lothric Castle<\/a><ul><li>Dropped by the twinaxe-wielding Winged Knight found in a small tower between the <a data-e=\"lothric-castle\">Lothric Castle<\/a> and the Dragon Barracks bonfires.<\/li><\/ul><\/li><li><a data-e=\"grand-archives\">Grand Archives<\/a><ul><li>Dropped by the twinaxe-wielding Gertrude's Knight found on top of the main dome.<\/li><\/ul><\/li><\/ul>","notes":"","url":"https://darksouls.fandom.com/wiki/Winged_Knight_Twinaxes"},{"id":"winged-spear","kind":"weapon","name":"Winged Spear","page":"Winged Spear (Dark Souls III)","img":"assets/img/Winged_Spear__Dark_Souls_III.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":95,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":12,"dex":15,"int":0,"fth":0},"scale":{"str":"D","dex":"C","int":"-","fth":"-"},"defs":{"phys":40,"mag":25,"fire":20,"ltn":20,"dark":25},"stability":20,"weight":6,"durability":70,"skill":"Charge","dmg_type":"Thrust","cast":null,"fp":"13(-/9)","buy":1500,"desc":"A long-hilted spear with wing lugs.\nLong reach, and can be used with shield up.\nSpear attacks are centered on thrusting, but can inflict high damage when timed with the end of an enemy's swing.\nSkill: Charge\nHold spear at waist and charge at foe. Use strong attack while charging to extend the length of the charge.","boss_weapon":false,"avail":"<p>Sold by <a data-e=\"unbreakable-patches\">Unbreakable Patches<\/a> for 1,500 souls.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Winged_Spear_(Dark_Souls_III)"},{"id":"witchs-locks","kind":"weapon","name":"Witch's Locks","page":"Witch's Locks","img":"assets/img/Witch_s_Locks.webp","wtype":"Whip","group":"melee","paired":false,"atk":{"phys":77,"mag":0,"fire":80,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":9,"dex":17,"int":12,"fth":12},"scale":{"str":"-","dex":"D","int":"C","fth":"C"},"defs":{"phys":30,"mag":15,"fire":20,"ltn":10,"dark":15},"stability":15,"weight":3,"durability":50,"skill":"Flame Whip","dmg_type":"Slash","cast":null,"fp":"18(-/-)","buy":null,"desc":"A whip fashioned from the black hair of a daughter of the Witch of Izalith, creator of the Flame of Chaos.\nThe long, shining locks woven together to create this whip are imbued with the essence of fire, which can be channeled through the use of its Skill.\nSkill: Flame Whip\nTemporarily coat the whip in fire, the self-same fire as that which consumed the Witch herself, it is said.","boss_weapon":false,"avail":"<p>Found inside a chest in the <a data-e=\"grand-archives\">Grand Archives<\/a>, in a secret room behind a moving bookcase in the darkened room on the second floor, past the large vat with wax. The bookcase's mechanism is triggered by a lever within the same room.<\/p>","notes":"<ul><li>The weapon's description may be a reference to Chaos Witch Quelaag, as she is the only Daughter of Chaos whose hair is seen by the player, and it is black in color.<\/li><\/ul><p><br><br><\/p>","url":"https://darksouls.fandom.com/wiki/Witch's_Locks"},{"id":"witchtree-branch","kind":"weapon","name":"Witchtree Branch","page":"Witchtree Branch (Dark Souls III)","img":"assets/img/Witchtree_Branch__Dark_Souls_III.webp","wtype":"Staff","group":"catalyst","paired":false,"atk":{"phys":57,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":7,"dex":0,"int":18,"fth":0},"scale":{"str":"E","dex":"-","int":"C","fth":"-"},"defs":{"phys":25,"mag":20,"fire":10,"ltn":10,"dark":15},"stability":10,"weight":2,"durability":40,"skill":"Steady Chant","dmg_type":"Strike","cast":100,"fp":"7(-/-)","buy":null,"desc":"The branch of a large, well-tended witchtree, used as a sorcery catalyst.\nWitchtree staves are customary in the far north, and allow for faster casting than ordinary catalysts.\nSkill: Steady Chant\nBoost the strength of sorceries for a very short period. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>.<\/p><p>From <a data-e=\"irithyll-of-the-boreal-valley\">Central Irithyll<\/a>, make way past the plaza with the fountain. To the left of the second Fire Witch there will be a small terrace with a Crystal Lizard. The banister on the right is illusory and will reveal a staircase once hit. Head down the stairs past a Pontiff Knight and toward a cell with a deranged Evangelist named Dorhys inside. The staff lies next to a tree on the right.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Witchtree_Branch_(Dark_Souls_III)"},{"id":"wolf-knights-greatshield","kind":"weapon","name":"Wolf Knight's Greatshield","page":"Wolf Knight's Greatshield","img":"assets/img/Wolf_Knight_s_Greatshield.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":124,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":30,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":68,"fire":65,"ltn":52,"dark":68},"stability":67,"weight":11,"durability":140,"skill":"Weapon Skill","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"Greatshield of a knight tainted by the dark of the Abyss, and master of the wolf's blood of Farron.\nBoasts consistent defense and divine protection against various status effects.\nSkill: Weapon Skill\nEquipping this shield in the left hand allows one to perform the Skill of the right hand weapon.","boss_weapon":false,"avail":"<p>Obtained by reaching Rank 2 in the <a data-e=\"watchdogs-of-farron\">Watchdogs of Farron<\/a> covenant.<\/p>","notes":"<ul><li>When equipped, it increases Bleed, Poison, Frost, and Curse resistances by 50. It has no effect on Toxic resistance.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Wolf_Knight's_Greatshield"},{"id":"wolf-knights-greatsword","kind":"weapon","name":"Wolf Knight's Greatsword","page":"Wolf Knight's Greatsword","img":"assets/img/Wolf_Knight_s_Greatsword.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":139,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":24,"dex":18,"int":0,"fth":0},"scale":{"str":"C","dex":"D","int":"-","fth":"-"},"defs":{"phys":55,"mag":40,"fire":35,"ltn":35,"dark":40},"stability":40,"weight":11.5,"durability":95,"skill":"Wolf Sword","dmg_type":"Standard/Thrust","cast":null,"fp":"-(19/23)","buy":10000,"desc":"Greatsword of a knight tainted by the dark of the Abyss, and master of the wolf's blood of Farron.\nThe wolf knight was the first Abyss Watcher, and his sword is more punishing against creations of the abyss.\nSkill: Wolf Sword\nWhile in stance, use normal attack for a low spinning slash, or strong attack to leap forward in a vertically-slashing somersault.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-the-blood-of-the-wolf\">Soul of the Blood of the Wolf<\/a> and 10,000 souls with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"<ul><li>Deals increased damage to abyssal enemies.<\/li><\/ul>","from_soul":[{"soul":"soul-of-the-blood-of-the-wolf","cost":"10,000 souls"}],"url":"https://darksouls.fandom.com/wiki/Wolf_Knight's_Greatsword"},{"id":"wolnirs-holy-sword","kind":"weapon","name":"Wolnir's Holy Sword","page":"Wolnir's Holy Sword","img":"assets/img/Wolnir_s_Holy_Sword.webp","wtype":"Greatsword","group":"melee","paired":false,"atk":{"phys":151,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":13,"dex":13,"int":0,"fth":13},"scale":{"str":"D","dex":"E","int":"-","fth":"D"},"defs":{"phys":45,"mag":35,"fire":30,"ltn":30,"dark":45},"stability":30,"weight":7.5,"durability":70,"skill":"Wrath of the Gods","dmg_type":"Standard","cast":null,"fp":"30(-/-)","buy":null,"desc":"A holy sword eroded by the Abyss. When Wolnir fell to the Abyss, he was gripped by a fear of true darkness, and pleaded to the gods for the first time.\nThis holy sword, together with three armlets stripped from the corpses of clerics, gave him some semblance of comfort.\nSkill: Wrath of the Gods\nThrust weapon into earth to emit powerful shockwave. The wrath of those swallowed by the Abyss is a thing to be wary of indeed.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-high-lord-wolnir\">Soul of High Lord Wolnir<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"","from_soul":[{"soul":"soul-of-high-lord-wolnir","cost":null}],"url":"https://darksouls.fandom.com/wiki/Wolnir's_Holy_Sword"},{"id":"wooden-shield","kind":"weapon","name":"Wooden Shield","page":"Wooden Shield (Dark Souls III)","img":"assets/img/Wooden_Shield__Dark_Souls_III.webp","wtype":"Medium Shield","group":"shield","paired":false,"atk":{"phys":78,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":8,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":57,"mag":66,"fire":48,"ltn":44,"dark":39},"stability":53,"weight":2.5,"durability":70,"skill":"Parry","dmg_type":"Strike","cast":null,"fp":null,"buy":null,"desc":"A vertically elongated wooden shield decorated with a white dragon.\nWooden shields are light, manageable, and offer relatively high magic absorption.\nSkill: Parry\nRepel an attack at the right time to follow up with a critical hit.","boss_weapon":false,"avail":"<ul><li>Starting equipment of the Mercenary class.<\/li><li>Dropped by Hollow Soldiers who wield them.<\/li><li><a data-e=\"road-of-sacrifices\">Road of Sacrifices<\/a><ul><li>Dropped by Sage's Prenticese.<\/li><\/ul><\/li><li><a data-e=\"cathedral-of-the-deep\">Cathedral of the Deep<\/a><ul><li>Dropped by Devouts of the Deep.<\/li><\/ul><\/li><\/ul>","notes":"<ul><li>The Wooden Shield has made an appearance in each <i>Dark Souls<\/i> game to date, and though the appearance was altered in <i>Dark Souls II<\/i> to have a lion painted on the front, the version in <i>Dark Souls III<\/i> uses a higher-quality model of the <a data-e=\"wooden-shield\">original<\/a> <i>Dark Souls<\/i> design.<\/li><\/ul>","url":"https://darksouls.fandom.com/wiki/Wooden_Shield_(Dark_Souls_III)"},{"id":"yhorms-great-machete","kind":"weapon","name":"Yhorm's Great Machete","page":"Yhorm's Great Machete","img":"assets/img/Yhorm_s_Great_Machete.webp","wtype":"Greataxe","group":"melee","paired":false,"atk":{"phys":185,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":38,"dex":10,"int":0,"fth":0},"scale":{"str":"C","dex":"-","int":"-","fth":"-"},"defs":{"phys":55,"mag":45,"fire":40,"ltn":40,"dark":45},"stability":40,"weight":19,"durability":140,"skill":"Warcry","dmg_type":"Standard","cast":null,"fp":"20(-/-)","buy":null,"desc":"Great machete wielded long ago by Yhorm the Giant.\nYhorm once lumbered on the frontlines with a greatshield. But one day, in place of his shield, a left-hand notch was added to his machete, enabling the smashing technique that would become the legacy of his later years.\nSkill: Warcry\nLet out a spirited warcry that temporarily boosts attack, and enables a crushing strong attack.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-yhorm-the-giant\">Soul of Yhorm the Giant<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"","from_soul":[{"soul":"soul-of-yhorm-the-giant","cost":null}],"url":"https://darksouls.fandom.com/wiki/Yhorm's_Great_Machete"},{"id":"yhorms-greatshield","kind":"weapon","name":"Yhorm's Greatshield","page":"Yhorm's Greatshield","img":"assets/img/Yhorm_s_Greatshield.webp","wtype":"Greatshield","group":"melee","paired":false,"atk":{"phys":132,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":40,"dex":0,"int":0,"fth":0},"scale":{"str":"D","dex":"-","int":"-","fth":"-"},"defs":{"phys":100,"mag":74,"fire":76,"ltn":63,"dark":74},"stability":73,"weight":20.5,"durability":205,"skill":"Shield Bash","dmg_type":"Strike","cast":null,"fp":"16(-/-)","buy":null,"desc":"Greatshield used long ago by Yhorm the Giant.\nIncreases the user's poise.\nAs a lord, Yhorm risked everything and fought unflinchingly as a one-man vanguard. Following the loss of the one he wished to protect, he forsook his shield.\nSkill: Shield Bash\nWithout lowering your guard, strike the enemy with the shield to knock them back or stagger them. Works while equipped in either hand.","boss_weapon":true,"avail":"<p>Obtained by transposing the <a data-e=\"soul-of-yhorm-the-giant\">Soul of Yhorm the Giant<\/a> with <a data-e=\"ludleth-of-courland\">Ludleth of Courland<\/a>.<\/p>","notes":"","from_soul":[{"soul":"soul-of-yhorm-the-giant","cost":null}],"url":"https://darksouls.fandom.com/wiki/Yhorm's_Greatshield"},{"id":"yorshkas-chime","kind":"weapon","name":"Yorshka's Chime","page":"Yorshka's Chime","img":"assets/img/Yorshka_s_Chime.webp","wtype":"Sacred Chime","group":"catalyst","paired":false,"atk":{"phys":54,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":3,"dex":0,"int":0,"fth":30},"scale":{"str":"D","dex":"-","int":"-","fth":"A"},"defs":{"phys":25,"mag":15,"fire":10,"ltn":20,"dark":15},"stability":10,"weight":0.5,"durability":60,"skill":"Gentle Prayer","dmg_type":"Strike","cast":124,"fp":"13(-/-)","buy":null,"desc":"A sacred chime belonging to Yorshka. Her brother, the former knight captain, presented her with this medium together with another gift: her name.\nThe ringing of the chime must have done much to soothe her loneliness.\nSkill: Gentle Prayer\nRecovers HP for a period of time, albeit extremely slowly. Works while equipped in either hand.","boss_weapon":false,"avail":"<p>Dropped by <a data-e=\"company-captain-yorshka\">Company Captain Yorshka<\/a> in <a data-e=\"anor-londo\">Anor Londo<\/a>.<\/p>","notes":"<ul><li>Can be traded with Pickle Pee in exchange for the <a data-e=\"hello-carving\">Help me! Carving<\/a>.<\/li><li>Since getting this item requires that the player kills <a data-e=\"company-captain-yorshka\">Captain Yorshka<\/a>, it should be noted that the <a data-e=\"darkmoon-blade\">Darkmoon Blade<\/a> and the <a data-e=\"darkmoon-ring\">Darkmoon Ring<\/a>, both rewards in the <a data-e=\"blade-of-the-darkmoon\">Blade of the Darkmoon<\/a> covenant, will not be available anymore in that playthrough, unless the player acquires both prior to killing her.<\/li><\/ul><p><br><br><\/p>","url":"https://darksouls.fandom.com/wiki/Yorshka's_Chime"},{"id":"yorshkas-spear","kind":"weapon","name":"Yorshka's Spear","page":"Yorshka's Spear","img":"assets/img/Yorshka_s_Spear.webp","wtype":"Spear","group":"melee","paired":false,"atk":{"phys":102,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":18,"dex":14,"int":0,"fth":13},"scale":{"str":"D","dex":"D","int":"-","fth":"D"},"defs":{"phys":40,"mag":65,"fire":60,"ltn":60,"dark":65},"stability":25,"weight":6.5,"durability":65,"skill":"Pacify","dmg_type":"Strike/Thrust","cast":null,"fp":"25(-/-)","buy":null,"desc":"This treasure, gifted to the Yorshka Church, is enchanted with a soporific spell, and was surreptitiously worshiped by Irithyll slaves.\nAs a weapon, it is part spear and part hammer, the former allowing thrusting, and the latter allowing strikes.\nSkill: Pacify\nWith a prayer and an offering of this spear, temporarily wear down enemy FP with each strike.","boss_weapon":false,"avail":"<p>Found in <a data-e=\"irithyll-of-the-boreal-valley\">Irithyll of the Boreal Valley<\/a>, in the darkened room located shortly past the graveyard behind the <a data-e=\"irithyll-of-the-boreal-valley\">Church of Yorshka<\/a>. Climb the ladder on the far-right and walk along the rafters until reaching the other end of the room. Drop down to an elevated platform with a chest that contains the weapon.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Yorshka's_Spear"},{"id":"zweihander","kind":"weapon","name":"Zweihander","page":"Zweihander (Dark Souls III)","img":"assets/img/Zweihander__Dark_Souls_III.webp","wtype":"Ultra Greatsword","group":"melee","paired":false,"atk":{"phys":145,"mag":0,"fire":0,"ltn":0,"dark":0},"aux":{"bld":0,"psn":0,"fst":0},"req":{"str":19,"dex":11,"int":0,"fth":0},"scale":{"str":"D","dex":"D","int":"-","fth":"-"},"defs":{"phys":50,"mag":40,"fire":35,"ltn":35,"dark":40},"stability":40,"weight":10,"durability":80,"skill":"Stomp","dmg_type":"Standard/Thrust","cast":null,"fp":"10(-/15)","buy":6000,"desc":"Ultra greatsword with a large, long blade. Wielded with two hands, yet still requiring great strength due to its weight.\nExecute powerful attacks that take advantage of its weight, or utilize its sharp blade in thrust attacks.\nSkill: Stomp\nUse one's weight to lunge forward with a low stance and increased poise, and follow with strong attack for an upward slash.","boss_weapon":false,"avail":"<p>Sold by <a data-e=\"greirat-of-the-undead-settlement\">Greirat<\/a> for 6,000 souls once he returns from his pillaging travel in the <a data-e=\"undead-settlement\">Undead Settlement<\/a>.<\/p>","notes":"","url":"https://darksouls.fandom.com/wiki/Zweihander_(Dark_Souls_III)"}]);
